window.COURSE = {"plannedLessons":240,"modules":[{"module":1,"hsk":"HSK1","title":"Основы произношения и пиньинь","summary":"После модуля ученик читает и записывает базовый пиньинь с тонами, применяет основные тональные изменения и различает ключевые китайские звуки. Ученик узнаёт первые иероглифы, ключи и уверенно читает простые фразы уровня HSK1.","lessons":[{"id":1,"title":"Пиньинь: карта китайского слога","duration":20,"goal":"Понимать, из каких частей состоит китайский слог, и читать пиньинь как подсказку к произношению.","theory":[{"heading":"Зачем нужен пиньинь","body":"Пиньинь — официальная запись китайских звуков латинскими буквами. Он не заменяет иероглифы, а помогает узнать произношение: 中国 читается Zhōngguó. Не пытайтесь читать буквы по-русски или по-английски: у системы свои правила."},{"heading":"Три части слога","body":"Обычный слог состоит из инициали в начале, финали после неё и тона над гласной: hǎo = h + ao + третий тон. Иногда инициали нет: ài начинается сразу с финали. Один иероглиф обычно соответствует одному слогу."},{"heading":"Слово может состоять из слогов","body":"В слове 你好 два слога: nǐ и hǎo. Произносите их по очереди, не сливая в русский ударный слог. Тон относится к каждому слогу отдельно."}],"vocab":[{"hanzi":"中国","pinyin":"Zhōngguó","ru":"Китай"},{"hanzi":"汉语","pinyin":"Hànyǔ","ru":"китайский язык"},{"hanzi":"人","pinyin":"rén","ru":"человек"},{"hanzi":"名字","pinyin":"míngzi","ru":"имя"},{"hanzi":"什么","pinyin":"shénme","ru":"что"},{"hanzi":"叫","pinyin":"jiào","ru":"зваться, называться"}],"grammar":[{"rule":"Строение слога: инициаль + финаль + тон","explain":"В pinyin сначала определяем начальный согласный, затем гласную часть и тон. У некоторых слогов начального согласного нет.","examples":[{"hanzi":"中国","pinyin":"Zhōngguó","ru":"Китай."},{"hanzi":"你叫什么名字？","pinyin":"Nǐ jiào shénme míngzi?","ru":"Как тебя зовут?"}]}],"dialogue":{"title":"Знакомство","lines":[{"speaker":"A","hanzi":"你叫什么名字？","pinyin":"Nǐ jiào shénme míngzi?","ru":"Как тебя зовут?"},{"speaker":"B","hanzi":"我叫安娜。","pinyin":"Wǒ jiào Ānnà.","ru":"Меня зовут Анна."},{"speaker":"A","hanzi":"你是中国人吗？","pinyin":"Nǐ shì Zhōngguó rén ma?","ru":"Ты китаец/китаянка?"},{"speaker":"B","hanzi":"不是，我学习汉语。","pinyin":"Bú shì, wǒ xuéxí Hànyǔ.","ru":"Нет, я изучаю китайский."}]},"exercises":[{"type":"choice","q":"Что обозначает знак тона в pinyin?","options":["Громкость голоса","Высоту и направление голоса","Длину слова"],"answer":1,"explain":"Тон показывает, как меняется высота голоса внутри слога."},{"type":"choice","q":"Сколько слогов в слове Hànyǔ?","options":["Один","Два","Три"],"answer":1,"explain":"Hàn и yǔ — два самостоятельных слога."},{"type":"match","q":"Соотнесите базовые слова и переводы.","pairs":[{"left":"人","right":"человек"},{"left":"名字","right":"имя"},{"left":"汉语","right":"китайский язык"}],"explain":"Каждая пара закрепляет базовую лексику урока."},{"type":"choice","q":"Что в слоге hǎo является финалью?","options":["h","ao","третий тон"],"answer":1,"explain":"h — инициаль, ao — финаль, а знак показывает третий тон."},{"type":"input","q":"Напишите пиньинь слова 中国.","answer":["zhōngguó","zhongguo"],"explain":"中国 читается Zhōngguó: это два слога."},{"type":"input","q":"Напишите пиньинь слова 叫.","answer":["jiào","jiao"],"explain":"В jiào начальная часть j, финаль iao и четвёртый тон."},{"type":"input","q":"Напишите pinyin слова 名字.","answer":["míngzi","mingzi"],"explain":"名字 читается míngzi: второй слог нейтральный."}],"homework":"Прочитайте вслух 中国, 汉语, 名字 по слогам. Подчеркните в тетради инициаль и обведите финаль в каждом слоге."},{"id":2,"title":"Пять тонов: четыре тона и нейтральный","duration":22,"goal":"Различать четыре основных тона и короткий нейтральный тон на знакомых словах.","theory":[{"heading":"Тон меняет значение","body":"В китайском высота голоса различает слова. На схеме: первый тон ровный высокий — mā; второй поднимается — má; третий сначала опускается, затем поднимается — mǎ; четвёртый резко падает — mà."},{"heading":"Нейтральный тон","body":"Нейтральный тон пишется без значка и произносится коротко, легко, без ударения. В māma второй слог ma нейтральный: не повторяйте высокий первый тон."},{"heading":"Как тренироваться","body":"Сначала произнесите тон на одном гласном, затем на целом слоге. Не заменяйте третий тон русской вопросительной интонацией: он начинается ниже обычного."}],"vocab":[{"hanzi":"妈妈","pinyin":"māma","ru":"мама","note":"второй слог — нейтральный"},{"hanzi":"爸爸","pinyin":"bàba","ru":"папа","note":"второй слог — нейтральный"},{"hanzi":"他","pinyin":"tā","ru":"он"},{"hanzi":"她","pinyin":"tā","ru":"она"},{"hanzi":"吗","pinyin":"ma","ru":"вопросительная частица","note":"нейтральный тон"},{"hanzi":"呢","pinyin":"ne","ru":"а, же","note":"нейтральный тон"}],"grammar":[{"rule":"Тон — часть слога","explain":"Тон нельзя пропускать: mā, má, mǎ и mà произносятся по-разному. Если значка нет, как в ma и ne, это обычно нейтральный тон.","examples":[{"hanzi":"妈妈好吗？","pinyin":"Māma hǎo ma?","ru":"Мама в порядке?"},{"hanzi":"爸爸呢？","pinyin":"Bàba ne?","ru":"А папа?"}]}],"dialogue":{"title":"Разговор о семье","lines":[{"speaker":"A","hanzi":"妈妈好吗？","pinyin":"Māma hǎo ma?","ru":"Мама в порядке?"},{"speaker":"B","hanzi":"妈妈很好。","pinyin":"Māma hěn hǎo.","ru":"Мама очень хорошо."},{"speaker":"A","hanzi":"爸爸呢？","pinyin":"Bàba ne?","ru":"А папа?"},{"speaker":"B","hanzi":"爸爸很好。","pinyin":"Bàba hěn hǎo.","ru":"Папа очень хорошо."}]},"exercises":[{"type":"choice","q":"Какой тон в слоге mǎ?","options":["Первый","Третий","Четвёртый"],"answer":1,"explain":"Знак ˇ над a обозначает третий тон."},{"type":"choice","q":"Как произносится нейтральный тон?","options":["Долго и с сильным ударением","Коротко и без собственного контура","Всегда как четвёртый тон"],"answer":1,"explain":"Нейтральный слог короткий и не получает сильного ударения."},{"type":"match","q":"Соотнесите запись и значение.","pairs":[{"left":"mǎ","right":"лошадь"},{"left":"mà","right":"ругать"},{"left":"ma","right":"вопросительная частица"}],"explain":"Разные тоны и отсутствие тона дают разные слоги."},{"type":"choice","q":"Какой знак обозначает четвёртый тон?","options":["¯","ˊ","ˋ"],"answer":2,"explain":"Четвёртый тон резко падает и обозначается знаком ˋ."},{"type":"input","q":"Напишите pinyin слова «мама».","answer":["māma","mama"],"explain":"Первый слог mā — первый тон, второй ma — нейтральный."},{"type":"input","q":"Напишите pinyin частицы 吗.","answer":["ma"],"explain":"У 吗 нейтральный тон, поэтому диакритики нет."},{"type":"input","q":"Напишите pinyin слова 爸爸.","answer":["bàba","baba"],"explain":"В 爸爸 первый слог четвёртого тона, второй — нейтральный."}],"homework":"Запишите и произнесите цепочку mā, má, mǎ, mà пять раз. Затем прочитайте 妈妈, 爸爸, 吗, сохраняя нейтральные слоги короткими."},{"id":3,"title":"Простые финали: a, o, e, i, u, ü","duration":22,"goal":"Произносить шесть простых финалей и ставить знак тона на нужную гласную.","theory":[{"heading":"Открываем рот по-разному","body":"Финаль a похожа на русское «а», o — на округлённое «о». Китайское e не равно русскому «е»: в одиночном ē оно звучит глубже, ближе к звуку между «ы» и «э». Слушайте образец и не добавляйте лишний согласный в конце."},{"heading":"Узкие гласные","body":"i похоже на русское «и», u — на «у». Для ü произнесите «и», но округлите губы как для «у»; язык остаётся впереди. Этот звук есть в немецком ü и французском u, но отсутствует в русском."},{"heading":"Куда ставить значок","body":"В финали из одной гласной знак тона стоит на ней: mā, wǒ, nǐ, lù, nǚ. В более длинных финалях правило разберём позже."}],"vocab":[{"hanzi":"大","pinyin":"dà","ru":"большой"},{"hanzi":"我","pinyin":"wǒ","ru":"я"},{"hanzi":"你","pinyin":"nǐ","ru":"ты"},{"hanzi":"书","pinyin":"shū","ru":"книга"},{"hanzi":"女儿","pinyin":"nǚ’ér","ru":"дочь"},{"hanzi":"五","pinyin":"wǔ","ru":"пять"}],"grammar":[{"rule":"Простая финаль несёт тон","explain":"В слогах dà, wǒ, nǐ, lù и nǚ тоновый знак стоит над единственной гласной финали.","examples":[{"hanzi":"我是女儿。","pinyin":"Wǒ shì nǚ’ér.","ru":"Я дочь."},{"hanzi":"你五岁吗？","pinyin":"Nǐ wǔ suì ma?","ru":"Тебе пять лет?"}]}],"dialogue":{"title":"О себе","lines":[{"speaker":"A","hanzi":"你是学生吗？","pinyin":"Nǐ shì xuésheng ma?","ru":"Ты студент?"},{"speaker":"B","hanzi":"是，我是学生。","pinyin":"Shì, wǒ shì xuésheng.","ru":"Да, я студент."},{"speaker":"A","hanzi":"你有女儿吗？","pinyin":"Nǐ yǒu nǚ’ér ma?","ru":"У тебя есть дочь?"},{"speaker":"B","hanzi":"没有。","pinyin":"Méi yǒu.","ru":"Нет."}]},"exercises":[{"type":"choice","q":"Как артикулировать ü?","options":["Как «у», язык отведён назад","Как «и» с округлёнными губами","Как русское «ы»"],"answer":1,"explain":"Для ü язык остаётся в позиции «и», а губы округляются."},{"type":"choice","q":"В каком слове есть финаль ü?","options":["你","路","女儿"],"answer":2,"explain":"Первый слог 女儿 — nǚ, с финалью ü."},{"type":"match","q":"Соотнесите слово и pinyin.","pairs":[{"left":"我","right":"wǒ"},{"left":"五","right":"wǔ"},{"left":"大","right":"dà"}],"explain":"В каждом случае тон стоит на единственной гласной."},{"type":"choice","q":"В каком слове есть звук ü?","options":["书","女儿","我"],"answer":1,"explain":"В первом слоге nǚ есть ü: язык как для «и», губы округлены."},{"type":"input","q":"Напишите pinyin слова 女儿.","answer":["nǚ’ér","nü’er","nǚer","nuer"],"explain":"Слоги nǚ и ér разделены апострофом; ü сохраняет две точки."},{"type":"input","q":"Напишите pinyin слова «я».","answer":["wǒ","wo"],"explain":"Иероглиф 我 читается wǒ, третий тон."},{"type":"input","q":"Напишите pinyin слова 书.","answer":["shū","shu"],"explain":"书 читается shū: финаль u и первый тон."}],"homework":"Перед зеркалом пять раз чередуйте i—ü и u—ü. Прочитайте вслух nǐ, lù, nǚ, следя за положением губ."},{"id":4,"title":"Губные инициали b, p, m, f","duration":20,"goal":"Различать придыхательные и непридыхательные губные инициали b, p, m, f.","theory":[{"heading":"b и p — не русские «б» и «п»","body":"Обе инициали произносятся без голоса, как мягкие русские «п». Разница в придыхании: после p слышен заметный выдох, после b почти нет. Поднесите ладонь ко рту: в pā выдох сильнее, чем в bā."},{"heading":"m и f","body":"m похоже на русское «м»: воздух идёт через нос. f похоже на «ф», но произносите его чётко, без добавления гласного после согласного."},{"heading":"Слушаем начало слога","body":"Инициаль занимает только начало слога; тон находится на гласной. В bàba b не становится звонким русским «б»."}],"vocab":[{"hanzi":"八","pinyin":"bā","ru":"восемь"},{"hanzi":"杯子","pinyin":"bēizi","ru":"чашка, стакан"},{"hanzi":"朋友","pinyin":"péngyou","ru":"друг"},{"hanzi":"苹果","pinyin":"píngguǒ","ru":"яблоко"},{"hanzi":"米饭","pinyin":"mǐfàn","ru":"рис, готовый рис"},{"hanzi":"飞机","pinyin":"fēijī","ru":"самолёт"}],"grammar":[{"rule":"Придыхание после p","explain":"После p идёт сильный выдох, после b — слабый. Голос начинается на финали, а не на инициативе.","examples":[{"hanzi":"八个苹果。","pinyin":"Bā ge píngguǒ.","ru":"Восемь яблок."},{"hanzi":"朋友买米饭。","pinyin":"Péngyou mǎi mǐfàn.","ru":"Друг покупает рис."}]}],"dialogue":{"title":"В магазине","lines":[{"speaker":"A","hanzi":"你买什么？","pinyin":"Nǐ mǎi shénme?","ru":"Что ты покупаешь?"},{"speaker":"B","hanzi":"我买苹果。","pinyin":"Wǒ mǎi píngguǒ.","ru":"Я покупаю яблоки."},{"speaker":"A","hanzi":"买几个？","pinyin":"Mǎi jǐ ge?","ru":"Сколько штук?"},{"speaker":"B","hanzi":"买八个。","pinyin":"Mǎi bā ge.","ru":"Покупаю восемь."}]},"exercises":[{"type":"choice","q":"Какая инициаль произносится с сильным выдохом?","options":["b","p","m"],"answer":1,"explain":"p — придыхательная инициаль; проверьте это ладонью у рта."},{"type":"choice","q":"Какая инициаль стоит в слове 米饭 mǐfàn?","options":["m","f","обе m и f"],"answer":2,"explain":"Первый слог начинается с m, второй — с f."},{"type":"match","q":"Соотнесите покупки и переводы.","pairs":[{"left":"杯子","right":"чашка, стакан"},{"left":"朋友","right":"друг"},{"left":"飞机","right":"самолёт"}],"explain":"Обратите внимание на начальные b, p и f."},{"type":"choice","q":"Какой звук есть в начале слова 飞机?","options":["b","p","f"],"answer":2,"explain":"飞机 начинается с f: это чёткий губно-зубной звук."},{"type":"input","q":"Напишите pinyin слова 苹果.","answer":["píngguǒ","pingguo"],"explain":"В 苹果 два слога: píng и guǒ."},{"type":"input","q":"Напишите pinyin числа 八.","answer":["bā","ba"],"explain":"八 произносится bā с первым тоном."},{"type":"input","q":"Напишите pinyin слова 米饭.","answer":["mǐfàn","mifan"],"explain":"米饭 состоит из mǐ и fàn; оба слога имеют тоны."}],"homework":"Скажите по десять раз bā—pā, держа ладонь у рта. Затем прочитайте 杯子, 苹果, 米饭 в медленном темпе."},{"id":5,"title":"Инициали d, t, n, l: кончик языка","duration":20,"goal":"Правильно ставить кончик языка для d, t, n, l и слышать придыхание t.","theory":[{"heading":"d и t","body":"Кончик языка касается бугорков за верхними зубами. d произносится без сильного выдоха, t — с придыханием; это ближе к двум вариантам русского «т», а не к паре «д—т». "},{"heading":"n и l","body":"При n воздух выходит через нос — как в русском «н». При l язык остаётся у верхних зубов, а воздух идёт по бокам языка: похоже на русское «л», но без сильного смягчения."},{"heading":"Не смешивайте инициали","body":"В китайском n и l могут различать слова. Произносите начальный согласный отдельно перед финалью: nǐ, lǎoshī."}],"vocab":[{"hanzi":"大","pinyin":"dà","ru":"большой"},{"hanzi":"天气","pinyin":"tiānqì","ru":"погода"},{"hanzi":"你","pinyin":"nǐ","ru":"ты"},{"hanzi":"老师","pinyin":"lǎoshī","ru":"учитель"},{"hanzi":"冷","pinyin":"lěng","ru":"холодный"},{"hanzi":"六","pinyin":"liù","ru":"шесть"}],"grammar":[{"rule":"Инициали d/t различаются выдохом","explain":"d и t имеют одинаковое место артикуляции, но t придыхательная. n и l произносятся в том же месте, с носовым или боковым выходом воздуха.","examples":[{"hanzi":"天气很冷。","pinyin":"Tiānqì hěn lěng.","ru":"Погода очень холодная."},{"hanzi":"老师，你好！","pinyin":"Lǎoshī, nǐ hǎo!","ru":"Учитель, здравствуйте!"}]}],"dialogue":{"title":"В классе","lines":[{"speaker":"A","hanzi":"老师，你好！","pinyin":"Lǎoshī, nǐ hǎo!","ru":"Учитель, здравствуйте!"},{"speaker":"B","hanzi":"你好！今天冷吗？","pinyin":"Nǐ hǎo! Jīntiān lěng ma?","ru":"Здравствуйте! Сегодня холодно?"},{"speaker":"A","hanzi":"很冷。","pinyin":"Hěn lěng.","ru":"Очень холодно."},{"speaker":"B","hanzi":"你喝热茶吗？","pinyin":"Nǐ hē rè chá ma?","ru":"Ты пьёшь горячий чай?"}]},"exercises":[{"type":"choice","q":"Какой звук в паре d/t имеет придыхание?","options":["d","t","n"],"answer":1,"explain":"После t слышен сильный поток воздуха."},{"type":"choice","q":"Какая инициаль носовая?","options":["l","n","d"],"answer":1,"explain":"При n воздух выходит через нос."},{"type":"match","q":"Соотнесите слова о погоде и числа.","pairs":[{"left":"天气","right":"погода"},{"left":"冷","right":"холодный"},{"left":"六","right":"шесть"}],"explain":"Закрепите инициали t, l и l."},{"type":"choice","q":"Какой звук стоит в начале слова 天气?","options":["d","t","l"],"answer":1,"explain":"天气 начинается с придыхательного t."},{"type":"input","q":"Напишите pinyin слова 老师.","answer":["lǎoshī","laoshi"],"explain":"老师 читается lǎoshī: третий и первый тоны."},{"type":"input","q":"Напишите pinyin слова 你.","answer":["nǐ","ni"],"explain":"你 читается nǐ, третий тон."},{"type":"input","q":"Напишите pinyin числа 六.","answer":["liù","liu"],"explain":"六 читается liù: четвёртый тон стоит над u."}],"homework":"Сравните пары dā—tā и nǐ—lǐ по восемь раз. Запишите 老师 и 天气 с тоновыми знаками."},{"id":6,"title":"Заднеязычные g, k, h","duration":20,"goal":"Произносить g, k и h в китайской позиции и различать g/k по придыханию.","theory":[{"heading":"Где работает язык","body":"Для g и k задняя часть языка поднимается к мягкому нёбу. g — без заметного выдоха, k — с сильным выдохом. Не произносите g как звонкое русское «г»: голос появляется на гласной."},{"heading":"Китайское h","body":"h — щелевой звук, похожий на более хриплое русское «х». В слове hē воздух проходит через щель в глубине рта; не заменяйте его русским «г». "},{"heading":"Тренировка контраста","body":"Сначала скажите gā—kā, затем gē—kē. Ладонь у рта снова поможет почувствовать разницу."}],"vocab":[{"hanzi":"高兴","pinyin":"gāoxìng","ru":"рад, довольный"},{"hanzi":"狗","pinyin":"gǒu","ru":"собака"},{"hanzi":"看","pinyin":"kàn","ru":"смотреть"},{"hanzi":"可以","pinyin":"kěyǐ","ru":"можно"},{"hanzi":"喝","pinyin":"hē","ru":"пить"},{"hanzi":"好","pinyin":"hǎo","ru":"хороший; хорошо"}],"grammar":[{"rule":"Заднеязычные инициали","explain":"g и k образуются в глубине рта; k придыхательная. h — щелевой звук в той же области и не имеет взрыва.","examples":[{"hanzi":"我看狗。","pinyin":"Wǒ kàn gǒu.","ru":"Я смотрю на собаку."},{"hanzi":"可以喝茶。","pinyin":"Kěyǐ hē chá.","ru":"Можно пить чай."}]}],"dialogue":{"title":"После занятия","lines":[{"speaker":"A","hanzi":"你高兴吗？","pinyin":"Nǐ gāoxìng ma?","ru":"Ты рад?"},{"speaker":"B","hanzi":"很高兴。","pinyin":"Hěn gāoxìng.","ru":"Очень рад."},{"speaker":"A","hanzi":"你看狗吗？","pinyin":"Nǐ kàn gǒu ma?","ru":"Ты смотришь на собаку?"},{"speaker":"B","hanzi":"看。狗很好。","pinyin":"Kàn. Gǒu hěn hǎo.","ru":"Смотрю. Собака очень хорошая."}]},"exercises":[{"type":"choice","q":"Как различаются g и k?","options":["Звонкостью","Силой придыхания","Длиной гласной"],"answer":1,"explain":"После k выдох заметнее, чем после g."},{"type":"choice","q":"Какая инициаль есть в слове 可以 kěyǐ?","options":["g","k","h"],"answer":1,"explain":"Первый слог 可以 начинается с k."},{"type":"match","q":"Соотнесите действия и предмет.","pairs":[{"left":"狗","right":"собака"},{"left":"看","right":"смотреть"},{"left":"喝","right":"пить"}],"explain":"Слова помогают потренировать все три инициали урока."},{"type":"choice","q":"Какой звук стоит в начале слова 喝?","options":["g","k","h"],"answer":2,"explain":"喝 начинается с h — глубокого щелевого звука."},{"type":"input","q":"Напишите pinyin слова 高兴.","answer":["gāoxìng","gaoxing"],"explain":"高兴 состоит из gāo и xìng."},{"type":"input","q":"Напишите pinyin слова 好.","answer":["hǎo","hao"],"explain":"好 читается hǎo, третий тон."},{"type":"input","q":"Напишите pinyin слова 可以.","answer":["kěyǐ","keyi"],"explain":"可以: kě + yǐ, оба слога с третьим тоном."}],"homework":"Проговорите gā—kā десять раз, проверяя выдох. Прочитайте вслух 看狗, 喝茶, 很高兴."},{"id":7,"title":"Передненёбные j, q, x и секрет ü","duration":23,"goal":"Различать j, q, x и применять правило записи ü как u после j, q и x.","theory":[{"heading":"Не «дж», не «ч» и не «ш»","body":"j, q и x произносятся передней частью языка у твёрдого нёба. j — без придыхания, q — с придыханием, x — мягкая щель; приблизительно они напоминают очень мягкие «тсь», «тсьх» и «сь», но русских точных аналогов нет."},{"heading":"Почему в слове xǔ написано u","body":"После j, q, x финаль ü на письме теряет две точки: jū, qù, xǔ. Звук остаётся ü: произнесите «и» с округлёнными губами. В слове 女 nǚ точки сохраняются."},{"heading":"Не путайте с zh/ch/sh","body":"j/q/x произносятся с языком ближе к зубам и нёбу, чем zh/ch/sh. Для них губы не вытягиваются вперёд."}],"vocab":[{"hanzi":"几","pinyin":"jǐ","ru":"сколько"},{"hanzi":"九","pinyin":"jiǔ","ru":"девять"},{"hanzi":"去","pinyin":"qù","ru":"идти"},{"hanzi":"学习","pinyin":"xuéxí","ru":"учиться, изучать"},{"hanzi":"学校","pinyin":"xuéxiào","ru":"школа"},{"hanzi":"小姐","pinyin":"xiǎojiě","ru":"госпожа, мисс"}],"grammar":[{"rule":"ü записывается как u после j/q/x","explain":"В записях jū, qù и xǔ буква u обозначает звук ü. Две точки не пишутся только потому, что после j, q, x другого u быть не может.","examples":[{"hanzi":"我去学校。","pinyin":"Wǒ qù xuéxiào.","ru":"Я иду в школу."},{"hanzi":"你学习汉语吗？","pinyin":"Nǐ xuéxí Hànyǔ ma?","ru":"Ты изучаешь китайский?"}]}],"dialogue":{"title":"У входа в школу","lines":[{"speaker":"A","hanzi":"小姐，你去学校吗？","pinyin":"Xiǎojiě, nǐ qù xuéxiào ma?","ru":"Мисс, вы идёте в школу?"},{"speaker":"B","hanzi":"去，我学习汉语。","pinyin":"Qù, wǒ xuéxí Hànyǔ.","ru":"Да, я иду, изучаю китайский."},{"speaker":"A","hanzi":"你几岁？","pinyin":"Nǐ jǐ suì?","ru":"Сколько тебе лет?"},{"speaker":"B","hanzi":"我九岁。","pinyin":"Wǒ jiǔ suì.","ru":"Мне девять лет."}]},"exercises":[{"type":"choice","q":"Какой звук обозначает u в qù?","options":["u","ü","o"],"answer":1,"explain":"После q буква u всегда читается как ü."},{"type":"choice","q":"Какая из j, q, x произносится с придыханием?","options":["j","q","x"],"answer":1,"explain":"q произносится с сильным выдохом."},{"type":"match","q":"Соотнесите слова об учёбе и значения.","pairs":[{"left":"几","right":"сколько"},{"left":"学习","right":"учиться"},{"left":"学校","right":"школа"}],"explain":"Все эти слова содержат инициативы j, q или x."},{"type":"choice","q":"После какой инициали ü пишется как u?","options":["n","q","l"],"answer":1,"explain":"После q буква u обозначает ü, поэтому qù звучит с округлёнными губами."},{"type":"input","q":"Напишите pinyin слова 去.","answer":["qù","qu"],"explain":"去 читается qù, четвёртый тон; звук гласной — ü."},{"type":"input","q":"Напишите pinyin слова 小姐.","answer":["xiǎojiě","xiaojie"],"explain":"小姐: xiǎo + jiě, оба слога с третьим тоном."},{"type":"input","q":"Напишите pinyin слова 学习.","answer":["xuéxí","xuexi"],"explain":"学习: xué + xí; после x буква u читается как ü."}],"homework":"Скажите jī—qī—xī, затем jū—qù—xǔ. В тетради объясните одним предложением, почему в qù нет точек над u."},{"id":8,"title":"Свистящие z, c, s","duration":20,"goal":"Произносить z, c, s без русской мягкости и отличать c по придыханию.","theory":[{"heading":"Положение языка","body":"z, c и s образуются у зубов: кончик языка направлен вниз или близко к нижним зубам. z напоминает слитное «тс», c — «тс» с сильным выдохом, s похоже на чёткое русское «с». "},{"heading":"Не добавляйте гласную","body":"В слоге zì буква z — один цельный звук, а не два слога «т» и «с». После z/c/s финаль i имеет особое краткое звучание, не равное обычному русскому «и». "},{"heading":"Проверка выдоха","body":"Контраст z—c такой же, как b—p или d—t: у c выдох сильнее. s — щелевой, без взрыва."}],"vocab":[{"hanzi":"字","pinyin":"zì","ru":"иероглиф; буква"},{"hanzi":"坐","pinyin":"zuò","ru":"сидеть"},{"hanzi":"菜","pinyin":"cài","ru":"блюдо, овощи"},{"hanzi":"岁","pinyin":"suì","ru":"лет (о возрасте)"},{"hanzi":"三","pinyin":"sān","ru":"три"},{"hanzi":"四","pinyin":"sì","ru":"четыре"}],"grammar":[{"rule":"Инициали z/c/s у зубов","explain":"z — непредыхательная аффриката, c — придыхательная, s — щелевой звук. В слогах zì и sì i читается не как обычное i.","examples":[{"hanzi":"我写三个字。","pinyin":"Wǒ xiě sān ge zì.","ru":"Я пишу три иероглифа."},{"hanzi":"请坐。","pinyin":"Qǐng zuò.","ru":"Пожалуйста, садитесь."}]}],"dialogue":{"title":"В аудитории","lines":[{"speaker":"A","hanzi":"请坐。","pinyin":"Qǐng zuò.","ru":"Пожалуйста, садитесь."},{"speaker":"B","hanzi":"谢谢老师。","pinyin":"Xièxie lǎoshī.","ru":"Спасибо, учитель."},{"speaker":"A","hanzi":"你写几个字？","pinyin":"Nǐ xiě jǐ ge zì?","ru":"Сколько иероглифов ты пишешь?"},{"speaker":"B","hanzi":"我写三个字。","pinyin":"Wǒ xiě sān ge zì.","ru":"Я пишу три иероглифа."}]},"exercises":[{"type":"choice","q":"Какая инициаль произносится с придыханием?","options":["z","c","s"],"answer":1,"explain":"c — вариант с сильным выдохом."},{"type":"choice","q":"Где образуются z, c, s?","options":["У зубов","В глубине горла","С губами"],"answer":0,"explain":"Это передние, «свистящие» инициали."},{"type":"match","q":"Соотнесите слова со свистящими и переводы.","pairs":[{"left":"字","right":"иероглиф"},{"left":"菜","right":"блюдо, овощи"},{"left":"四","right":"четыре"}],"explain":"Тренируйте начальные z, c и s вместе с тонами."},{"type":"choice","q":"Какой звук в начале слова 三?","options":["z","c","s"],"answer":2,"explain":"三 начинается с s, обычного щелевого «с». "},{"type":"input","q":"Напишите pinyin слова 坐.","answer":["zuò","zuo"],"explain":"坐 читается zuò, четвёртый тон."},{"type":"input","q":"Напишите pinyin числа 三.","answer":["sān","san"],"explain":"三 читается sān, первый тон."},{"type":"input","q":"Напишите pinyin слова 四.","answer":["sì","si"],"explain":"四 читается sì, четвёртый тон."}],"homework":"Прочитайте zī—cī—sī и zì—cài—sān. Затем скажите 请坐, сохраняя чёткое z в zuò."},{"id":9,"title":"Шипящие zh, ch, sh, r","duration":22,"goal":"Различать ретрофлексные инициали zh, ch, sh, r и не смешивать их со свистящими.","theory":[{"heading":"Язык чуть назад","body":"В zh, ch, sh, r кончик языка слегка загибается назад к твёрдому нёбу. zh похоже на твёрдое «дж» без голоса в начале, ch — на «ч» с выдохом, sh — на твёрдое «ш». "},{"heading":"Особое r","body":"Китайское r не похоже на русское раскатистое «р». Это звук между русскими «ж» и «р», произнесённый с языком, отведённым назад. В начале учитесь узнавать его на слове rén."},{"heading":"Сравнение с z/c/s","body":"Для z/c/s язык остаётся впереди, для zh/ch/sh/r он отходит назад. Почувствуйте разницу на парах zì—zhì и cài—chā."}],"vocab":[{"hanzi":"中国","pinyin":"Zhōngguó","ru":"Китай"},{"hanzi":"吃","pinyin":"chī","ru":"есть"},{"hanzi":"书","pinyin":"shū","ru":"книга"},{"hanzi":"十","pinyin":"shí","ru":"десять"},{"hanzi":"是","pinyin":"shì","ru":"быть; являться"},{"hanzi":"人","pinyin":"rén","ru":"человек"}],"grammar":[{"rule":"Ретрофлексные инициали","explain":"Сочетания zh, ch и sh — это по одному звуку, а не две буквы. ch придыхательная, zh нет; r читается не как русское «р».","examples":[{"hanzi":"我是中国人。","pinyin":"Wǒ shì Zhōngguó rén.","ru":"Я китаец/китаянка."},{"hanzi":"他吃十个苹果。","pinyin":"Tā chī shí ge píngguǒ.","ru":"Он ест десять яблок."}]}],"dialogue":{"title":"О книге","lines":[{"speaker":"A","hanzi":"这是什么？","pinyin":"Zhè shì shénme?","ru":"Что это?"},{"speaker":"B","hanzi":"这是书。","pinyin":"Zhè shì shū.","ru":"Это книга."},{"speaker":"A","hanzi":"谁看书？","pinyin":"Shéi kàn shū?","ru":"Кто читает книгу?"},{"speaker":"B","hanzi":"中国老师看书。","pinyin":"Zhōngguó lǎoshī kàn shū.","ru":"Китайский учитель читает книгу."}]},"exercises":[{"type":"choice","q":"Какая инициаль в chī придыхательная?","options":["zh","ch","sh"],"answer":1,"explain":"ch произносится со слышимым выдохом."},{"type":"choice","q":"Как записано слово «Китай»?","options":["Zōngguó","Zhōngguó","Chōngguó"],"answer":1,"explain":"Первый слог начинается с zh и имеет первый тон: Zhōng."},{"type":"match","q":"Соотнесите шипящие слова и переводы.","pairs":[{"left":"吃","right":"есть"},{"left":"书","right":"книга"},{"left":"十","right":"десять"}],"explain":"Слова тренируют ch, sh и sh."},{"type":"choice","q":"Какая запись передаёт один звук, а не два?","options":["z + h","zh","s + h"],"answer":1,"explain":"zh — одна ретрофлексная инициаль, а не два отдельных звука."},{"type":"input","q":"Напишите pinyin слова 人.","answer":["rén","ren"],"explain":"人 читается rén: китайское r не раскатывается как русское «р»."},{"type":"input","q":"Напишите pinyin слова 是.","answer":["shì","shi"],"explain":"是 читается shì, четвёртый тон."},{"type":"input","q":"Напишите pinyin слова 吃.","answer":["chī","chi"],"explain":"吃 читается chī: ch придыхательная, тон первый."}],"homework":"Трижды прочитайте zì—zhì, cī—chī, sī—shī. Затем медленно скажите 我是中国人."},{"id":10,"title":"Составные финали ai, ei, ao, ou","duration":22,"goal":"Читать распространённые составные финали и правильно размещать в них тоновые знаки.","theory":[{"heading":"Гласные в одной финали","body":"ai, ei, ao и ou — это одна финаль внутри одного слога, а не два слога. В ai и ao голос плавно движется от a к i/o; в ei — от e к i; в ou — от o к u."},{"heading":"Правило тонового знака","body":"В финалях ai, ei, ao знак стоит на a или e: hǎo, zài, léi. В ou знак ставится на o: dōu. Запомните приоритет гласных a, o, e; если их нет, знак обычно получает последняя гласная."},{"heading":"Не дробите слова","body":"В lǎoshī первый слог — lǎo, а не «ла-о». Произносите финаль как единое скольжение и только потом переходите к следующему слогу."}],"vocab":[{"hanzi":"老师","pinyin":"lǎoshī","ru":"учитель"},{"hanzi":"再见","pinyin":"zàijiàn","ru":"до свидания"},{"hanzi":"都","pinyin":"dōu","ru":"все; всё"},{"hanzi":"杯子","pinyin":"bēizi","ru":"чашка, стакан"},{"hanzi":"水","pinyin":"shuǐ","ru":"вода"},{"hanzi":"回","pinyin":"huí","ru":"возвращаться"}],"grammar":[{"rule":"Тоновый знак в ai/ei/ao/ou","explain":"В ai, ei, ao знак ставится на a или e; в ou — на o. Финаль остаётся одной частью слога.","examples":[{"hanzi":"老师喝水。","pinyin":"Lǎoshī hē shuǐ.","ru":"Учитель пьёт воду."},{"hanzi":"我们都回家。","pinyin":"Wǒmen dōu huí jiā.","ru":"Мы все возвращаемся домой."}]}],"dialogue":{"title":"Прощание","lines":[{"speaker":"A","hanzi":"老师，再见！","pinyin":"Lǎoshī, zàijiàn!","ru":"Учитель, до свидания!"},{"speaker":"B","hanzi":"再见！","pinyin":"Zàijiàn!","ru":"До свидания!"},{"speaker":"A","hanzi":"你回家吗？","pinyin":"Nǐ huí jiā ma?","ru":"Ты возвращаешься домой?"},{"speaker":"B","hanzi":"对，我回家。","pinyin":"Duì, wǒ huí jiā.","ru":"Да, я возвращаюсь домой."}]},"exercises":[{"type":"choice","q":"На какой букве стоит знак в dōu?","options":["d","o","u"],"answer":1,"explain":"В финали ou тоновый знак ставится на o."},{"type":"choice","q":"Сколько слогов в lǎoshī?","options":["Один","Два","Три"],"answer":1,"explain":"lǎo и shī — два слога; ao не образует отдельный слог."},{"type":"match","q":"Соотнесите слова с составными финалями.","pairs":[{"left":"都","right":"все"},{"left":"水","right":"вода"},{"left":"回","right":"возвращаться"}],"explain":"В словах dōu и huí есть составные финали."},{"type":"choice","q":"На какой гласной тон в hǎo?","options":["a","i","o"],"answer":0,"explain":"В финали ao тоновый знак ставится на a."},{"type":"input","q":"Напишите pinyin слова 再见.","answer":["zàijiàn","zaijian"],"explain":"再见 читается zàijiàn: в первом слоге финаль ai."},{"type":"input","q":"Введите pinyin для 老师.","answer":["lǎoshī","laoshi"],"explain":"В lǎo знак третьего тона стоит на a."},{"type":"input","q":"Напишите pinyin слова 都.","answer":["dōu","dou"],"explain":"都 читается dōu: в ou тон стоит на o."}],"homework":"Выпишите финали из слов 老师, 再见, 都, 回. Произнесите каждую финаль слитно, без паузы внутри."},{"id":11,"title":"Финали с -n: an, en, in, un","duration":22,"goal":"Произносить финали с носовым окончанием -n и отличать их от финалей с -ng.","theory":[{"heading":"Куда идёт язык","body":"В финалях an, en, in, un звук n произносится кончиком языка у верхних зубов, как русское «н». Финаль заканчивается носовым звуком, но не добавляйте после него отдельную гласную."},{"heading":"Короткое сравнение","body":"В an рот раскрыт шире, чем в en; в in слышится переднее i. В un буква u после обычной инициали звучит как u: wèn, nín, hěn, kūn — произносите финаль одним движением."},{"heading":"-n и -ng не равны","body":"В -n язык касается нёба, а в -ng задняя часть языка поднимается глубже. Сейчас закрепите -n; -ng разберём в следующем уроке."}],"vocab":[{"hanzi":"三","pinyin":"sān","ru":"три"},{"hanzi":"很","pinyin":"hěn","ru":"очень"},{"hanzi":"您","pinyin":"nín","ru":"Вы","note":"вежливая форма «вы»"},{"hanzi":"门","pinyin":"mén","ru":"дверь"},{"hanzi":"分钟","pinyin":"fēnzhōng","ru":"минута"},{"hanzi":"本","pinyin":"běn","ru":"счётное слово для книг"}],"grammar":[{"rule":"Финали an/en/in/un оканчиваются на -n","explain":"В конце -n кончик языка касается области за верхними зубами. Не путайте его с более глубоким -ng.","examples":[{"hanzi":"我有三本书。","pinyin":"Wǒ yǒu sān běn shū.","ru":"У меня есть три книги."},{"hanzi":"您很忙吗？","pinyin":"Nín hěn máng ma?","ru":"Вы очень заняты?"}]}],"dialogue":{"title":"У двери","lines":[{"speaker":"A","hanzi":"老师，您好吗？","pinyin":"Lǎoshī, nín hǎo ma?","ru":"Учитель, как вы?"},{"speaker":"B","hanzi":"我很好。","pinyin":"Wǒ hěn hǎo.","ru":"Я очень хорошо."},{"speaker":"A","hanzi":"门在哪儿？","pinyin":"Mén zài nǎr?","ru":"Где дверь?"},{"speaker":"B","hanzi":"门在那儿。","pinyin":"Mén zài nàr.","ru":"Дверь там."}]},"exercises":[{"type":"choice","q":"Как образуется конечный звук в hěn?","options":["Язык у верхних зубов","Губы сомкнуты","Язык глубоко у мягкого нёба"],"answer":0,"explain":"В финали -n кончик языка касается области за верхними зубами."},{"type":"choice","q":"В каком слове есть финаль in?","options":["很","您","三"],"answer":1,"explain":"您 читается nín: его финаль — in."},{"type":"match","q":"Соотнесите финали -n и значения слов.","pairs":[{"left":"三","right":"три"},{"left":"门","right":"дверь"},{"left":"分钟","right":"минута"}],"explain":"В этих словах есть финали с -n."},{"type":"choice","q":"Какая финаль в слове 三 sān?","options":["an","ang","in"],"answer":0,"explain":"В sān конечный звук -n; это финаль an."},{"type":"input","q":"Напишите pinyin слова 本.","answer":["běn","ben"],"explain":"本 читается běn с финалью en."},{"type":"input","q":"Напишите pinyin слова 很.","answer":["hěn","hen"],"explain":"很 читается hěn, третий тон."},{"type":"input","q":"Напишите pinyin слова 门.","answer":["mén","men"],"explain":"门 читается mén: финаль en и второй тон."}],"homework":"Произнесите sān—hěn—nín—běn по пять раз. Положите кончик языка за верхние зубы в конце каждого слога."},{"id":12,"title":"Финали с -ng: ang, eng, ing, ong","duration":22,"goal":"Произносить глубокие носовые финали -ng и отличать их от -n.","theory":[{"heading":"Носовой звук глубже","body":"В ang, eng, ing, ong конечный -ng образуется задней частью языка у мягкого нёба. Кончик языка не касается верхних зубов. Русское «нг» — лишь приблизительная подсказка: не произносите отдельное «г». "},{"heading":"Четыре частые финали","body":"ang широкая и открытая, eng более центральная, ing начинается с i, ong — с округлённого o. В píng, lěng и zhōng звук в конце должен быть единым носовым окончанием."},{"heading":"Сравнивайте парами","body":"Скажите hěn—hěng и mén—méng: в -n язык идёт вперёд, в -ng — назад. Эта разница важна для понятной речи."}],"vocab":[{"hanzi":"中国","pinyin":"Zhōngguó","ru":"Китай"},{"hanzi":"学生","pinyin":"xuésheng","ru":"студент"},{"hanzi":"朋友","pinyin":"péngyou","ru":"друг"},{"hanzi":"冷","pinyin":"lěng","ru":"холодный"},{"hanzi":"名字","pinyin":"míngzi","ru":"имя"},{"hanzi":"东西","pinyin":"dōngxi","ru":"вещь"}],"grammar":[{"rule":"Финали ang/eng/ing/ong оканчиваются на -ng","explain":"При -ng работает задняя часть языка, а не кончик. Не добавляйте в конце отдельный звук «г».","examples":[{"hanzi":"学生很高兴。","pinyin":"Xuésheng hěn gāoxìng.","ru":"Студент очень рад."},{"hanzi":"这是什么东西？","pinyin":"Zhè shì shénme dōngxi?","ru":"Что это за вещь?"}]}],"dialogue":{"title":"Новая вещь","lines":[{"speaker":"A","hanzi":"这是什么东西？","pinyin":"Zhè shì shénme dōngxi?","ru":"Что это за вещь?"},{"speaker":"B","hanzi":"这是朋友的杯子。","pinyin":"Zhè shì péngyou de bēizi.","ru":"Это чашка друга."},{"speaker":"A","hanzi":"朋友在中国吗？","pinyin":"Péngyou zài Zhōngguó ma?","ru":"Друг в Китае?"},{"speaker":"B","hanzi":"在。","pinyin":"Zài.","ru":"Да, там."}]},"exercises":[{"type":"choice","q":"Где работает язык в конечном -ng?","options":["У верхних зубов","В глубине рта, у мягкого нёба","На нижней губе"],"answer":1,"explain":"Для -ng задняя часть языка поднимается к мягкому нёбу."},{"type":"choice","q":"В каком слове есть финаль ong?","options":["名字","中国","冷"],"answer":1,"explain":"Первый слог 中国 — Zhōng, с финалью ong."},{"type":"match","q":"Соотнесите носовые слова и переводы.","pairs":[{"left":"冷","right":"холодный"},{"left":"东西","right":"вещь"},{"left":"学生","right":"студент"}],"explain":"Финали -ng встречаются в lěng, dōng и sheng."},{"type":"choice","q":"Какая финаль в слове 中国 Zhōngguó?","options":["ong","on","ang"],"answer":0,"explain":"В Zhōng конечное -ng образуется глубоко в полости рта."},{"type":"input","q":"Введите pinyin для 名字.","answer":["míngzi","mingzi"],"explain":"Первый слог 名 читается míng с финалью ing."},{"type":"input","q":"Напишите pinyin слова 朋友.","answer":["péngyou","pengyou"],"explain":"Первый слог 朋 читается péng, финаль eng."},{"type":"input","q":"Напишите pinyin слова 东西.","answer":["dōngxi","dongxi"],"explain":"东西: dōng + xi; второй слог нейтральный."}],"homework":"Прочитайте пары hěn—lěng и mén—míng. Затем запишите четыре финали: ang, eng, ing, ong и приведите по слову к двум из них."},{"id":13,"title":"Сложные финали с i- и u-","duration":24,"goal":"Читать финали ia, ie, iao, ua, uo, uai как единый слог и ставить в них тоны.","theory":[{"heading":"Начальный скольжащий звук","body":"В ia, ie, iao сначала очень кратко слышится i, затем основная гласная. В ua, uo, uai сначала кратко звучит u. Не делайте из iao три слога: xiào — один слог."},{"heading":"Тоны в сложных финалях","body":"Знак тона следует общему правилу: в ia, iao и ua ставим его на a; в ie — на e; в uo — на o; в uai — на a. Поэтому: jiā, xiě, xiào, huá, guó, kuài."},{"heading":"Слова для беглости","body":"В китайских словах такие финали часто соединяют части слова: xuéxiào, xiǎo, guó. Сначала читайте слоги медленно, затем соединяйте их без потери тонов."}],"vocab":[{"hanzi":"家","pinyin":"jiā","ru":"дом; семья"},{"hanzi":"写","pinyin":"xiě","ru":"писать"},{"hanzi":"小","pinyin":"xiǎo","ru":"маленький"},{"hanzi":"学校","pinyin":"xuéxiào","ru":"школа"},{"hanzi":"桌子","pinyin":"zhuōzi","ru":"стол"},{"hanzi":"块","pinyin":"kuài","ru":"юань; кусок"}],"grammar":[{"rule":"Сложная финаль — один слог","explain":"ia, ie, iao, ua, uo и uai не делятся на слоги. Тоновый знак ставится на главную гласную согласно правилу a/o/e.","examples":[{"hanzi":"我写汉字。","pinyin":"Wǒ xiě Hànzì.","ru":"Я пишу китайские иероглифы."},{"hanzi":"学校很小。","pinyin":"Xuéxiào hěn xiǎo.","ru":"Школа очень маленькая."}]}],"dialogue":{"title":"О школе","lines":[{"speaker":"A","hanzi":"学校在哪儿？","pinyin":"Xuéxiào zài nǎr?","ru":"Где школа?"},{"speaker":"B","hanzi":"学校在这儿。","pinyin":"Xuéxiào zài zhèr.","ru":"Школа здесь."},{"speaker":"A","hanzi":"学校大吗？","pinyin":"Xuéxiào dà ma?","ru":"Школа большая?"},{"speaker":"B","hanzi":"不大，很小。","pinyin":"Bú dà, hěn xiǎo.","ru":"Не большая, очень маленькая."}]},"exercises":[{"type":"choice","q":"На какой гласной стоит тон в xiǎo?","options":["i","a","o"],"answer":1,"explain":"В финали iao приоритет у a."},{"type":"choice","q":"Сколько слогов в xiào?","options":["Один","Два","Три"],"answer":0,"explain":"xiao — одна сложная финаль в одном слоге."},{"type":"match","q":"Соотнесите сложные финали и переводы.","pairs":[{"left":"家","right":"дом, семья"},{"left":"小","right":"маленький"},{"left":"块","right":"юань; кусок"}],"explain":"В jiā, xiǎo и kuài — сложные финали."},{"type":"choice","q":"Какая финаль в первом слоге 桌子 zhuōzi?","options":["ua","uo","uai"],"answer":1,"explain":"Первый слог zhuō содержит финаль uo."},{"type":"input","q":"Напишите pinyin слова 写.","answer":["xiě","xie"],"explain":"写 читается xiě: финаль ie, знак на e."},{"type":"input","q":"Напишите pinyin слова 桌子.","answer":["zhuōzi","zhuozi"],"explain":"桌子: zhuō + zi; в первом слоге финаль uo."},{"type":"input","q":"Напишите pinyin слова 家.","answer":["jiā","jia"],"explain":"家 читается jiā: финаль ia и первый тон."}],"homework":"Разделите на инициали и финали слова jiā, xiě, xiǎo, kuài. После этого прочитайте три раза 学校很小."},{"id":14,"title":"Тональные изменения 不 bù и 一 yī","duration":22,"goal":"Применять изменения произношения 不 и 一 перед слогами с разными тонами.","theory":[{"heading":"Не всегда произносим как написано","body":"На письме 不 остаётся bù, но перед четвёртым тоном в речи оно звучит bú: bú shì, bú kèqi. Перед другими тонами остаётся bù: bù hǎo, bù máng."},{"heading":"Три варианта 一","body":"Одинокое число «один» читается yī. Перед четвёртым тоном 一 звучит yí: yí ge, yí diǎn; перед первым, вторым и третьим — yì: yì tiān, yì nián. В записи слова обычно всё равно пишем yī."},{"heading":"Сначала увидьте следующий тон","body":"Чтобы выбрать произношение, посмотрите на тон следующего слога. Это изменение касается устной речи, а не написания иероглифов."}],"vocab":[{"hanzi":"不","pinyin":"bù","ru":"не"},{"hanzi":"不是","pinyin":"bú shì","ru":"не быть; нет","note":"в речи 不 меняет тон"},{"hanzi":"一个","pinyin":"yí ge","ru":"один; одна штука","note":"в речи 一 меняет тон"},{"hanzi":"一天","pinyin":"yì tiān","ru":"один день"},{"hanzi":"一点","pinyin":"yì diǎn","ru":"немного; один час"},{"hanzi":"不客气","pinyin":"bú kèqi","ru":"не за что"}],"grammar":[{"rule":"Изменение 不 и 一 перед следующим тоном","explain":"不: bù → bú перед четвёртым тоном. 一: yī → yí перед четвёртым, yī → yì перед первым, вторым или третьим тоном; написание не меняется.","examples":[{"hanzi":"不是，谢谢。","pinyin":"Bú shì, xièxie.","ru":"Нет, спасибо."},{"hanzi":"我有一个朋友。","pinyin":"Wǒ yǒu yí ge péngyou.","ru":"У меня есть один друг."}]}],"dialogue":{"title":"Вежливый ответ","lines":[{"speaker":"A","hanzi":"谢谢你！","pinyin":"Xièxie nǐ!","ru":"Спасибо тебе!"},{"speaker":"B","hanzi":"不客气。","pinyin":"Bú kèqi.","ru":"Не за что."},{"speaker":"A","hanzi":"你有几个朋友？","pinyin":"Nǐ yǒu jǐ ge péngyou?","ru":"Сколько у тебя друзей?"},{"speaker":"B","hanzi":"我有一个朋友。","pinyin":"Wǒ yǒu yí ge péngyou.","ru":"У меня один друг."}]},"exercises":[{"type":"choice","q":"Как в речи произносится 不 перед shì?","options":["bù shì","bú shì","bī shì"],"answer":1,"explain":"是 имеет четвёртый тон, поэтому 不 меняется на bú."},{"type":"choice","q":"Как произносится 一 перед tiān (первый тон)?","options":["yī","yí","yì"],"answer":2,"explain":"Перед первым тоном 一 звучит yì."},{"type":"match","q":"Соотнесите написание и произношение в речи.","pairs":[{"left":"不是","right":"bú shì"},{"left":"一天","right":"yì tiān"},{"left":"一点","right":"yì diǎn"}],"explain":"Изменение зависит от тона следующего слога."},{"type":"choice","q":"Как звучит 不 перед hǎo?","options":["bù","bú","bī"],"answer":0,"explain":"Перед третьим тоном 不 не меняется: bù hǎo."},{"type":"input","q":"Напишите pinyin фразы 一个.","answer":["yí ge","yige"],"explain":"В слове 一个 первый слог в речи звучит yí; на письме иероглиф 一 не меняется."},{"type":"input","q":"Напишите pinyin слова 不客气.","answer":["bú kèqi","bu keqi","bukeqi"],"explain":"Перед kè (четвёртый тон) 不 звучит bú; кэци имеет нейтральный последний слог."},{"type":"input","q":"Напишите pinyin фразы 一天.","answer":["yì tiān","yitian"],"explain":"Перед первым тоном tiān слово 一 звучит yì."}],"homework":"Прочитайте вслух bù hǎo, bú shì, yì tiān, yí ge. Рядом с каждым сочетанием подпишите тон следующего слога."},{"id":15,"title":"Два третьих тона подряд","duration":20,"goal":"Естественно произносить пары слогов с третьим тоном по правилу 3+3.","theory":[{"heading":"Что происходит с двумя третьими тонами","body":"Когда два третьих тона стоят подряд, первый в обычной речи произносится как второй: nǐ hǎo звучит близко к ní hǎo. На письме оба знака третьего тона сохраняются: nǐ hǎo."},{"heading":"Не меняйте второй слог","body":"Меняется только первый третий тон в группе. Второй остаётся третьим, обычно с понижением голоса; не нужно полностью рисовать два глубоких контура подряд."},{"heading":"Смысловые группы","body":"Правило работает внутри тесной группы слов. Делайте короткую паузу между отдельными фразами, а не между nǐ и hǎo."}],"vocab":[{"hanzi":"你好","pinyin":"nǐ hǎo","ru":"привет; здравствуйте"},{"hanzi":"很好","pinyin":"hěn hǎo","ru":"очень хорошо"},{"hanzi":"也","pinyin":"yě","ru":"тоже"},{"hanzi":"水果","pinyin":"shuǐguǒ","ru":"фрукты"},{"hanzi":"可以","pinyin":"kěyǐ","ru":"можно"},{"hanzi":"小姐","pinyin":"xiǎojiě","ru":"госпожа, мисс"}],"grammar":[{"rule":"Сандхи третьего тона: 3 + 3 → 2 + 3 в речи","explain":"В записи сохраняются два знака третьего тона, но первый слог звучит как второй. Это помогает говорить плавно.","examples":[{"hanzi":"你很好。","pinyin":"Nǐ hěn hǎo.","ru":"Ты очень хорош."},{"hanzi":"我也可以。","pinyin":"Wǒ yě kěyǐ.","ru":"Я тоже могу."}]}],"dialogue":{"title":"Дружеское приветствие","lines":[{"speaker":"A","hanzi":"你好！","pinyin":"Nǐ hǎo!","ru":"Привет!"},{"speaker":"B","hanzi":"你好！你好吗？","pinyin":"Nǐ hǎo! Nǐ hǎo ma?","ru":"Привет! Как ты?"},{"speaker":"A","hanzi":"我很好。","pinyin":"Wǒ hěn hǎo.","ru":"Я очень хорошо."},{"speaker":"B","hanzi":"我也很好。","pinyin":"Wǒ yě hěn hǎo.","ru":"Я тоже очень хорошо."}]},"exercises":[{"type":"choice","q":"Как звучит первая часть в паре nǐ hǎo в беглой речи?","options":["Как первый тон","Близко ко второму тону","Как четвёртый тон"],"answer":1,"explain":"Первый из двух третьих тонов меняется на второй."},{"type":"choice","q":"Какой слог сохраняет третий тон в nǐ hǎo?","options":["nǐ","hǎo","оба меняются"],"answer":1,"explain":"Меняется только первый слог; второй остаётся третьим."},{"type":"match","q":"Соотнесите выражение и перевод.","pairs":[{"left":"很好","right":"очень хорошо"},{"left":"也","right":"тоже"},{"left":"水果","right":"фрукты"}],"explain":"В 很好 есть последовательность двух третьих тонов."},{"type":"choice","q":"Как записывается 很好 в pinyin?","options":["hén háo","hěn hǎo","hèn hào"],"answer":1,"explain":"На письме оба тона третьи: hěn hǎo, хотя первый меняется в речи."},{"type":"input","q":"Напишите pinyin приветствия 你好.","answer":["nǐ hǎo","ni hao","nihao"],"explain":"На письме оба слога имеют третий тон, хотя первый в речи меняется."},{"type":"input","q":"Напишите pinyin слова 水果.","answer":["shuǐguǒ","shuiguo"],"explain":"В shuǐguǒ два третьих тона подряд; запись сохраняет оба знака."},{"type":"input","q":"Введите pinyin для 可以.","answer":["kěyǐ","keyi"],"explain":"В записи kěyǐ два третьих тона; первый звучит ближе ко второму."}],"homework":"Скажите десять раз nǐ hǎo и hěn hǎo: первый слог произносите восходяще, второй — третьим тоном. Запишите правило 3+3."},{"id":16,"title":"Слоги без инициали, апостроф и слогораздел","duration":22,"goal":"Распознавать слоги без инициали, читать их начальные y/w и ставить апостроф при необходимости.","theory":[{"heading":"Когда в начале нет согласного","body":"Если слог начинается с i, u или ü, в pinyin появляются буквы y или w: yī, yǒu, wǒ. Это удобная запись начала слога; не добавляйте к ним русские «й» или «в» слишком сильно."},{"heading":"Апостроф предотвращает путаницу","body":"Апостроф ставится перед слогом, начинающимся на a, o или e, если он идёт после другого слога: nǚ’ér, Xī’ān. Он показывает границу: без него чтение могло бы стать неясным."},{"heading":"Читаем словами, не буквами","body":"Разделяйте знакомые слова на слоги: wǒmen = wǒ + men, xiānsheng = xiān + sheng. Нейтральный тон в men и sheng остаётся без значка."}],"vocab":[{"hanzi":"我","pinyin":"wǒ","ru":"я"},{"hanzi":"有","pinyin":"yǒu","ru":"иметь; есть"},{"hanzi":"我们","pinyin":"wǒmen","ru":"мы"},{"hanzi":"女儿","pinyin":"nǚ’ér","ru":"дочь"},{"hanzi":"儿子","pinyin":"érzi","ru":"сын"},{"hanzi":"医生","pinyin":"yīshēng","ru":"врач"}],"grammar":[{"rule":"Начальные y/w и апостроф","explain":"y и w помогают записать слог без инициали. Апостроф перед a/o/e отделяет следующий слог и не произносится как звук.","examples":[{"hanzi":"我们有医生朋友。","pinyin":"Wǒmen yǒu yīshēng péngyou.","ru":"У нас есть друг-врач."},{"hanzi":"她有女儿。","pinyin":"Tā yǒu nǚ’ér.","ru":"У неё есть дочь."}]}],"dialogue":{"title":"О семье","lines":[{"speaker":"A","hanzi":"你有女儿吗？","pinyin":"Nǐ yǒu nǚ’ér ma?","ru":"У тебя есть дочь?"},{"speaker":"B","hanzi":"有，我有一个女儿。","pinyin":"Yǒu, wǒ yǒu yí ge nǚ’ér.","ru":"Да, у меня одна дочь."},{"speaker":"A","hanzi":"她在哪儿？","pinyin":"Tā zài nǎr?","ru":"Где она?"},{"speaker":"B","hanzi":"她在家。","pinyin":"Tā zài jiā.","ru":"Она дома."}]},"exercises":[{"type":"choice","q":"Зачем нужен апостроф в nǚ’ér?","options":["Обозначает паузу на целую секунду","Показывает границу перед слогом ér","Ставит четвёртый тон"],"answer":1,"explain":"Апостроф отделяет слог, начинающийся с e, и сам не произносится."},{"type":"choice","q":"Какая буква помогает записать слог uо без инициали в слове 我?","options":["y","w","r"],"answer":1,"explain":"w в wǒ обозначает начало слога без обычной инициали."},{"type":"match","q":"Соотнесите слова без инициали и переводы.","pairs":[{"left":"我们","right":"мы"},{"left":"有","right":"иметь"},{"left":"医生","right":"врач"}],"explain":"Начальные y/w встречаются в этих pinyin-записях."},{"type":"choice","q":"Где нужен апостроф?","options":["wǒmen","nǚ’ér","yīshēng"],"answer":1,"explain":"Апостроф отделяет слог ér, который начинается с e."},{"type":"input","q":"Введите pinyin для 女儿.","answer":["nǚ’ér","nü’er","nǚer","nuer"],"explain":"Правильная полная запись — nǚ’ér; апостроф помогает увидеть два слога."},{"type":"input","q":"Напишите pinyin слова 我们.","answer":["wǒmen","women"],"explain":"我们: wǒ — третий тон, men — нейтральный."},{"type":"input","q":"Напишите pinyin слова 医生.","answer":["yīshēng","yisheng"],"explain":"医生: yī + shēng; y помогает записать начальный слог без инициали."}],"homework":"Разделите на слоги и перепишите: 我们, 女儿, 医生, 西安. Отдельно отметьте, где апостроф обязателен."},{"id":17,"title":"Первые иероглифы: черты и порядок","duration":24,"goal":"Узнавать основные черты и писать простые иероглифы в правильном порядке.","theory":[{"heading":"Иероглиф — не картинка","body":"Иероглиф состоит из ограниченного набора черт. В китайской каллиграфии важны направление, длина и порядок: это помогает писать разборчиво и запоминать форму."},{"heading":"Базовый порядок","body":"Главные правила: сверху вниз, слева направо; сначала горизонтальные черты, затем вертикальные; внешняя рамка часто пишется до внутренней части. Не старайтесь рисовать знак одним движением."},{"heading":"Начните с простого","body":"练习 (упражнение) здесь — медленно повторить 人, 大, 木, 口, 日. Считайте черты и проговаривайте слово с тоном, когда пишете его."}],"vocab":[{"hanzi":"人","pinyin":"rén","ru":"человек"},{"hanzi":"大","pinyin":"dà","ru":"большой"},{"hanzi":"口","pinyin":"kǒu","ru":"рот"},{"hanzi":"日","pinyin":"rì","ru":"день; солнце"},{"hanzi":"木","pinyin":"mù","ru":"дерево"},{"hanzi":"火","pinyin":"huǒ","ru":"огонь"}],"grammar":[{"rule":"Основные правила порядка черт","explain":"Пишите сверху вниз и слева направо. В 人 сначала левая откидная черта, затем правая; в 口 сначала левая вертикальная с верхней горизонталью, затем нижняя и правая.","examples":[{"hanzi":"大人","pinyin":"dàrén","ru":"взрослый."},{"hanzi":"日子好。","pinyin":"Rìzi hǎo.","ru":"День хороший."}]}],"dialogue":{"title":"На уроке письма","lines":[{"speaker":"A","hanzi":"这是什么字？","pinyin":"Zhè shì shénme zì?","ru":"Что это за иероглиф?"},{"speaker":"B","hanzi":"这是人。","pinyin":"Zhè shì rén.","ru":"Это 人 — человек."},{"speaker":"A","hanzi":"人有几画？","pinyin":"Rén yǒu jǐ huà?","ru":"Сколько черт в 人?"},{"speaker":"B","hanzi":"人有两画。","pinyin":"Rén yǒu liǎng huà.","ru":"В 人 две черты."}]},"exercises":[{"type":"choice","q":"Какое правило порядка черт верное?","options":["Снизу вверх","Сверху вниз","Сначала случайные мелкие части"],"answer":1,"explain":"Одно из главных правил письма — двигаться сверху вниз."},{"type":"choice","q":"Сколько черт в 人?","options":["Одна","Две","Четыре"],"answer":1,"explain":"В 人 две откидные черты."},{"type":"match","q":"Соотнесите иероглиф и значение.","pairs":[{"left":"口","right":"рот"},{"left":"日","right":"день; солнце"},{"left":"木","right":"дерево"}],"explain":"Эти простые знаки полезно запоминать вместе со значением."},{"type":"choice","q":"С чего обычно начинают писать иероглиф?","options":["С нижней черты","С верхней части","С любой черты"],"answer":1,"explain":"Базовое правило порядка черт: сверху вниз."},{"type":"input","q":"Напишите pinyin иероглифа 人.","answer":["rén","ren"],"explain":"人 читается rén, второй тон."},{"type":"input","q":"Напишите pinyin иероглифа 大.","answer":["dà","da"],"explain":"大 читается dà, четвёртый тон."},{"type":"input","q":"Напишите pinyin иероглифа 木.","answer":["mù","mu"],"explain":"木 читается mù, четвёртый тон."}],"homework":"Напишите в клетку по пять раз 人, 大, 口, 日. Для каждого знака проговорите pinyin и число черт."},{"id":18,"title":"Ключи: 人, 口, 女, 日, 月, 水","duration":24,"goal":"Узнавать шесть частых ключей и использовать их как подсказки к структуре иероглифа.","theory":[{"heading":"Что такое ключ","body":"Ключ, или радикал, — значимая часть иероглифа. Он часто подсказывает общую тему слова или помогает найти знак в словаре, но сам по себе не всегда сообщает точное произношение."},{"heading":"Шесть полезных ключей","body":"人 связан с людьми, 口 — с ртом и речью, 女 — с женщиной, 日 — с солнцем или днём, 月 — с луной и частями тела, 水/氵 — с водой. В иероглифе 妈 слева стоит ключ 女; в 喝 слева — 口."},{"heading":"Ищите знакомую часть","body":"Сначала найдите ключ, затем рассматривайте остальную часть. Так сложный иероглиф перестаёт быть сплошным рисунком и легче запоминается."}],"vocab":[{"hanzi":"人","pinyin":"rén","ru":"человек"},{"hanzi":"口","pinyin":"kǒu","ru":"рот"},{"hanzi":"女","pinyin":"nǚ","ru":"женщина"},{"hanzi":"日","pinyin":"rì","ru":"день; солнце"},{"hanzi":"月","pinyin":"yuè","ru":"месяц; луна"},{"hanzi":"水","pinyin":"shuǐ","ru":"вода"}],"grammar":[{"rule":"Ключ — подсказка, а не перевод всего слова","explain":"Радикал помогает увидеть тему и структуру. Например, 女 в 妈 связано с «мама», а 口 в 吃 и 喝 — с действиями рта.","examples":[{"hanzi":"妈妈喝水。","pinyin":"Māma hē shuǐ.","ru":"Мама пьёт воду."},{"hanzi":"今天是三月。","pinyin":"Jīntiān shì sānyuè.","ru":"Сегодня март."}]}],"dialogue":{"title":"Наблюдаем иероглифы","lines":[{"speaker":"A","hanzi":"妈妈的妈有女吗？","pinyin":"Māma de mā yǒu nǚ ma?","ru":"В иероглифе «мама» есть 女?"},{"speaker":"B","hanzi":"有，女在左边。","pinyin":"Yǒu, nǚ zài zuǒbian.","ru":"Да, 女 слева."},{"speaker":"A","hanzi":"喝有口吗？","pinyin":"Hē yǒu kǒu ma?","ru":"В 喝 есть 口?"},{"speaker":"B","hanzi":"有，口在左边。","pinyin":"Yǒu, kǒu zài zuǒbian.","ru":"Да, 口 слева."}]},"exercises":[{"type":"choice","q":"Какой ключ находится слева в 妈?","options":["人","女","水"],"answer":1,"explain":"Иероглиф 妈 содержит ключ 女 слева."},{"type":"choice","q":"Какой ключ часто виден в словах о питье и еде?","options":["口","月","女"],"answer":0,"explain":"В 吃 и 喝 есть ключ 口, связанный с действиями рта."},{"type":"match","q":"Соотнесите ключ и общую тему.","pairs":[{"left":"人","right":"люди"},{"left":"口","right":"рот и речь"},{"left":"水","right":"вода"}],"explain":"Ключ подсказывает семантическую область, но не переводит слово целиком."},{"type":"choice","q":"Какой ключ связан с водой?","options":["口","水","女"],"answer":1,"explain":"Ключ 水 и его вариант 氵 часто встречаются в словах о воде."},{"type":"input","q":"Напишите pinyin иероглифа 水.","answer":["shuǐ","shui"],"explain":"水 читается shuǐ, третий тон."},{"type":"input","q":"Напишите pinyin иероглифа 女.","answer":["nǚ","nü","nu"],"explain":"女 читается nǚ; две точки над ü важны."},{"type":"input","q":"Напишите pinyin иероглифа 月.","answer":["yuè","yue"],"explain":"月 читается yuè: после y буква u обозначает ü."}],"homework":"Найдите в 妈妈, 喝, 吃, 明 знакомые ключи. Запишите каждый ключ один раз и подпишите его значение."},{"id":19,"title":"Читаем и пишем первые фразы","duration":25,"goal":"Переводить простые фразы между иероглифами и pinyin, сохраняя слоги, тоны и пробелы.","theory":[{"heading":"Что записываем в pinyin","body":"Каждый иероглиф обычно даёт один слог pinyin. В учебной записи слова разделяют пробелами: Wǒ shì xuésheng. Тоновые знаки обязательны для точной записи, а предложение начинается с заглавной буквы."},{"heading":"От чтения к письму","body":"Сначала найдите известные слова, затем проверьте каждый тон. Например, 我是学生: wǒ (3), shì (4), xué (2), sheng (нейтральный). Не подменяйте pinyin русской транскрипцией."},{"heading":"Короткие формулы общения","body":"Фразы 你好, 谢谢, 再见 и 对不起 стоит узнавать целиком, но всё равно полезно видеть их слоги: nǐ hǎo, xièxie, zàijiàn, duìbuqǐ."}],"vocab":[{"hanzi":"你好","pinyin":"nǐ hǎo","ru":"привет; здравствуйте"},{"hanzi":"谢谢","pinyin":"xièxie","ru":"спасибо"},{"hanzi":"再见","pinyin":"zàijiàn","ru":"до свидания"},{"hanzi":"对不起","pinyin":"duìbuqǐ","ru":"извините"},{"hanzi":"学生","pinyin":"xuésheng","ru":"студент"},{"hanzi":"老师","pinyin":"lǎoshī","ru":"учитель"}],"grammar":[{"rule":"Один иероглиф — один слог pinyin","explain":"В pinyin ставьте пробел между словами и диакритику на каждом тоновом слоге. Нейтральные слоги, например sheng и xie в 谢谢, пишутся без знака.","examples":[{"hanzi":"我是学生。","pinyin":"Wǒ shì xuésheng.","ru":"Я студент."},{"hanzi":"对不起，老师。","pinyin":"Duìbuqǐ, lǎoshī.","ru":"Извините, учитель."}]}],"dialogue":{"title":"После урока","lines":[{"speaker":"A","hanzi":"老师，对不起。","pinyin":"Lǎoshī, duìbuqǐ.","ru":"Учитель, извините."},{"speaker":"B","hanzi":"没关系。","pinyin":"Méi guānxi.","ru":"Ничего страшного."},{"speaker":"A","hanzi":"谢谢老师。","pinyin":"Xièxie lǎoshī.","ru":"Спасибо, учитель."},{"speaker":"B","hanzi":"再见！","pinyin":"Zàijiàn!","ru":"До свидания!"}]},"exercises":[{"type":"choice","q":"Какая pinyin-запись верна для 我是学生？","options":["wo shi xuesheng","Wǒ shì xuésheng","Wǒshìxuéshēng"],"answer":1,"explain":"В учебной записи есть пробелы между словами и тоны; sheng нейтральный."},{"type":"choice","q":"Сколько слогов в duìbuqǐ?","options":["Два","Три","Четыре"],"answer":1,"explain":"对不起 состоит из duì, bu и qǐ; средний слог нейтральный."},{"type":"match","q":"Соотнесите фразу и перевод.","pairs":[{"left":"你好","right":"привет"},{"left":"对不起","right":"извините"},{"left":"再见","right":"до свидания"}],"explain":"Эти выражения удобно узнавать и читать целиком."},{"type":"choice","q":"Какой слог в 谢谢 нейтральный?","options":["xiè","xie","оба"],"answer":1,"explain":"Первый слог xiè четвёртого тона, второй xie — нейтральный."},{"type":"input","q":"Напишите pinyin слова 谢谢.","answer":["xièxie","xiexie"],"explain":"谢谢: xiè — четвёртый тон, xie — нейтральный."},{"type":"input","q":"Напишите pinyin фразы 我是学生.","answer":["wǒ shì xuésheng","wo shi xuesheng","woshixuesheng"],"explain":"Запишите слова раздельно: wǒ shì xuésheng."},{"type":"input","q":"Напишите pinyin фразы 对不起.","answer":["duìbuqǐ","duibuqi"],"explain":"对不起: duì + bu + qǐ; средний слог нейтральный."}],"homework":"Перепишите pinyin с тонами для 你好, 谢谢, 再见, 对不起. Затем без подсказки запишите иероглифами фразу «Я студент»."},{"id":20,"title":"Итог модуля: пиньинь, тоны и первые фразы","duration":30,"goal":"Закрепить чтение HSK1-слов, тоновые правила, основы письма и запись простого диалога.","theory":[{"heading":"Алгоритм чтения","body":"Увидев pinyin, найдите границы слогов, инициаль, финаль и тон. Затем проверьте особые правила: ü после j/q/x, апостроф перед a/o/e, изменения 不/一 и два третьих тона подряд."},{"heading":"Алгоритм записи","body":"Услышав или увидев иероглифы, сначала назовите знакомые слова, затем запишите pinyin с тонами. Пишите один слог на иероглиф и ставьте пробелы между словами."},{"heading":"Повторяем осознанно","body":"В этом уроке нет новой фонетики: задача — заметить слабое место и повторить именно его. Читайте медленно, но точно; скорость появится после нескольких правильных повторений."}],"vocab":[{"hanzi":"我","pinyin":"wǒ","ru":"я"},{"hanzi":"你","pinyin":"nǐ","ru":"ты"},{"hanzi":"他","pinyin":"tā","ru":"он"},{"hanzi":"是","pinyin":"shì","ru":"быть; являться"},{"hanzi":"好","pinyin":"hǎo","ru":"хороший; хорошо"},{"hanzi":"汉语","pinyin":"Hànyǔ","ru":"китайский язык"}],"grammar":[{"rule":"Проверка чтения: слог, тон, правило","explain":"В итоговой записи тоны сохраняются даже там, где речь меняет их: nǐ hǎo и bù shì на письме; в произношении — ní hǎo и bú shì. При чтении сначала опирайтесь на написание, затем применяйте правило.","examples":[{"hanzi":"你好，我是学生。","pinyin":"Nǐ hǎo, wǒ shì xuésheng.","ru":"Здравствуйте, я студент."},{"hanzi":"他不是老师，他学习汉语。","pinyin":"Tā bú shì lǎoshī, tā xuéxí Hànyǔ.","ru":"Он не учитель, он изучает китайский."}]}],"dialogue":{"title":"Итоговый диалог","lines":[{"speaker":"A","hanzi":"你好！你是老师吗？","pinyin":"Nǐ hǎo! Nǐ shì lǎoshī ma?","ru":"Здравствуйте! Вы учитель?"},{"speaker":"B","hanzi":"不是，我是学生。","pinyin":"Bú shì, wǒ shì xuésheng.","ru":"Нет, я студент."},{"speaker":"A","hanzi":"你学习汉语吗？","pinyin":"Nǐ xuéxí Hànyǔ ma?","ru":"Ты изучаешь китайский?"},{"speaker":"B","hanzi":"学习。谢谢！再见！","pinyin":"Xuéxí. Xièxie! Zàijiàn!","ru":"Изучаю. Спасибо! До свидания!"}]},"exercises":[{"type":"choice","q":"Какая запись верна для «не быть» в речи перед shì?","options":["bù shì","bú shì","bǔ shì"],"answer":1,"explain":"Перед четвёртым тоном shì слово 不 произносится bú."},{"type":"input","q":"Напишите pinyin слова 汉语.","answer":["hànyǔ","hanyu"],"explain":"汉语 читается Hànyǔ: четвёртый и третий тоны."},{"type":"match","q":"Соотнесите местоимения и значения.","pairs":[{"left":"我","right":"я"},{"left":"你","right":"ты"},{"left":"他","right":"он"},{"left":"是","right":"быть"}],"explain":"Это ключевые слова для первых фраз."},{"type":"choice","q":"Какая запись сохраняется на письме для приветствия?","options":["ní hǎo","nǐ hǎo","nī hǎo"],"answer":1,"explain":"На письме оба третьих тона сохраняются: nǐ hǎo; в речи первый меняется."},{"type":"input","q":"Запишите pinyin: 我是学生。","answer":["wǒ shì xuésheng","wo shi xuesheng","woshixuesheng"],"explain":"Проверьте три слога с тонами и пробелы между словами."},{"type":"match","q":"Соотнесите правило и пример.","pairs":[{"left":"u = ü после j/q/x","right":"qù"},{"left":"3 + 3 в речи","right":"nǐ hǎo"},{"left":"апостроф перед e","right":"nǚ’ér"}],"explain":"Каждый пример напоминает важное правило модуля."},{"type":"choice","q":"Какой ключ есть слева в 喝?","options":["口","女","水"],"answer":0,"explain":"В 喝 слева ключ 口; он связан с действием рта."}],"homework":"Повторите все слова урока 20. Затем запишите от руки 你好，我是学生。 и прочитайте итоговый диалог два раза: сначала медленно, затем естественно."}]},{"module":2,"hsk":"HSK1","title":"Базовые фразы и приветствия","summary":"В модуле ученик осваивает базовые приветствия, знакомство и повседневные вежливые фразы. Он учится строить простые предложения о себе, людях, предметах, действиях и месте.","lessons":[{"id":1,"title":"你好: приветствия в разное время","duration":20,"goal":"Ученик приветствует собеседника нейтрально и выбирает формулу по времени суток.","theory":[{"heading":"Нейтральное «здравствуйте»","body":"<b>你好</b> (nǐ hǎo) подходит почти для любой неформальной ситуации: при встрече с ровесником, знакомым или новым человеком. Это не вопрос «ты хороший», а готовая формула приветствия."},{"heading":"Время суток в приветствии","body":"Перед 好 можно поставить время: <b>早上好</b> — утром, <b>中午好</b> — в полдень, <b>下午好</b> — после обеда, <b>晚上好</b> — вечером. Произносите каждую часть спокойно и с изученными тонами."}],"vocab":[{"hanzi":"你好","pinyin":"nǐ hǎo","ru":"привет; здравствуйте"},{"hanzi":"早上好","pinyin":"zǎoshang hǎo","ru":"доброе утро"},{"hanzi":"上午好","pinyin":"shàngwǔ hǎo","ru":"доброе утро; добрый день","note":"чаще в формальной речи"},{"hanzi":"中午好","pinyin":"zhōngwǔ hǎo","ru":"добрый день (в полдень)"},{"hanzi":"下午好","pinyin":"xiàwǔ hǎo","ru":"добрый день"},{"hanzi":"晚上好","pinyin":"wǎnshang hǎo","ru":"добрый вечер"}],"grammar":[{"rule":"Приветствие: [время] + 好","explain":"Слово 好 остаётся в конце. Если время неважно, используйте просто 你好.","examples":[{"hanzi":"早上好！","pinyin":"Zǎoshang hǎo!","ru":"Доброе утро!"},{"hanzi":"下午好！","pinyin":"Xiàwǔ hǎo!","ru":"Добрый день!"}]}],"dialogue":{"title":"Встреча в разное время","lines":[{"speaker":"Аня","hanzi":"早上好！","pinyin":"Zǎoshang hǎo!","ru":"Доброе утро!"},{"speaker":"Ли","hanzi":"你好！","pinyin":"Nǐ hǎo!","ru":"Здравствуйте!"},{"speaker":"Аня","hanzi":"中午好！","pinyin":"Zhōngwǔ hǎo!","ru":"Добрый день!"},{"speaker":"Ли","hanzi":"下午好！","pinyin":"Xiàwǔ hǎo!","ru":"Добрый день!"}]},"exercises":[{"type":"choice","q":"Как поздороваться вечером?","options":["早上好","晚上好","中午好"],"answer":1,"explain":"晚上 означает «вечер», поэтому вечером говорят 晚上好。"},{"type":"choice","q":"Какое приветствие нейтрально по времени?","options":["你好","上午好","下午好"],"answer":0,"explain":"你好 можно сказать в любое время суток."},{"type":"choice","q":"Что скажете в полдень?","options":["下午好","中午好","晚上好"],"answer":1,"explain":"中午 — полдень, поэтому подходит 中午好。"},{"type":"choice","q":"Какое слово есть во всех приветствиях урока?","options":["好","是","吗"],"answer":0,"explain":"好 завершает каждую формулу приветствия."},{"type":"match","q":"Соотнесите приветствие и время.","pairs":[{"left":"早上好","right":"утро"},{"left":"中午好","right":"полдень"},{"left":"晚上好","right":"вечер"}],"explain":"Первая часть формулы называет время суток."},{"type":"input","q":"Напишите пиньинь приветствия 你好.","answer":["nǐ hǎo","ni hao","nihao"],"explain":"你好 читается nǐ hǎo: оба слога в третьем тоне."},{"type":"input","q":"Напишите иероглифами: «Добрый день после обеда».","answer":["下午好"],"explain":"После обеда используют 下午好。"}],"homework":"Запишите голосом или вслух четыре приветствия: 你好, 早上好, 下午好, 晚上好. Для каждого выберите подходящий момент дня."},{"id":2,"title":"Личные местоимения: 我、你、他、她、它","duration":22,"goal":"Ученик называет себя, собеседника и других людей, а также образует множественное число с 们.","theory":[{"heading":"Кого мы называем","body":"<b>我</b> — «я», <b>你</b> — «ты/вы», <b>他</b> — «он», <b>她</b> — «она», <b>它</b> — «оно». В устной речи tā для 他、她 и 它 звучит одинаково: значение видно из контекста."},{"heading":"Несколько людей","body":"Суффикс <b>们</b> ставится после местоимения: 我们 — «мы», 你们 — «вы», 他们 — «они». С вещами 们 не используют: нельзя сказать 它们 о предметах в этом курсе."}],"vocab":[{"hanzi":"我","pinyin":"wǒ","ru":"я"},{"hanzi":"你","pinyin":"nǐ","ru":"ты; вы"},{"hanzi":"他","pinyin":"tā","ru":"он"},{"hanzi":"她","pinyin":"tā","ru":"она"},{"hanzi":"它","pinyin":"tā","ru":"оно"},{"hanzi":"我们","pinyin":"wǒmen","ru":"мы"},{"hanzi":"你们","pinyin":"nǐmen","ru":"вы"},{"hanzi":"他们","pinyin":"tāmen","ru":"они","note":"о мужчинах или смешанной группе"}],"grammar":[{"rule":"Множественное число: местоимение + 们","explain":"们 добавляет значение нескольких людей. Оно пишется после уже знакомого местоимения.","examples":[{"hanzi":"我们好。","pinyin":"Wǒmen hǎo.","ru":"У нас всё хорошо."},{"hanzi":"你们好！","pinyin":"Nǐmen hǎo!","ru":"Здравствуйте! (обращение к нескольким людям)"}]}],"dialogue":{"title":"Новые знакомые","lines":[{"speaker":"Маша","hanzi":"你好，我是玛莎。","pinyin":"Nǐ hǎo, wǒ shì Mǎshā.","ru":"Здравствуйте, я Маша."},{"speaker":"Ли","hanzi":"你好，我是李明。","pinyin":"Nǐ hǎo, wǒ shì Lǐ Míng.","ru":"Здравствуйте, я Ли Мин."},{"speaker":"Маша","hanzi":"她是你的朋友吗？","pinyin":"Tā shì nǐ de péngyou ma?","ru":"Она твоя подруга?"},{"speaker":"Ли","hanzi":"是，她是我的朋友。","pinyin":"Shì, tā shì wǒ de péngyou.","ru":"Да, она моя подруга."}]},"exercises":[{"type":"choice","q":"Как по-китайски «мы»?","options":["你们","我们","他们"],"answer":1,"explain":"我 — «я», а 我们 — «мы». "},{"type":"choice","q":"Какой иероглиф означает «она»?","options":["他","她","它"],"answer":1,"explain":"У 她 слева ключ 女 «женщина»; это местоимение «она». "},{"type":"choice","q":"Как по-китайски «они»?","options":["他们","我们","你们"],"answer":0,"explain":"他们 — «они» о мужчинах или смешанной группе."},{"type":"choice","q":"Что добавляют к 我, чтобы сказать «мы»?","options":["的","们","吗"],"answer":1,"explain":"Суффикс 们 образует множественное число людей."},{"type":"match","q":"Соотнесите местоимение и перевод.","pairs":[{"left":"我","right":"я"},{"left":"他","right":"он"},{"left":"她","right":"она"},{"left":"它","right":"оно"}],"explain":"Хотя пиньинь у трёх слов tā одинаковый, иероглифы и значение различаются."},{"type":"input","q":"Напишите пиньинь слова 我们.","answer":["wǒmen","women"],"explain":"我们 читается wǒmen; второй слог обычно произносится нейтрально."},{"type":"input","q":"Напишите иероглифами: «вы» (несколько человек).","answer":["你们"],"explain":"К 你 добавляется суффикс 们: 你们。"}],"homework":"Составьте вслух пять мини-фраз: «я», «ты», «он», «она», «мы». Затем замените одно местоимение на форму с 们."},{"id":3,"title":"谢谢, 不客气: вежливые слова","duration":22,"goal":"Ученик благодарит, отвечает на благодарность и вежливо извиняется.","theory":[{"heading":"Благодарность и ответ","body":"<b>谢谢</b> значит «спасибо». На него естественно ответить <b>不客气</b> — буквально «не церемоньтесь», то есть «пожалуйста; не за что». Эта реплика не изменяется по лицам."},{"heading":"Если нужно извиниться","body":"<b>对不起</b> говорят, когда вы действительно виноваты или помешали человеку. Мягкий ответ — <b>没关系</b>: «ничего, всё в порядке». Перед просьбой полезно поставить 请 — «пожалуйста»."}],"vocab":[{"hanzi":"谢谢","pinyin":"xièxie","ru":"спасибо"},{"hanzi":"不客气","pinyin":"bú kèqi","ru":"пожалуйста; не за что"},{"hanzi":"对不起","pinyin":"duìbuqǐ","ru":"извините; прости"},{"hanzi":"没关系","pinyin":"méi guānxi","ru":"ничего; всё в порядке"},{"hanzi":"请","pinyin":"qǐng","ru":"пожалуйста; просить"},{"hanzi":"请坐","pinyin":"qǐng zuò","ru":"присаживайтесь, пожалуйста"}],"grammar":[{"rule":"Вежливый обмен: 谢谢 → 不客气","explain":"После 谢谢 не нужно повторять спасибо. Ответьте 不客气. Перед глаголом 请 делает просьбу вежливой.","examples":[{"hanzi":"谢谢你。","pinyin":"Xièxie nǐ.","ru":"Спасибо тебе."},{"hanzi":"不客气。","pinyin":"Bú kèqi.","ru":"Пожалуйста."}]}],"dialogue":{"title":"В классе","lines":[{"speaker":"Ира","hanzi":"请，喝水。","pinyin":"Qǐng, hē shuǐ.","ru":"Пожалуйста, попей воды."},{"speaker":"Ван","hanzi":"谢谢！","pinyin":"Xièxie!","ru":"Спасибо!"},{"speaker":"Ира","hanzi":"不客气。","pinyin":"Bú kèqi.","ru":"Пожалуйста."},{"speaker":"Ван","hanzi":"对不起！","pinyin":"Duìbuqǐ!","ru":"Извините!"},{"speaker":"Ира","hanzi":"没关系。","pinyin":"Méi guānxi.","ru":"Ничего."}]},"exercises":[{"type":"choice","q":"Что ответить на 谢谢?","options":["对不起","不客气","再见"],"answer":1,"explain":"不客气 — стандартный ответ на благодарность."},{"type":"choice","q":"Как сказать «извините»?","options":["没关系","请","对不起"],"answer":2,"explain":"对不起 используют, когда просят прощения."},{"type":"choice","q":"Как начать вежливую просьбу?","options":["请","再见","谁"],"answer":0,"explain":"请 делает просьбу вежливой."},{"type":"choice","q":"Что говорят, приглашая сесть?","options":["请坐","再见","谁"],"answer":0,"explain":"请坐 — вежливое «присаживайтесь»."},{"type":"match","q":"Соотнесите фразу и ситуацию.","pairs":[{"left":"请","right":"вежливая просьба"},{"left":"谢谢","right":"благодарность"},{"left":"对不起","right":"извинение"},{"left":"没关系","right":"ответ на извинение"}],"explain":"Выражения работают как короткие готовые реплики."},{"type":"input","q":"Напишите пиньинь слова 谢谢.","answer":["xièxie","xiexie"],"explain":"谢谢 читается xièxie: первый слог в четвёртом тоне, второй — нейтральный."},{"type":"input","q":"Напишите иероглифами: «Ничего, всё в порядке».","answer":["没关系"],"explain":"Устойчивое выражение «всё в порядке» — 没关系。"}],"homework":"Придумайте два микродиалога по две реплики: один со 谢谢, другой с 对不起. Прочитайте их вслух."},{"id":4,"title":"再见: как попрощаться","duration":20,"goal":"Ученик завершает разговор и уточняет, когда увидится с собеседником снова.","theory":[{"heading":"Основное прощание","body":"<b>再见</b> буквально означает «снова увидеться», но по-русски это обычное «до свидания». Его можно сказать и одному человеку, и группе."},{"heading":"Добавляем время встречи","body":"Чтобы договориться о следующей встрече, поставьте время перед 见: <b>明天见</b> — «до завтра», <b>下午见</b> — «увидимся днём». В коротком ответе достаточно повторить: 明天见！"}],"vocab":[{"hanzi":"再见","pinyin":"zàijiàn","ru":"до свидания"},{"hanzi":"见","pinyin":"jiàn","ru":"видеть; увидеться"},{"hanzi":"明天","pinyin":"míngtiān","ru":"завтра"},{"hanzi":"今天","pinyin":"jīntiān","ru":"сегодня"},{"hanzi":"下午","pinyin":"xiàwǔ","ru":"после обеда; днём"},{"hanzi":"晚上","pinyin":"wǎnshang","ru":"вечер"}],"grammar":[{"rule":"Прощание со временем: время + 见","explain":"В этой краткой формуле время отвечает на вопрос «когда увидимся?». Глагол 见 стоит в конце.","examples":[{"hanzi":"明天见！","pinyin":"Míngtiān jiàn!","ru":"До завтра!"},{"hanzi":"下午见！","pinyin":"Xiàwǔ jiàn!","ru":"Увидимся днём!"}]}],"dialogue":{"title":"После занятия","lines":[{"speaker":"Оля","hanzi":"今天谢谢你。","pinyin":"Jīntiān xièxie nǐ.","ru":"Спасибо тебе за сегодня."},{"speaker":"Чжан","hanzi":"不客气。","pinyin":"Bú kèqi.","ru":"Пожалуйста."},{"speaker":"Оля","hanzi":"明天见！","pinyin":"Míngtiān jiàn!","ru":"До завтра!"},{"speaker":"Чжан","hanzi":"再见！","pinyin":"Zàijiàn!","ru":"До свидания!"}]},"exercises":[{"type":"choice","q":"Как сказать «до завтра»?","options":["今天见","明天见","晚上好"],"answer":1,"explain":"明天 — «завтра», поэтому 明天见 — «до завтра». "},{"type":"choice","q":"Какое слово означает «до свидания»?","options":["再见","谢谢","你好"],"answer":0,"explain":"再见 — универсальная формула прощания."},{"type":"choice","q":"Какое слово означает «завтра»?","options":["昨天","明天","今天"],"answer":1,"explain":"明天 — завтрашний день."},{"type":"choice","q":"Чем завершить разговор?","options":["再见","请问","什么"],"answer":0,"explain":"再见 — обычное «до свидания»."},{"type":"match","q":"Соотнесите слово и перевод.","pairs":[{"left":"今天","right":"сегодня"},{"left":"明天","right":"завтра"},{"left":"再见","right":"до свидания"}],"explain":"今天 и 明天 называют дни, а 再见 завершает беседу."},{"type":"input","q":"Напишите пиньинь слова 再见.","answer":["zàijiàn","zaijian"],"explain":"再见 читается zàijiàn: оба слога в четвёртом тоне."},{"type":"input","q":"Напишите иероглифами: «Увидимся днём».","answer":["下午见"],"explain":"Формула строится так: 下午 + 见。"}],"homework":"Напишите три карточки-прощания: 再见, 明天见, 下午见. Прочитайте каждую с правильными тонами."},{"id":5,"title":"Это...: конструкция A 是 B","duration":24,"goal":"Ученик строит простые предложения с 是 и отрицает их с 不是.","theory":[{"heading":"Что делает 是","body":"<b>是</b> связывает два названия: «A есть B». По-китайски обычно не нужен отдельный эквивалент русского слова «это»: 这是书 — «это книга». Порядок слов важен."},{"heading":"Как сказать «не»","body":"Отрицание перед 是 — <b>不是</b>. Не ставьте 不 отдельно после 是: правильно 他不是老师, а не 他是不老师."}],"vocab":[{"hanzi":"是","pinyin":"shì","ru":"быть; являться"},{"hanzi":"不是","pinyin":"bú shì","ru":"не быть; не являться"},{"hanzi":"这","pinyin":"zhè","ru":"это; этот"},{"hanzi":"那","pinyin":"nà","ru":"то; тот"},{"hanzi":"人","pinyin":"rén","ru":"человек"},{"hanzi":"书","pinyin":"shū","ru":"книга"},{"hanzi":"学生","pinyin":"xuéshēng","ru":"студент; ученик"}],"grammar":[{"rule":"Утверждение: A 是 B","explain":"Сначала назовите тему, затем 是, потом кто это или что это. В русском переводе часто появляется тире, а в китайском — 是.","examples":[{"hanzi":"这是书。","pinyin":"Zhè shì shū.","ru":"Это книга."},{"hanzi":"我是学生。","pinyin":"Wǒ shì xuéshēng.","ru":"Я студент."}]},{"rule":"Отрицание: A 不是 B","explain":"Чтобы отрицать именно «быть кем-то/чем-то», замените 是 на 不是.","examples":[{"hanzi":"他不是学生。","pinyin":"Tā bú shì xuéshēng.","ru":"Он не студент."},{"hanzi":"那不是书。","pinyin":"Nà bú shì shū.","ru":"То не книга."}]}],"dialogue":{"title":"У доски","lines":[{"speaker":"Катя","hanzi":"这是书吗？","pinyin":"Zhè shì shū ma?","ru":"Это книга?"},{"speaker":"Лю","hanzi":"是，这是书。","pinyin":"Shì, zhè shì shū.","ru":"Да, это книга."},{"speaker":"Катя","hanzi":"那是学生吗？","pinyin":"Nà shì xuéshēng ma?","ru":"Тот — студент?"},{"speaker":"Лю","hanzi":"不是，那是老师。","pinyin":"Bú shì, nà shì lǎoshī.","ru":"Нет, тот — преподаватель."}]},"exercises":[{"type":"choice","q":"Выберите правильное отрицание: «Он не студент».","options":["他是不学生。","他不是学生。","他学生不是。"],"answer":1,"explain":"不是 целиком стоит между подлежащим и тем, кем человек не является."},{"type":"choice","q":"Что означает 这是书？","options":["Это книга.","Это не книга.","Книга здесь."],"answer":0,"explain":"这 — «это», 是 — «есть», 书 — «книга». "},{"type":"choice","q":"Какой знак нужен в «Это не книга»?","options":["不是","没有","很"],"answer":0,"explain":"不是 отрицает связь с 是."},{"type":"choice","q":"Что стоит между 我 и 学生 в фразе «Я студент»?","options":["是","吗","有"],"answer":0,"explain":"В конструкции A 是 B связка 是 стоит посередине."},{"type":"match","q":"Соотнесите часть предложения и перевод.","pairs":[{"left":"我","right":"я"},{"left":"是","right":"являюсь; есть"},{"left":"不是","right":"не являюсь; не есть"},{"left":"书","right":"книга"}],"explain":"Из частей 我 是 学生 получается законченное предложение."},{"type":"input","q":"Напишите пиньинь слова 不是.","answer":["bú shì","bu shi","bushi"],"explain":"В 不 перед четвёртым тоном 是 тон меняется: bú shì."},{"type":"input","q":"Напишите иероглифами: «Я студент».","answer":["我是学生"],"explain":"Схема A 是 B: 我 + 是 + 学生。"}],"homework":"Составьте четыре предложения по схемам: 这是书、那是书、我是学生、他不是学生. Переведите их устно."},{"id":6,"title":"Общий вопрос с 吗","duration":22,"goal":"Ученик задаёт общий вопрос с 吗 и отвечает 是 или 不是.","theory":[{"heading":"Частица вопроса","body":"Чтобы превратить спокойное утверждение в вопрос «да или нет», поставьте <b>吗</b> в самый конец. Порядок остальных слов не меняется: 你是学生。→ 你是学生吗？"},{"heading":"Короткий ответ","body":"На такой вопрос можно ответить просто 是 («да») или 不是 («нет»). Если хотите дать полную информацию, повторите предложение: 是，我是学生。"}],"vocab":[{"hanzi":"吗","pinyin":"ma","ru":"вопросительная частица"},{"hanzi":"是","pinyin":"shì","ru":"быть; да"},{"hanzi":"不是","pinyin":"bú shì","ru":"нет; не быть"},{"hanzi":"老师","pinyin":"lǎoshī","ru":"преподаватель"},{"hanzi":"学生","pinyin":"xuéshēng","ru":"студент; ученик"},{"hanzi":"中国人","pinyin":"Zhōngguó rén","ru":"китаец; китаянка"}],"grammar":[{"rule":"Общий вопрос: утверждение + 吗？","explain":"吗 не переводится отдельным словом. Она сообщает, что ожидается ответ «да» или «нет».","examples":[{"hanzi":"你是老师吗？","pinyin":"Nǐ shì lǎoshī ma?","ru":"Вы преподаватель?"},{"hanzi":"他是中国人吗？","pinyin":"Tā shì Zhōngguó rén ma?","ru":"Он китаец?"}]}],"dialogue":{"title":"Первый урок","lines":[{"speaker":"Сун","hanzi":"你是学生吗？","pinyin":"Nǐ shì xuéshēng ma?","ru":"Ты студент?"},{"speaker":"Пётр","hanzi":"是，我是学生。","pinyin":"Shì, wǒ shì xuéshēng.","ru":"Да, я студент."},{"speaker":"Пётр","hanzi":"你是老师吗？","pinyin":"Nǐ shì lǎoshī ma?","ru":"Ты преподаватель?"},{"speaker":"Сун","hanzi":"是，我是老师。","pinyin":"Shì, wǒ shì lǎoshī.","ru":"Да, я преподаватель."}]},"exercises":[{"type":"choice","q":"Где стоит 吗 в общем вопросе?","options":["в начале","после 是","в конце"],"answer":2,"explain":"吗 всегда завершает общий вопрос."},{"type":"choice","q":"Как ответить «нет» на вопрос 你是老师吗？","options":["吗","不是","你好"],"answer":1,"explain":"不是 — короткий отрицательный ответ."},{"type":"choice","q":"Какая частица превращает фразу в общий вопрос?","options":["的","吗","呢"],"answer":1,"explain":"吗 ставят в конце вопроса «да или нет». "},{"type":"choice","q":"Какой знак ставят в конце 你是学生吗？","options":["？","。","！"],"answer":0,"explain":"Это вопрос, поэтому в конце нужен вопросительный знак."},{"type":"match","q":"Соотнесите реплику и её роль.","pairs":[{"left":"你是学生吗？","right":"вопрос"},{"left":"是。","right":"краткое «да»"},{"left":"不是。","right":"краткое «нет»"}],"explain":"По частицы 吗 видно, что первая реплика — вопрос."},{"type":"input","q":"Напишите пиньинь частицы 吗.","answer":["ma"],"explain":"吗 читается ma с нейтральным тоном."},{"type":"input","q":"Соберите иероглифами вопрос: «Ты студент?»","answer":["你是学生吗"],"explain":"Сначала 你是学生, затем в конце 吗。"}],"homework":"Превратите в вопросы три предложения: 我是学生。她是老师。那是书。Проверьте, что 吗 стоит только в конце."},{"id":7,"title":"Знакомство: 你叫什么名字？","duration":25,"goal":"Ученик спрашивает имя и представляется с помощью 叫.","theory":[{"heading":"Как спросить имя","body":"Самый частый вопрос при знакомстве — <b>你叫什么名字？</b> Буквально: «ты зовёшься каким именем?» В живом разговоре часто сокращают до 你叫什么？"},{"heading":"Как представиться","body":"Используйте схему <b>我叫 + имя</b>. После 叫 не нужно ставить 是: правильно 我叫安娜, а не 我是叫安娜."}],"vocab":[{"hanzi":"叫","pinyin":"jiào","ru":"звать; называться"},{"hanzi":"名字","pinyin":"míngzi","ru":"имя"},{"hanzi":"什么","pinyin":"shénme","ru":"что; какой"},{"hanzi":"请问","pinyin":"qǐngwèn","ru":"скажите, пожалуйста; позвольте спросить"},{"hanzi":"姓","pinyin":"xìng","ru":"фамилия; носить фамилию"},{"hanzi":"先生","pinyin":"xiānsheng","ru":"господин; мистер"},{"hanzi":"小姐","pinyin":"xiǎojiě","ru":"госпожа; мисс"}],"grammar":[{"rule":"Имя: 我叫 + имя","explain":"叫 — глагол «зваться». Субъект стоит перед ним, а имя — сразу после него.","examples":[{"hanzi":"我叫安娜。","pinyin":"Wǒ jiào Ānnà.","ru":"Меня зовут Анна."},{"hanzi":"你叫什么名字？","pinyin":"Nǐ jiào shénme míngzi?","ru":"Как тебя зовут?"}]}],"dialogue":{"title":"Знакомство на курсе","lines":[{"speaker":"Анна","hanzi":"你好！请问，你叫什么名字？","pinyin":"Nǐ hǎo! Qǐngwèn, nǐ jiào shénme míngzi?","ru":"Здравствуйте! Скажите, пожалуйста, как вас зовут?"},{"speaker":"Чэнь","hanzi":"我叫陈文。你呢？","pinyin":"Wǒ jiào Chén Wén. Nǐ ne?","ru":"Меня зовут Чэнь Вэнь. А вас?"},{"speaker":"Анна","hanzi":"我叫安娜。","pinyin":"Wǒ jiào Ānnà.","ru":"Меня зовут Анна."},{"speaker":"Чэнь","hanzi":"你好，安娜！","pinyin":"Nǐ hǎo, Ānnà!","ru":"Здравствуйте, Анна!"}]},"exercises":[{"type":"choice","q":"Какой глагол нужен в фразе «Меня зовут Ли»?","options":["叫","是","有"],"answer":0,"explain":"Чтобы назвать своё имя, используйте 叫."},{"type":"choice","q":"Что означает 你叫什么名字？","options":["Откуда ты?","Как тебя зовут?","Кто ты?"],"answer":1,"explain":"什么名字 — «какое имя», поэтому вопрос касается имени."},{"type":"choice","q":"Как спросить имя собеседника?","options":["你叫什么名字？","你是哪国人？","你在哪儿？"],"answer":0,"explain":"Вопрос с 什么名字 спрашивает имя."},{"type":"choice","q":"Что следует после 我叫?","options":["имя","профессия","место"],"answer":0,"explain":"После 我叫 сразу называют имя."},{"type":"match","q":"Соотнесите слово и перевод.","pairs":[{"left":"叫","right":"зваться"},{"left":"名字","right":"имя"},{"left":"请问","right":"скажите, пожалуйста"},{"left":"姓","right":"фамилия"}],"explain":"请问 — вежливое начало вопроса к незнакомому человеку."},{"type":"input","q":"Напишите пиньинь слова 名字.","answer":["míngzi","mingzi"],"explain":"名字 читается míngzi: второй слог нейтральный."},{"type":"input","q":"Напишите иероглифами: «Меня зовут Анна».","answer":["我叫安娜"],"explain":"После 我叫 сразу ставится имя: 安娜。"}],"homework":"Представьтесь в трёх фразах: 你好。 我叫…。 你叫什么名字？ Подставьте своё имя вместо многоточия."},{"id":8,"title":"什么 и 谁: спрашиваем о предмете и человеке","duration":24,"goal":"Ученик различает вопросительные слова 什么 и 谁 и задаёт вопросы о людях и предметах.","theory":[{"heading":"Что и кто","body":"<b>什么</b> спрашивает о предмете, названии или содержании: 这是什么？ <b>谁</b> спрашивает о человеке: 他是谁？ В китайском вопросительное слово остаётся там, где был бы ответ."},{"heading":"Не меняем порядок","body":"Не нужно переносить 什么 или 谁 в начало. Сравните: 这是书。→ 这是什么？ Он — учитель. → 他是谁？"}],"vocab":[{"hanzi":"什么","pinyin":"shénme","ru":"что; какой"},{"hanzi":"谁","pinyin":"shéi","ru":"кто"},{"hanzi":"朋友","pinyin":"péngyou","ru":"друг; подруга"},{"hanzi":"同学","pinyin":"tóngxué","ru":"однокурсник; одноклассник"},{"hanzi":"老师","pinyin":"lǎoshī","ru":"преподаватель"},{"hanzi":"东西","pinyin":"dōngxi","ru":"вещь; предмет"}],"grammar":[{"rule":"Вопрос о предмете: 这/那 是 什么？","explain":"什么 занимает место названия предмета после 是.","examples":[{"hanzi":"这是什么？","pinyin":"Zhè shì shénme?","ru":"Что это?"},{"hanzi":"那是书。","pinyin":"Nà shì shū.","ru":"То — книга."}]},{"rule":"Вопрос о человеке: 他/她 是 谁？","explain":"谁 занимает место имени или названия человека после 是.","examples":[{"hanzi":"她是谁？","pinyin":"Tā shì shéi?","ru":"Кто она?"},{"hanzi":"她是我朋友。","pinyin":"Tā shì wǒ péngyou.","ru":"Она моя подруга."}]}],"dialogue":{"title":"Фото на столе","lines":[{"speaker":"Нина","hanzi":"这是什么？","pinyin":"Zhè shì shénme?","ru":"Что это?"},{"speaker":"Хуа","hanzi":"这是书。","pinyin":"Zhè shì shū.","ru":"Это книга."},{"speaker":"Нина","hanzi":"他是谁？","pinyin":"Tā shì shéi?","ru":"Кто он?"},{"speaker":"Хуа","hanzi":"他是我同学。","pinyin":"Tā shì wǒ tóngxué.","ru":"Он мой однокурсник."}]},"exercises":[{"type":"choice","q":"Как спросить «Кто она?»","options":["她是什么？","她是谁？","谁是她？"],"answer":1,"explain":"О человеке спрашиваем с 谁: 她是谁？"},{"type":"choice","q":"Какое слово нужно в вопросе о предмете?","options":["谁","什么","吗"],"answer":1,"explain":"什么 означает «что» и заменяет название предмета."},{"type":"choice","q":"Каким словом спросить о человеке?","options":["谁","什么","哪儿"],"answer":0,"explain":"谁 значит «кто». "},{"type":"choice","q":"Каким словом спросить о предмете?","options":["谁","什么","呢"],"answer":1,"explain":"什么 значит «что». "},{"type":"match","q":"Соотнесите вопрос и подходящий ответ.","pairs":[{"left":"这是什么？","right":"这是书。"},{"left":"他是谁？","right":"他是老师。"},{"left":"她是谁？","right":"她是我朋友。"}],"explain":"什么 требует предмета, а 谁 — человека."},{"type":"input","q":"Напишите пиньинь вопросительного слова 谁.","answer":["shéi","shei"],"explain":"Кто — 谁, pinyin shéi, второй тон."},{"type":"input","q":"Напишите иероглифами: «Что это?»","answer":["这是什么"],"explain":"В вопросе 这 是 什么 什么 стоит в позиции ответа."}],"homework":"Посмотрите на пять предметов или людей вокруг. Для каждого составьте вопрос с 什么 или 谁 и дайте короткий ответ."},{"id":9,"title":"Страны и национальность: 你是哪国人？","duration":25,"goal":"Ученик спрашивает о национальности и говорит, из какой страны человек.","theory":[{"heading":"Страна и человек","body":"<b>中国</b> — Китай, <b>俄罗斯</b> — Россия. Чтобы назвать человека по стране, добавьте 人: 中国人 — китаец/китаянка, 俄罗斯人 — россиянин/россиянка."},{"heading":"Вопрос о национальности","body":"В вопросе <b>你是哪国人？</b> 哪 означает «какой; какой именно». Здесь страна стоит перед 人: сначала название страны, затем 人."}],"vocab":[{"hanzi":"中国","pinyin":"Zhōngguó","ru":"Китай"},{"hanzi":"俄罗斯","pinyin":"Èluósī","ru":"Россия"},{"hanzi":"中国人","pinyin":"Zhōngguó rén","ru":"китаец; китаянка"},{"hanzi":"俄罗斯人","pinyin":"Èluósī rén","ru":"россиянин; россиянка"},{"hanzi":"哪","pinyin":"nǎ","ru":"какой; который"},{"hanzi":"国","pinyin":"guó","ru":"страна; государство"},{"hanzi":"人","pinyin":"rén","ru":"человек"}],"grammar":[{"rule":"Национальность: страна + 人","explain":"人 ставится после названия страны и не меняется по роду.","examples":[{"hanzi":"我是中国人。","pinyin":"Wǒ shì Zhōngguó rén.","ru":"Я китаец / китаянка."},{"hanzi":"她是俄罗斯人。","pinyin":"Tā shì Èluósī rén.","ru":"Она россиянка."}]},{"rule":"Вопрос: 你是 哪国人？","explain":"哪国人 — единый вопросительный блок «человек какой страны». В разговоре часто произносят без паузы.","examples":[{"hanzi":"你是哪国人？","pinyin":"Nǐ shì nǎ guó rén?","ru":"Ты какой национальности?"},{"hanzi":"我是俄罗斯人。","pinyin":"Wǒ shì Èluósī rén.","ru":"Я россиянин / россиянка."}]}],"dialogue":{"title":"Разговор на языковом обмене","lines":[{"speaker":"Даша","hanzi":"你是哪国人？","pinyin":"Nǐ shì nǎ guó rén?","ru":"Ты какой национальности?"},{"speaker":"王伟","hanzi":"我是中国人。你呢？","pinyin":"Wǒ shì Zhōngguó rén. Nǐ ne?","ru":"Я китаец. А ты?"},{"speaker":"Даша","hanzi":"我是俄罗斯人。","pinyin":"Wǒ shì Èluósī rén.","ru":"Я россиянка."},{"speaker":"王伟","hanzi":"很高兴！","pinyin":"Hěn gāoxìng!","ru":"Очень приятно!"}]},"exercises":[{"type":"choice","q":"Как образовать «китаец/китаянка»?","options":["中国 + 是","中国 + 人","人 + 中国"],"answer":1,"explain":"К названию страны добавляют 人: 中国人."},{"type":"choice","q":"Что спрашивает фраза 你是哪国人？","options":["имя","национальность","профессию"],"answer":1,"explain":"哪国人 буквально значит «человек какой страны». "},{"type":"choice","q":"Как называется Россия по-китайски?","options":["中国","俄罗斯","北京"],"answer":1,"explain":"俄罗斯 — Россия."},{"type":"choice","q":"Что добавляют к стране в названии национальности?","options":["人","吗","的"],"answer":0,"explain":"Страна + 人 образует название национальности."},{"type":"match","q":"Соотнесите слово и перевод.","pairs":[{"left":"中国","right":"Китай"},{"left":"俄罗斯","right":"Россия"},{"left":"中国人","right":"китаец / китаянка"},{"left":"哪国人","right":"какой национальности"}],"explain":"Страны и национальности отличаются наличием 人."},{"type":"input","q":"Напишите пиньинь слова 中国人.","answer":["zhōngguó rén","zhongguo ren","zhongguoren"],"explain":"中国人 читается Zhōngguó rén: Китай + человек."},{"type":"input","q":"Напишите иероглифами: «Я россиянин/россиянка».","answer":["我是俄罗斯人"],"explain":"Схема: 我 + 是 + 俄罗斯人。"}],"homework":"Напишите мини-представление из двух фраз: 我叫… 。我是俄罗斯人。 Затем задайте воображаемому собеседнику вопрос 你是哪国人？"},{"id":10,"title":"Профессии: 老师、学生、医生","duration":24,"goal":"Ученик называет профессию или род занятий с помощью 我是…","theory":[{"heading":"Три полезных слова","body":"<b>老师</b> — преподаватель, <b>学生</b> — ученик или студент, <b>医生</b> — врач. В китайском языке эти слова не меняются по роду: 老师 может быть и мужчина, и женщина."},{"heading":"Говорим о занятии","body":"Чтобы сообщить, кем вы являетесь, используйте уже знакомую связку: 我是老师。 Для вопроса добавьте 吗: 你是医生吗？"}],"vocab":[{"hanzi":"老师","pinyin":"lǎoshī","ru":"преподаватель"},{"hanzi":"学生","pinyin":"xuéshēng","ru":"студент; ученик"},{"hanzi":"医生","pinyin":"yīshēng","ru":"врач"},{"hanzi":"医院","pinyin":"yīyuàn","ru":"больница"},{"hanzi":"工作","pinyin":"gōngzuò","ru":"работа; работать"},{"hanzi":"同学","pinyin":"tóngxué","ru":"однокурсник; одноклассник"}],"grammar":[{"rule":"Профессия: подлежащее + 是 + профессия","explain":"Название профессии или статуса ставится после 是. Отдельное слово «по профессии» не нужно.","examples":[{"hanzi":"我是老师。","pinyin":"Wǒ shì lǎoshī.","ru":"Я преподаватель."},{"hanzi":"她是医生。","pinyin":"Tā shì yīshēng.","ru":"Она врач."}]}],"dialogue":{"title":"В коридоре школы","lines":[{"speaker":"Максим","hanzi":"你是老师吗？","pinyin":"Nǐ shì lǎoshī ma?","ru":"Вы преподаватель?"},{"speaker":"Лин","hanzi":"不是，我是学生。","pinyin":"Bú shì, wǒ shì xuéshēng.","ru":"Нет, я студентка."},{"speaker":"Максим","hanzi":"她是谁？","pinyin":"Tā shì shéi?","ru":"Кто она?"},{"speaker":"Лин","hanzi":"她是医生。","pinyin":"Tā shì yīshēng.","ru":"Она врач."}]},"exercises":[{"type":"choice","q":"Как по-китайски «врач»?","options":["老师","医生","学生"],"answer":1,"explain":"医生 — врач; дословно «медицинский человек». "},{"type":"choice","q":"Как сказать «Я преподаватель»?","options":["我叫老师。","我是老师。","我有老师。"],"answer":1,"explain":"После 我 ставим 是 и название профессии."},{"type":"choice","q":"Кто работает в больнице?","options":["医生","学生","同学"],"answer":0,"explain":"医生 — врач; 医院 — больница."},{"type":"choice","q":"Каким словом назвать преподавателя?","options":["老师","医生","朋友"],"answer":0,"explain":"老师 — преподаватель."},{"type":"match","q":"Соотнесите слово и значение.","pairs":[{"left":"老师","right":"преподаватель"},{"left":"学生","right":"студент"},{"left":"医生","right":"врач"},{"left":"医院","right":"больница"}],"explain":"医院 — место, где работает 医生."},{"type":"input","q":"Напишите пиньинь слова 学生.","answer":["xuéshēng","xuesheng"],"explain":"学生 читается xuéshēng: второй и первый тоны."},{"type":"input","q":"Напишите иероглифами: «Она врач».","answer":["她是医生"],"explain":"Схема: 她 + 是 + 医生。"}],"homework":"Расскажите о трёх людях по моделям: 我是学生。 他是老师。 她是医生。 Замените местоимения и профессии по своему выбору."},{"id":11,"title":"的: мой, твой, его","duration":24,"goal":"Ученик показывает принадлежность с помощью 的 и строит короткие именные группы.","theory":[{"heading":"Чей это предмет или человек","body":"<b>的</b> связывает того, кому что-то принадлежит, и сам предмет: 我的名字 — «моё имя», 你的老师 — «твой преподаватель». Слово-владелец всегда стоит перед 的."},{"heading":"Местоимения перед 的","body":"После 我、你、他、她 можно спокойно ставить 的: 我的、你的、他的、她的. Не путайте 她的 («её») и 他的 («его»): произносятся они одинаково, но пишутся по-разному."}],"vocab":[{"hanzi":"的","pinyin":"de","ru":"показатель принадлежности"},{"hanzi":"我的","pinyin":"wǒ de","ru":"мой; моя; моё"},{"hanzi":"你的","pinyin":"nǐ de","ru":"твой; ваш"},{"hanzi":"他的","pinyin":"tā de","ru":"его"},{"hanzi":"她的","pinyin":"tā de","ru":"её"},{"hanzi":"名字","pinyin":"míngzi","ru":"имя"},{"hanzi":"朋友","pinyin":"péngyou","ru":"друг; подруга"}],"grammar":[{"rule":"Принадлежность: владелец + 的 + предмет","explain":"的 не переводится отдельно, но связывает две части как русское «чей?». Главное слово находится после 的.","examples":[{"hanzi":"我的名字是安娜。","pinyin":"Wǒ de míngzi shì Ānnà.","ru":"Моё имя — Анна."},{"hanzi":"他是你的老师。","pinyin":"Tā shì nǐ de lǎoshī.","ru":"Он твой преподаватель."}]}],"dialogue":{"title":"Чьи это вещи?","lines":[{"speaker":"Илья","hanzi":"这是谁的书？","pinyin":"Zhè shì shéi de shū?","ru":"Чья это книга?"},{"speaker":"Мэй","hanzi":"这是我的书。","pinyin":"Zhè shì wǒ de shū.","ru":"Это моя книга."},{"speaker":"Илья","hanzi":"那是她的书吗？","pinyin":"Nà shì tā de shū ma?","ru":"То её книга?"},{"speaker":"Мэй","hanzi":"不是，那是他的书。","pinyin":"Bú shì, nà shì tā de shū.","ru":"Нет, то его книга."}]},"exercises":[{"type":"choice","q":"Что стоит между владельцем и предметом?","options":["吗","的","是"],"answer":1,"explain":"的 связывает владельца и то, что ему принадлежит."},{"type":"choice","q":"Как перевести 你的老师?","options":["твой преподаватель","ты преподаватель","преподаватель тебя"],"answer":0,"explain":"你 — «ты», 的 показывает принадлежность, 老师 — «преподаватель». "},{"type":"choice","q":"Что означает 他的书?","options":["его книга","её книга","твоя книга"],"answer":0,"explain":"他 — «он», 的 показывает принадлежность."},{"type":"choice","q":"Где стоит предмет в группе 我的名字?","options":["до 的","после 的","вместо 的"],"answer":1,"explain":"Главное слово 名字 стоит после 的."},{"type":"match","q":"Соотнесите группу и перевод.","pairs":[{"left":"我的朋友","right":"мой друг"},{"left":"你的名字","right":"твоё имя"},{"left":"他的书","right":"его книга"},{"left":"她的老师","right":"её преподаватель"}],"explain":"В каждой группе главное слово стоит в конце."},{"type":"input","q":"Напишите пиньинь слова 我的.","answer":["wǒ de","wo de","wode"],"explain":"我的 читается wǒ de; 的 здесь произносится нейтрально."},{"type":"input","q":"Напишите иероглифами: «её имя».","answer":["她的名字"],"explain":"Владелец 她, затем 的, затем предмет 名字。"}],"homework":"Напишите четыре сочетания с 的: моё имя, твой друг, его книга, её преподаватель. Прочитайте их слева направо без пауз."},{"id":12,"title":"有 и 没有: что у нас есть","duration":24,"goal":"Ученик говорит о наличии предметов и людей с 有 и отрицает это с 没有.","theory":[{"heading":"Значение 有","body":"<b>有</b> означает «иметь; есть». Оно подходит и для личного обладания, и для наличия где-то: 我有书 — «у меня есть книга»; 家里有水 — «дома есть вода»."},{"heading":"Отрицание наличия","body":"У 有 особое отрицание: <b>没有</b>, а не 不有. В вопросе можно сказать 你有书吗？ и ответить 有 или 没有."}],"vocab":[{"hanzi":"有","pinyin":"yǒu","ru":"иметь; есть"},{"hanzi":"没有","pinyin":"méiyǒu","ru":"не иметь; нет"},{"hanzi":"书","pinyin":"shū","ru":"книга"},{"hanzi":"水","pinyin":"shuǐ","ru":"вода"},{"hanzi":"钱","pinyin":"qián","ru":"деньги"},{"hanzi":"家","pinyin":"jiā","ru":"дом; семья"},{"hanzi":"朋友","pinyin":"péngyou","ru":"друг; подруга"}],"grammar":[{"rule":"Наличие: кто/где + 有 + предмет","explain":"Тот, кто имеет предмет, или место, где он находится, ставится перед 有.","examples":[{"hanzi":"我有朋友。","pinyin":"Wǒ yǒu péngyou.","ru":"У меня есть друг."},{"hanzi":"家里有水。","pinyin":"Jiā li yǒu shuǐ.","ru":"Дома есть вода."}]},{"rule":"Отрицание: кто/где + 没有 + предмет","explain":"没有 целиком заменяет 有 и уже содержит отрицание.","examples":[{"hanzi":"我没有钱。","pinyin":"Wǒ méiyǒu qián.","ru":"У меня нет денег."},{"hanzi":"他没有书。","pinyin":"Tā méiyǒu shū.","ru":"У него нет книги."}]}],"dialogue":{"title":"Перед поездкой","lines":[{"speaker":"Саша","hanzi":"你有水吗？","pinyin":"Nǐ yǒu shuǐ ma?","ru":"У тебя есть вода?"},{"speaker":"Вэй","hanzi":"有，我有水。","pinyin":"Yǒu, wǒ yǒu shuǐ.","ru":"Да, у меня есть вода."},{"speaker":"Саша","hanzi":"你有钱吗？","pinyin":"Nǐ yǒu qián ma?","ru":"У тебя есть деньги?"},{"speaker":"Вэй","hanzi":"没有，我没有钱。","pinyin":"Méiyǒu, wǒ méiyǒu qián.","ru":"Нет, у меня нет денег."}]},"exercises":[{"type":"choice","q":"Как правильно сказать «У меня нет книги»?","options":["我不是书。","我不有书。","我没有书。"],"answer":2,"explain":"Наличие с 有 отрицается словом 没有."},{"type":"choice","q":"Что означает 有?","options":["иметь; есть","быть кем-то","нравиться"],"answer":0,"explain":"有 сообщает о наличии или обладании."},{"type":"choice","q":"Какой глагол означает «иметь»?","options":["有","是","在"],"answer":0,"explain":"有 говорит о наличии или обладании."},{"type":"choice","q":"Что отвечает на вопрос 你有钱吗？, если денег нет?","options":["没有","不是","不客气"],"answer":0,"explain":"Нет денег — 没有。"},{"type":"match","q":"Соотнесите фразу и перевод.","pairs":[{"left":"我有书。","right":"У меня есть книга."},{"left":"她没有钱。","right":"У неё нет денег."},{"left":"家里有水。","right":"Дома есть вода."}],"explain":"有 — наличие, 没有 — отсутствие."},{"type":"input","q":"Напишите пиньинь слова 没有.","answer":["méiyǒu","meiyou"],"explain":"没有 читается méiyǒu: второй и третий тоны."},{"type":"input","q":"Напишите иероглифами: «У него есть друг».","answer":["他有朋友"],"explain":"Схема: 他 + 有 + 朋友。"}],"homework":"Напишите четыре правдивые или вымышленные фразы: две с 有 и две с 没有. Используйте 书、水、钱、朋友."},{"id":13,"title":"很 и 太: описываем предметы","duration":24,"goal":"Ученик описывает предметы и людей с 很 и 太, используя базовые прилагательные.","theory":[{"heading":"Наречие 很","body":"<b>很</b> перед прилагательным часто просто связывает подлежащее с признаком; его не всегда нужно переводить как «очень». 我很好 может значить и «у меня всё хорошо», и «я очень хорош»."},{"heading":"Слово 太","body":"<b>太</b> усиливает признак: 太大 — «слишком большой» или «очень большой» в зависимости от ситуации. Часто после него добавляют 了: 太好了！ — «Как здорово!»"}],"vocab":[{"hanzi":"很","pinyin":"hěn","ru":"очень; довольно"},{"hanzi":"太","pinyin":"tài","ru":"слишком; очень"},{"hanzi":"好","pinyin":"hǎo","ru":"хороший; хорошо"},{"hanzi":"大","pinyin":"dà","ru":"большой"},{"hanzi":"小","pinyin":"xiǎo","ru":"маленький"},{"hanzi":"多","pinyin":"duō","ru":"много"},{"hanzi":"少","pinyin":"shǎo","ru":"мало"}],"grammar":[{"rule":"Описание: подлежащее + 很 + прилагательное","explain":"Когда говорим о качестве, 很 ставится прямо перед прилагательным.","examples":[{"hanzi":"这个书包很大。","pinyin":"Zhège shūbāo hěn dà.","ru":"Этот рюкзак большой."},{"hanzi":"她很好。","pinyin":"Tā hěn hǎo.","ru":"У неё всё хорошо."}]},{"rule":"Сильная оценка: 太 + прилагательное + 了","explain":"了 в такой восклицательной фразе передаёт эмоцию, а не прошедшее время.","examples":[{"hanzi":"太好了！","pinyin":"Tài hǎo le!","ru":"Как здорово!"},{"hanzi":"这个太小了。","pinyin":"Zhège tài xiǎo le.","ru":"Этот слишком маленький."}]}],"dialogue":{"title":"Выбираем книгу","lines":[{"speaker":"Лена","hanzi":"这个大吗？","pinyin":"Zhège dà ma?","ru":"Это большое?"},{"speaker":"Фан","hanzi":"不大，很小。","pinyin":"Bú dà, hěn xiǎo.","ru":"Не большое, очень маленькое."},{"speaker":"Лена","hanzi":"那个呢？","pinyin":"Nàge ne?","ru":"А то?"},{"speaker":"Фан","hanzi":"那个太大了。","pinyin":"Nàge tài dà le.","ru":"То слишком большое."}]},"exercises":[{"type":"choice","q":"Какое слово ставят перед прилагательным в спокойном описании?","options":["很","有","谁"],"answer":0,"explain":"很 связывает подлежащее и признак: 很好, 很大."},{"type":"choice","q":"Что означает 太好了！?","options":["Слишком плохо.","Как здорово!","У меня есть хорошо."],"answer":1,"explain":"太 усиливает 好, а 了 добавляет эмоциональную оценку."},{"type":"choice","q":"Какое слово значит «большой»?","options":["大","小","多"],"answer":0,"explain":"大 описывает большой размер."},{"type":"choice","q":"Как выразить сильную оценку «Как здорово!»?","options":["太好了！","没有好。","在好了。"],"answer":0,"explain":"太 + 好 + 了 создаёт эмоциональную похвалу."},{"type":"match","q":"Соотнесите слово и перевод.","pairs":[{"left":"大","right":"большой"},{"left":"小","right":"маленький"},{"left":"多","right":"много"},{"left":"少","right":"мало"}],"explain":"Это базовые слова для описания размера и количества."},{"type":"input","q":"Напишите пиньинь слова 很好.","answer":["hěn hǎo","hen hao","henhao"],"explain":"很好 читается hěn hǎo: оба слога в третьем тоне."},{"type":"input","q":"Напишите иероглифами: «очень маленький».","answer":["很小"],"explain":"很 стоит перед прилагательным 小。"}],"homework":"Опишите четыре вещи вокруг по моделям 很大、很小、太大了、太好了. Хотя бы одну фразу произнесите с восклицательной интонацией."},{"id":14,"title":"Как дела: 你好吗？我很好。你呢？","duration":22,"goal":"Ученик спрашивает о самочувствии, отвечает и возвращает вопрос частицей 呢.","theory":[{"heading":"Простой обмен «как дела»","body":"<b>你好吗？</b> — дружелюбный вопрос «Как дела?». Типичный ответ: 我很好 — «У меня всё хорошо». Можно сказать 也很好 — «тоже хорошо». "},{"heading":"Короткое «а ты?»","body":"<b>呢</b> в конце оставляет понятную часть вопроса без повторения. 你呢？ означает «А ты?»; она отсылает к только что сказанному вопросу о самочувствии."}],"vocab":[{"hanzi":"好吗","pinyin":"hǎo ma","ru":"хорошо ли; как дела"},{"hanzi":"很好","pinyin":"hěn hǎo","ru":"очень хорошо; всё хорошо"},{"hanzi":"呢","pinyin":"ne","ru":"а ...?; что насчёт ...?"},{"hanzi":"也","pinyin":"yě","ru":"тоже"},{"hanzi":"怎么样","pinyin":"zěnmeyàng","ru":"как; каким образом"},{"hanzi":"高兴","pinyin":"gāoxìng","ru":"рад; приятно"}],"grammar":[{"rule":"Вопрос о самочувствии: 你好吗？","explain":"Это готовая формула, в которой 好 показывает состояние. В ответе называйте себя: 我很好。","examples":[{"hanzi":"你好吗？","pinyin":"Nǐ hǎo ma?","ru":"Как дела?"},{"hanzi":"我很好。","pinyin":"Wǒ hěn hǎo.","ru":"У меня всё хорошо."}]},{"rule":"Уточнение: существительное/местоимение + 呢？","explain":"呢 заменяет повторение уже понятной части. После ответа «я хорошо» спросите 你呢？","examples":[{"hanzi":"我很好，你呢？","pinyin":"Wǒ hěn hǎo, nǐ ne?","ru":"У меня всё хорошо, а ты?"},{"hanzi":"她呢？","pinyin":"Tā ne?","ru":"А она?"}]}],"dialogue":{"title":"Созвон друзей","lines":[{"speaker":"Женя","hanzi":"你好吗？","pinyin":"Nǐ hǎo ma?","ru":"Как дела?"},{"speaker":"Лю Синь","hanzi":"我很好。你呢？","pinyin":"Wǒ hěn hǎo. Nǐ ne?","ru":"У меня всё хорошо. А ты?"},{"speaker":"Женя","hanzi":"我也很好。","pinyin":"Wǒ yě hěn hǎo.","ru":"У меня тоже всё хорошо."},{"speaker":"Лю Синь","hanzi":"很高兴！","pinyin":"Hěn gāoxìng!","ru":"Очень приятно!"}]},"exercises":[{"type":"choice","q":"Что значит 你呢？","options":["Кто ты?","А ты?","Ты где?"],"answer":1,"explain":"呢 заменяет повторение понятной части вопроса."},{"type":"choice","q":"Как ответить «У меня тоже всё хорошо»?","options":["我也很好。","我没有好。","我是很好。"],"answer":0,"explain":"也 означает «тоже» и стоит перед 很好."},{"type":"choice","q":"Что означает 也?","options":["тоже","где","кто"],"answer":0,"explain":"也 добавляет значение «тоже». "},{"type":"choice","q":"Что можно спросить после 我很好?","options":["你呢？","你是谁？","你有吗？"],"answer":0,"explain":"你呢？ возвращает тот же вопрос собеседнику."},{"type":"match","q":"Соотнесите фразу и перевод.","pairs":[{"left":"你好吗？","right":"Как дела?"},{"left":"我很好。","right":"У меня всё хорошо."},{"left":"你呢？","right":"А ты?"},{"left":"我也很好。","right":"У меня тоже всё хорошо."}],"explain":"也 добавляет «тоже», а 呢 возвращает вопрос собеседнику."},{"type":"input","q":"Напишите пиньинь частицы 呢.","answer":["ne"],"explain":"呢 произносится нейтральным тоном: ne."},{"type":"input","q":"Напишите иероглифами: «Как дела?»","answer":["你好吗"],"explain":"В конце вопроса стоит частица 吗: 你好吗？"}],"homework":"Запишите и прочитайте диалог из четырёх реплик: 你好吗？— 我很好。你呢？— 我也很好。— 很高兴！"},{"id":15,"title":"喜欢 и 想: что нравится и чего хочется","duration":25,"goal":"Ученик говорит о своих предпочтениях и желаниях с 喜欢 и 想.","theory":[{"heading":"Мне нравится","body":"<b>喜欢</b> выражает устойчивую симпатию: 喜欢茶 — «нравится чай», 喜欢看电影 — «нравится смотреть фильмы». После 喜欢 может идти предмет или действие."},{"heading":"Я хочу","body":"<b>想</b> выражает желание или намерение: 想喝水 — «хочу пить воду». После 想 обычно ставят глагол, а затем его объект: 想 + 喝 + 水."}],"vocab":[{"hanzi":"喜欢","pinyin":"xǐhuan","ru":"нравиться; любить"},{"hanzi":"想","pinyin":"xiǎng","ru":"хотеть; думать"},{"hanzi":"茶","pinyin":"chá","ru":"чай"},{"hanzi":"咖啡","pinyin":"kāfēi","ru":"кофе"},{"hanzi":"电影","pinyin":"diànyǐng","ru":"фильм"},{"hanzi":"看","pinyin":"kàn","ru":"смотреть; читать"},{"hanzi":"喝","pinyin":"hē","ru":"пить"}],"grammar":[{"rule":"Предпочтение: подлежащее + 喜欢 + объект/действие","explain":"После 喜欢 поставьте то, что вам нравится. Если это действие, глагол остаётся перед предметом.","examples":[{"hanzi":"我喜欢茶。","pinyin":"Wǒ xǐhuan chá.","ru":"Мне нравится чай."},{"hanzi":"她喜欢看电影。","pinyin":"Tā xǐhuan kàn diànyǐng.","ru":"Ей нравится смотреть фильмы."}]},{"rule":"Желание: подлежащее + 想 + глагол + объект","explain":"想 не равно 有 и не требует 是. Сразу после него ставьте желаемое действие.","examples":[{"hanzi":"我想喝水。","pinyin":"Wǒ xiǎng hē shuǐ.","ru":"Я хочу пить воду."},{"hanzi":"你想看电影吗？","pinyin":"Nǐ xiǎng kàn diànyǐng ma?","ru":"Ты хочешь посмотреть фильм?"}]}],"dialogue":{"title":"В кафе","lines":[{"speaker":"Артём","hanzi":"你喜欢茶吗？","pinyin":"Nǐ xǐhuan chá ma?","ru":"Тебе нравится чай?"},{"speaker":"Ян","hanzi":"喜欢，我喜欢茶。","pinyin":"Xǐhuan, wǒ xǐhuan chá.","ru":"Да, мне нравится чай."},{"speaker":"Артём","hanzi":"你想喝什么？","pinyin":"Nǐ xiǎng hē shénme?","ru":"Что ты хочешь пить?"},{"speaker":"Ян","hanzi":"我想喝咖啡。","pinyin":"Wǒ xiǎng hē kāfēi.","ru":"Я хочу пить кофе."}]},"exercises":[{"type":"choice","q":"Какой глагол выражает «нравиться»?","options":["喜欢","想","有"],"answer":0,"explain":"喜欢 используется для симпатии и предпочтений."},{"type":"choice","q":"Какой порядок верен для «Я хочу пить чай»?","options":["我想茶喝。","我想喝茶。","我喝想茶。"],"answer":1,"explain":"После 想 идёт глагол 喝, затем объект 茶."},{"type":"choice","q":"Что выражает 想?","options":["желание","наличие","место"],"answer":0,"explain":"想 ставят перед действием, которое хочется сделать."},{"type":"choice","q":"Что можно поставить после 喜欢?","options":["茶","在","吗"],"answer":0,"explain":"После 喜欢 можно назвать любимый предмет, например 茶."},{"type":"match","q":"Соотнесите сочетание и перевод.","pairs":[{"left":"喜欢茶","right":"нравится чай"},{"left":"想喝水","right":"хочу пить воду"},{"left":"喜欢看电影","right":"нравится смотреть фильмы"}],"explain":"喜欢 выражает предпочтение, а 想 — желание действия."},{"type":"input","q":"Напишите пиньинь слова 喜欢.","answer":["xǐhuan","xihuan"],"explain":"喜欢 читается xǐhuan: второй слог нейтральный."},{"type":"input","q":"Напишите иероглифами: «Я хочу пить воду».","answer":["我想喝水"],"explain":"Схема: 我 + 想 + 喝 + 水。"}],"homework":"Напишите по две фразы: что вам нравится и что вы хотите сделать сейчас. Используйте 喜欢 и 想 по одному разу."},{"id":16,"title":"Простое предложение: кто + действие + объект","duration":26,"goal":"Ученик строит простые предложения с 吃、喝、看、说 и дополнением.","theory":[{"heading":"Базовый порядок слов","body":"В простом китайском предложении удобно держать схему: <b>кто + глагол + что</b>. Например, 我喝水: «я пью воду». Не ставьте объект перед глаголом, как иногда бывает по-русски."},{"heading":"Четыре полезных действия","body":"<b>吃</b> — есть, <b>喝</b> — пить, <b>看</b> — смотреть или читать, <b>说</b> — говорить. Один и тот же порядок работает со всеми четырьмя: 他看书, 她说汉语."}],"vocab":[{"hanzi":"吃","pinyin":"chī","ru":"есть"},{"hanzi":"喝","pinyin":"hē","ru":"пить"},{"hanzi":"看","pinyin":"kàn","ru":"смотреть; читать"},{"hanzi":"说","pinyin":"shuō","ru":"говорить"},{"hanzi":"米饭","pinyin":"mǐfàn","ru":"варёный рис; еда"},{"hanzi":"水","pinyin":"shuǐ","ru":"вода"},{"hanzi":"汉语","pinyin":"Hànyǔ","ru":"китайский язык"},{"hanzi":"书","pinyin":"shū","ru":"книга"}],"grammar":[{"rule":"Простое предложение: подлежащее + глагол + дополнение","explain":"Подлежащее показывает, кто действует, глагол — что делает, дополнение — на что направлено действие.","examples":[{"hanzi":"我吃米饭。","pinyin":"Wǒ chī mǐfàn.","ru":"Я ем рис."},{"hanzi":"她看书。","pinyin":"Tā kàn shū.","ru":"Она читает книгу."}]},{"rule":"Язык после 说: 说 + язык","explain":"После 说 назовите язык, на котором говорит человек.","examples":[{"hanzi":"他说汉语。","pinyin":"Tā shuō Hànyǔ.","ru":"Он говорит по-китайски."},{"hanzi":"我说汉语。","pinyin":"Wǒ shuō Hànyǔ.","ru":"Я говорю по-китайски."}]}],"dialogue":{"title":"В столовой","lines":[{"speaker":"Коля","hanzi":"你吃米饭吗？","pinyin":"Nǐ chī mǐfàn ma?","ru":"Ты ешь рис?"},{"speaker":"周","hanzi":"吃，我吃米饭。","pinyin":"Chī, wǒ chī mǐfàn.","ru":"Да, я ем рис."},{"speaker":"Коля","hanzi":"你喝什么？","pinyin":"Nǐ hē shénme?","ru":"Что ты пьёшь?"},{"speaker":"周","hanzi":"我喝水。","pinyin":"Wǒ hē shuǐ.","ru":"Я пью воду."},{"speaker":"Коля","hanzi":"你说汉语吗？","pinyin":"Nǐ shuō Hànyǔ ma?","ru":"Ты говоришь по-китайски?"},{"speaker":"周","hanzi":"一点儿。","pinyin":"Yìdiǎnr.","ru":"Немного."}]},"exercises":[{"type":"choice","q":"Какой порядок слов в фразе «Она читает книгу»?","options":["她书看。","看她书。","她看书。"],"answer":2,"explain":"Сначала кто: 她, затем действие: 看, затем объект: 书."},{"type":"choice","q":"Что означает 说汉语?","options":["читать книгу","говорить по-китайски","пить чай"],"answer":1,"explain":"说 — «говорить», 汉语 — «китайский язык». "},{"type":"choice","q":"Какой глагол значит «пить»?","options":["喝","吃","看"],"answer":0,"explain":"喝 употребляется с напитками."},{"type":"choice","q":"Что поставить после 看 в «читать книгу»?","options":["书","水","汉语"],"answer":0,"explain":"看书 — читать книгу."},{"type":"match","q":"Соотнесите глагол и объект.","pairs":[{"left":"吃","right":"米饭"},{"left":"喝","right":"水"},{"left":"看","right":"书"},{"left":"说","right":"汉语"}],"explain":"Эти сочетания естественны и образуют простые фразы."},{"type":"input","q":"Напишите пиньинь глагола 吃.","answer":["chī","chi"],"explain":"吃 читается chī, первый тон."},{"type":"input","q":"Напишите иероглифами: «Я пью воду».","answer":["我喝水"],"explain":"Схема: 我 + 喝 + 水。"}],"homework":"Составьте четыре предложения по образцу 我吃米饭。 Используйте все глаголы: 吃、喝、看、说."},{"id":17,"title":"这、那、这个、那个: указываем на предмет","duration":24,"goal":"Ученик различает близкие и далёкие предметы и называет их с 这、那、这个、那个.","theory":[{"heading":"Близко и далеко","body":"<b>这</b> значит «это; этот» — предмет рядом. <b>那</b> значит «то; тот» — предмет дальше от говорящего. Смысл похож на русские «этот» и «тот». "},{"heading":"Счётное слово 个","body":"Перед многими существительными после 这 или 那 ставят <b>个</b>: 这个人 — «этот человек», 那个朋友 — «тот друг». В разговоре часто слышно сокращённые 这个 и 那个, когда предмет понятен из ситуации."}],"vocab":[{"hanzi":"这","pinyin":"zhè","ru":"это; этот"},{"hanzi":"那","pinyin":"nà","ru":"то; тот"},{"hanzi":"这个","pinyin":"zhège","ru":"этот; это"},{"hanzi":"那个","pinyin":"nàge","ru":"тот; то"},{"hanzi":"个","pinyin":"gè","ru":"универсальное счётное слово"},{"hanzi":"猫","pinyin":"māo","ru":"кошка"},{"hanzi":"狗","pinyin":"gǒu","ru":"собака"},{"hanzi":"杯子","pinyin":"bēizi","ru":"чашка; стакан"}],"grammar":[{"rule":"Указание на предмет: 这/那 + счётное слово + существительное","explain":"Для многих предметов используйте 个. Это помогает связать указательное слово с существительным.","examples":[{"hanzi":"这个人是老师。","pinyin":"Zhège rén shì lǎoshī.","ru":"Этот человек — преподаватель."},{"hanzi":"那个是我的杯子。","pinyin":"Nàge shì wǒ de bēizi.","ru":"То — моя чашка."}]},{"rule":"Вопрос: 这/那 是 什么？","explain":"Если предмет уже указан, можно спросить о нём с 什么.","examples":[{"hanzi":"这个是什么？","pinyin":"Zhège shì shénme?","ru":"Что это?"},{"hanzi":"那是猫。","pinyin":"Nà shì māo.","ru":"То кошка."}]}],"dialogue":{"title":"На улице","lines":[{"speaker":"Света","hanzi":"这是什么？","pinyin":"Zhè shì shénme?","ru":"Что это?"},{"speaker":"Го","hanzi":"这是猫。","pinyin":"Zhè shì māo.","ru":"Это кошка."},{"speaker":"Света","hanzi":"那个呢？","pinyin":"Nàge ne?","ru":"А то?"},{"speaker":"Го","hanzi":"那是狗。","pinyin":"Nà shì gǒu.","ru":"То собака."},{"speaker":"Света","hanzi":"这个猫很小。","pinyin":"Zhège māo hěn xiǎo.","ru":"Эта кошка маленькая."}]},"exercises":[{"type":"choice","q":"Какое слово указывает на предмет рядом?","options":["那","这","谁"],"answer":1,"explain":"这 используют для близкого предмета."},{"type":"choice","q":"Что означает 那个?","options":["этот","тот","какой"],"answer":1,"explain":"那 — «тот», 个 связывает его с существительным."},{"type":"choice","q":"Какое слово указывает на дальний предмет?","options":["那","这","个"],"answer":0,"explain":"那 значит «тот; вон тот». "},{"type":"choice","q":"Что добавляют после 这 перед 人?","options":["个","吗","很"],"answer":0,"explain":"这个人 — «этот человек». "},{"type":"match","q":"Соотнесите слово и значение.","pairs":[{"left":"这","right":"этот, рядом"},{"left":"那","right":"тот, дальше"},{"left":"这个人","right":"этот человек"},{"left":"那个朋友","right":"тот друг"}],"explain":"个 — счётное слово, которое часто появляется после 这 и 那."},{"type":"input","q":"Напишите пиньинь слова 这个.","answer":["zhège","zhege"],"explain":"这个 читается zhège: четвёртый и нейтральный тоны."},{"type":"input","q":"Напишите иероглифами: «тот друг».","answer":["那个朋友"],"explain":"Здесь 那 указывает на удалённого человека, а 个 связывает его со словом 朋友."}],"homework":"Покажите на четыре объекта вокруг и скажите по-китайски: 这是… / 那是… . Для двух объектов используйте 这个 или 那个."},{"id":18,"title":"在: где находится человек","duration":24,"goal":"Ученик сообщает, где находится человек, с помощью 在.","theory":[{"heading":"Где кто-то находится","body":"<b>在</b> перед местом означает «находиться в; быть в». Место ставится после 在: 我在家 — «я дома», 他在学校 — «он в школе». "},{"heading":"Вопрос о месте","body":"Чтобы спросить «где?», поставьте <b>哪儿</b> там, где ожидаете место: 你在哪儿？ Не добавляйте 是: неправильно 你是在哪儿？"}],"vocab":[{"hanzi":"在","pinyin":"zài","ru":"находиться в; в"},{"hanzi":"家","pinyin":"jiā","ru":"дом; семья"},{"hanzi":"学校","pinyin":"xuéxiào","ru":"школа"},{"hanzi":"北京","pinyin":"Běijīng","ru":"Пекин"},{"hanzi":"哪儿","pinyin":"nǎr","ru":"где"},{"hanzi":"这里","pinyin":"zhèlǐ","ru":"здесь"},{"hanzi":"那里","pinyin":"nàlǐ","ru":"там"}],"grammar":[{"rule":"Место: подлежащее + 在 + место","explain":"Сначала назовите человека, затем 在 и место его нахождения.","examples":[{"hanzi":"我在家。","pinyin":"Wǒ zài jiā.","ru":"Я дома."},{"hanzi":"他在学校。","pinyin":"Tā zài xuéxiào.","ru":"Он в школе."}]},{"rule":"Вопрос о месте: подлежащее + 在 + 哪儿？","explain":"哪儿 заменяет название места и остаётся после 在.","examples":[{"hanzi":"你在哪儿？","pinyin":"Nǐ zài nǎr?","ru":"Где ты?"},{"hanzi":"我在这里。","pinyin":"Wǒ zài zhèlǐ.","ru":"Я здесь."}]}],"dialogue":{"title":"Сообщения друзьям","lines":[{"speaker":"Рома","hanzi":"你在哪儿？","pinyin":"Nǐ zài nǎr?","ru":"Где ты?"},{"speaker":"Лань","hanzi":"我在学校。","pinyin":"Wǒ zài xuéxiào.","ru":"Я в школе."},{"speaker":"Рома","hanzi":"她在家吗？","pinyin":"Tā zài jiā ma?","ru":"Она дома?"},{"speaker":"Лань","hanzi":"是，她在家。","pinyin":"Shì, tā zài jiā.","ru":"Да, она дома."},{"speaker":"Рома","hanzi":"我在这里。","pinyin":"Wǒ zài zhèlǐ.","ru":"Я здесь."}]},"exercises":[{"type":"choice","q":"Какой порядок верен для «Он в школе»?","options":["他学校在。","他在学校。","在他学校。"],"answer":1,"explain":"После подлежащего ставим 在, затем место."},{"type":"choice","q":"Что заменяет 哪儿 в вопросе 你在哪儿？","options":["имя","место","профессию"],"answer":1,"explain":"哪儿 — вопросительное слово «где». "},{"type":"choice","q":"Какое слово означает «школа»?","options":["学校","医院","中国"],"answer":0,"explain":"学校 — школа."},{"type":"choice","q":"Что поставить после 在 в «Я в Пекине»?","options":["北京","我","很"],"answer":0,"explain":"После 在 называют место: 北京."},{"type":"match","q":"Соотнесите фразу и перевод.","pairs":[{"left":"我在家。","right":"Я дома."},{"left":"他在学校。","right":"Он в школе."},{"left":"你在哪儿？","right":"Где ты?"},{"left":"我在这里。","right":"Я здесь."}],"explain":"在 связывает человека с местом нахождения."},{"type":"input","q":"Напишите пиньинь слова 学校.","answer":["xuéxiào","xuexiao"],"explain":"学校 читается xuéxiào: второй и четвёртый тоны."},{"type":"input","q":"Напишите иероглифами: «Я дома».","answer":["我在家"],"explain":"Схема: 我 + 在 + 家。"}],"homework":"Напишите мини-переписку из четырёх строк: вопрос 你在哪儿？ и три ответа с 家、学校、这里."},{"id":19,"title":"Диалог-знакомство: собираем изученное","duration":28,"goal":"Ученик ведёт короткий связный разговор: здоровается, представляется, спрашивает национальность, занятие и место.","theory":[{"heading":"Логика первого разговора","body":"Связный диалог легче строить по шагам: приветствие → имя → национальность или занятие → один дополнительный вопрос → прощание. Не пытайтесь в одной реплике сказать всё сразу."},{"heading":"Связки уже знакомы","body":"Используйте готовые модели: 我叫…、我是…、你呢？、你在哪儿？. Частица 呢 помогает передать ход разговора обратно собеседнику, а 再见 аккуратно завершает беседу."}],"vocab":[{"hanzi":"认识","pinyin":"rènshi","ru":"знать; познакомиться"},{"hanzi":"很高兴","pinyin":"hěn gāoxìng","ru":"очень приятно"},{"hanzi":"同学","pinyin":"tóngxué","ru":"однокурсник; одноклассник"},{"hanzi":"现在","pinyin":"xiànzài","ru":"сейчас"},{"hanzi":"住","pinyin":"zhù","ru":"жить; проживать"},{"hanzi":"北京","pinyin":"Běijīng","ru":"Пекин"},{"hanzi":"再见","pinyin":"zàijiàn","ru":"до свидания"}],"grammar":[{"rule":"Связный обмен: вопрос → ответ → 你呢？","explain":"После собственного ответа возвращайте тот же вопрос собеседнику с 你呢？ Так диалог звучит естественно и не обрывается.","examples":[{"hanzi":"我是学生。你呢？","pinyin":"Wǒ shì xuéshēng. Nǐ ne?","ru":"Я студент. А ты?"},{"hanzi":"我在北京。你呢？","pinyin":"Wǒ zài Běijīng. Nǐ ne?","ru":"Я в Пекине. А ты?"}]},{"rule":"Завершение: 很高兴认识你 + 再见","explain":"Фраза 很高兴认识你 выражает радость от знакомства. После неё уместно попрощаться.","examples":[{"hanzi":"很高兴认识你。","pinyin":"Hěn gāoxìng rènshi nǐ.","ru":"Очень приятно познакомиться."},{"hanzi":"再见！","pinyin":"Zàijiàn!","ru":"До свидания!"}]}],"dialogue":{"title":"Встреча в школе","lines":[{"speaker":"Антон","hanzi":"你好！我叫安东。你叫什么名字？","pinyin":"Nǐ hǎo! Wǒ jiào Āndōng. Nǐ jiào shénme míngzi?","ru":"Здравствуйте! Меня зовут Антон. Как вас зовут?"},{"speaker":"李娜","hanzi":"我叫李娜。很高兴认识你。","pinyin":"Wǒ jiào Lǐ Nà. Hěn gāoxìng rènshi nǐ.","ru":"Меня зовут Ли На. Очень приятно познакомиться."},{"speaker":"Антон","hanzi":"我也是。你是哪国人？","pinyin":"Wǒ yě shì. Nǐ shì nǎ guó rén?","ru":"Мне тоже. Ты какой национальности?"},{"speaker":"李娜","hanzi":"我是中国人。你呢？","pinyin":"Wǒ shì Zhōngguó rén. Nǐ ne?","ru":"Я китаянка. А ты?"},{"speaker":"Антон","hanzi":"我是俄罗斯人。我是学生。","pinyin":"Wǒ shì Èluósī rén. Wǒ shì xuéshēng.","ru":"Я россиянин. Я студент."},{"speaker":"李娜","hanzi":"我也是学生。再见！","pinyin":"Wǒ yě shì xuéshēng. Zàijiàn!","ru":"Я тоже студентка. До свидания!"}]},"exercises":[{"type":"choice","q":"Что логично сказать после 你好 в начале знакомства?","options":["我叫…","没有。","明天见。"],"answer":0,"explain":"После приветствия естественно назвать себя с 我叫…"},{"type":"choice","q":"Как завершить разговор?","options":["你在哪儿？","再见！","这是什么？"],"answer":1,"explain":"再见 — готовая формула прощания."},{"type":"choice","q":"Какая фраза выражает радость от знакомства?","options":["很高兴认识你。","我没有书。","你在哪儿？"],"answer":0,"explain":"很高兴认识你 — «очень приятно познакомиться». "},{"type":"choice","q":"Что помогает вернуть вопрос собеседнику?","options":["你呢？","再见！","不客气。"],"answer":0,"explain":"你呢？ значит «а ты?» и поддерживает разговор."},{"type":"match","q":"Расположите части знакомства по функции.","pairs":[{"left":"你好！","right":"приветствие"},{"left":"我叫安东。","right":"имя"},{"left":"我是学生。","right":"занятие"},{"left":"再见！","right":"прощание"}],"explain":"У диалога есть понятная последовательность: начать, представиться, обменяться информацией, завершить."},{"type":"input","q":"Напишите пиньинь слова 认识.","answer":["rènshi","renshi"],"explain":"认识 читается rènshi: второй слог нейтральный."},{"type":"input","q":"Напишите иероглифами: «Очень приятно познакомиться».","answer":["很高兴认识你"],"explain":"很高兴 — «очень рад», 认识你 — «познакомиться с тобой». "}],"homework":"Составьте и запишите диалог из шести реплик с воображаемым китайским студентом: имя, страна, статус, вопрос с 你呢 и прощание."},{"id":20,"title":"Итог модуля 2: базовые фразы и приветствия","duration":30,"goal":"Ученик повторяет ключевые конструкции модуля и понимает короткий диалог-знакомство.","theory":[{"heading":"Что вы уже умеете","body":"Теперь вы можете поздороваться и попрощаться, назвать себя, спросить имя, национальность, профессию и местонахождение. Вы также умеете сказать, что у вас есть, что вам нравится и что вы хотите сделать."},{"heading":"Проверка порядка слов","body":"Перед выполнением упражнений вспомните четыре схемы: A 是 B; A 有 B; A 在 месте; A + глагол + объект. Вопросительная 吗 идёт в конец, а 什么、谁、哪儿 остаются на месте ответа."},{"heading":"Как повторять эффективно","body":"Читайте реплики вслух целыми фразами, а не отдельными иероглифами. Если забыли слово, сначала определите роль: приветствие, человек, действие, предмет или место."}],"vocab":[{"hanzi":"上午","pinyin":"shàngwǔ","ru":"утро; до полудня"},{"hanzi":"中午","pinyin":"zhōngwǔ","ru":"полдень"},{"hanzi":"下午","pinyin":"xiàwǔ","ru":"после обеда"},{"hanzi":"现在","pinyin":"xiànzài","ru":"сейчас"},{"hanzi":"昨天","pinyin":"zuótiān","ru":"вчера"},{"hanzi":"明天","pinyin":"míngtiān","ru":"завтра"},{"hanzi":"学习","pinyin":"xuéxí","ru":"учиться; изучать"},{"hanzi":"汉语","pinyin":"Hànyǔ","ru":"китайский язык"}],"grammar":[{"rule":"Итоговые модели: 是 / 有 / 在 / глагол","explain":"Выбирайте конструкцию по смыслу: кто это — 是; что имеется — 有; где находится — 在; что делает — обычный глагол.","examples":[{"hanzi":"我是学生。","pinyin":"Wǒ shì xuéshēng.","ru":"Я студент."},{"hanzi":"我有书。","pinyin":"Wǒ yǒu shū.","ru":"У меня есть книга."},{"hanzi":"我在学校学习汉语。","pinyin":"Wǒ zài xuéxiào xuéxí Hànyǔ.","ru":"Я изучаю китайский в школе."}]},{"rule":"Вопросы: 吗 / 什么 / 谁 / 哪儿","explain":"吗 создаёт вопрос «да/нет», а вопросительные слова называют недостающую информацию прямо на её месте.","examples":[{"hanzi":"你是老师吗？","pinyin":"Nǐ shì lǎoshī ma?","ru":"Ты преподаватель?"},{"hanzi":"你在哪儿？","pinyin":"Nǐ zài nǎr?","ru":"Где ты?"}]}],"dialogue":{"title":"Итоговый разговор","lines":[{"speaker":"Сергей","hanzi":"下午好！你叫什么名字？","pinyin":"Xiàwǔ hǎo! Nǐ jiào shénme míngzi?","ru":"Добрый день! Как тебя зовут?"},{"speaker":"王丽","hanzi":"我叫王丽。你呢？","pinyin":"Wǒ jiào Wáng Lì. Nǐ ne?","ru":"Меня зовут Ван Ли. А тебя?"},{"speaker":"Сергей","hanzi":"我叫谢尔盖。我是俄罗斯人。","pinyin":"Wǒ jiào Xiè'ěrgài. Wǒ shì Èluósī rén.","ru":"Меня зовут Сергей. Я россиянин."},{"speaker":"王丽","hanzi":"很高兴认识你。你在学校吗？","pinyin":"Hěn gāoxìng rènshi nǐ. Nǐ zài xuéxiào ma?","ru":"Очень приятно познакомиться. Ты в школе?"},{"speaker":"Сергей","hanzi":"是，我在学校学习汉语。","pinyin":"Shì, wǒ zài xuéxiào xuéxí Hànyǔ.","ru":"Да, я в школе изучаю китайский."},{"speaker":"王丽","hanzi":"太好了！明天见！","pinyin":"Tài hǎo le! Míngtiān jiàn!","ru":"Как здорово! До завтра!"}]},"exercises":[{"type":"choice","q":"Выберите верную фразу: «У меня нет воды».","options":["我不是水。","我没有水。","我不有水。"],"answer":1,"explain":"Наличие с 有 отрицается словом 没有."},{"type":"choice","q":"Как спросить «Где он?»","options":["他是谁？","他在哪儿？","他是什么？"],"answer":1,"explain":"Для места используется 在 + 哪儿。"},{"type":"choice","q":"Какой ответ подходит к вопросу 你喜欢茶吗？","options":["喜欢。","我是茶。","我在茶。"],"answer":0,"explain":"喜欢 — краткий утвердительный ответ на вопрос о предпочтении."},{"type":"match","q":"Соотнесите конструкцию и пример.","pairs":[{"left":"A 是 B","right":"她是医生。"},{"left":"A 有 B","right":"我有朋友。"},{"left":"A 在 地点","right":"他在家。"},{"left":"A + 动词 + 宾语","right":"我喝水。"}],"explain":"Каждая схема передаёт свой тип смысла: кто это, наличие, место или действие."},{"type":"input","q":"Напишите пиньинь фразы 明天见.","answer":["míngtiān jiàn","mingtian jian","mingtianjian"],"explain":"明天见 читается míngtiān jiàn: «до завтра». "},{"type":"input","q":"Напишите иероглифами: «Я в школе».","answer":["我在学校"],"explain":"Модель места: 我 + 在 + 学校。"},{"type":"input","q":"Напишите иероглифами: «Я студент».","answer":["我是学生"],"explain":"Используйте модель 我 + 是 + 学生。"}],"homework":"Повторите итоговый диалог вслух дважды: сначала по ролям, затем поменявшись ролями. После этого напишите о себе пять предложений: приветствие, имя, страна, занятие и место."}]},{"module":3,"hsk":"HSK1","title":"Числа, время и даты","summary":"После модуля ученик уверенно читает и строит числа, сообщает даты, время, возраст, цену и номер телефона. Он умеет спрашивать о времени и количестве, говорить о завершённых действиях и регулярных планах.","lessons":[{"id":1,"title":"Числа 0–10","duration":20,"goal":"Называть числа от нуля до десяти и узнавать их на слух.","theory":[{"heading":"Числа — отдельные слова","body":"В китайском одно число обычно соответствует одному иероглифу. Учите число сразу в трёх видах: иероглиф, звучание и значение. Тон важен: <b>yī</b> «один» и <b>wǔ</b> «пять» звучат по-разному."},{"heading":"Ноль в числе","body":"Ноль — <b>零 líng</b>. Пока просто запомните его как отдельное число; в составных числах он появится позже. Числа можно называть по порядку, как при счёте предметов."}],"vocab":[{"hanzi":"零","pinyin":"líng","ru":"ноль","note":""},{"hanzi":"一","pinyin":"yī","ru":"один","note":""},{"hanzi":"二","pinyin":"èr","ru":"два","note":""},{"hanzi":"三","pinyin":"sān","ru":"три","note":""},{"hanzi":"四","pinyin":"sì","ru":"четыре","note":""},{"hanzi":"五","pinyin":"wǔ","ru":"пять","note":""},{"hanzi":"六","pinyin":"liù","ru":"шесть","note":""},{"hanzi":"七","pinyin":"qī","ru":"семь","note":""},{"hanzi":"八","pinyin":"bā","ru":"восемь","note":""},{"hanzi":"九","pinyin":"jiǔ","ru":"девять","note":""},{"hanzi":"十","pinyin":"shí","ru":"десять","note":""}],"grammar":[{"rule":"Счёт от 0 до 10","explain":"Числа произносятся последовательно, без служебных слов. Не заменяйте 二 словом 两: 两 понадобится со счётными словами, а в простом счёте говорят 二.","examples":[{"hanzi":"一，二，三。","pinyin":"Yī, èr, sān.","ru":"Один, два, три."},{"hanzi":"八，九，十。","pinyin":"Bā, jiǔ, shí.","ru":"Восемь, девять, десять."}]}],"dialogue":{"title":"Считаем карандаши","lines":[{"speaker":"A","hanzi":"你会数吗？","pinyin":"Nǐ huì shǔ ma?","ru":"Ты умеешь считать?"},{"speaker":"B","hanzi":"会。一，二，三。","pinyin":"Huì. Yī, èr, sān.","ru":"Умею. Один, два, три."},{"speaker":"A","hanzi":"这是五吗？","pinyin":"Zhè shì wǔ ma?","ru":"Это пять?"},{"speaker":"B","hanzi":"不是，这是六。","pinyin":"Bú shì, zhè shì liù.","ru":"Нет, это шесть."}]},"exercises":[{"type":"choice","q":"Какое число означает 七？","options":["пять","семь","девять"],"answer":1,"explain":"七 читается qī и означает «семь»."},{"type":"input","q":"Напишите пиньинь числа 四.","answer":["sì","si"],"explain":"四 читается sì, четвёртый тон."},{"type":"match","q":"Соотнесите иероглиф и число.","pairs":[{"left":"一","right":"1"},{"left":"五","right":"5"},{"left":"十","right":"10"}],"explain":"Запоминайте форму иероглифа вместе со значением."},{"type":"choice","q":"Выберите 零.","options":["0","6","9"],"answer":0,"explain":"零 — это líng, ноль."},{"type":"input","q":"Напишите пиньинь числа 八.","answer":["bā","ba"],"explain":"八 читается bā, первый тон."},{"type":"choice","q":"Какое число читается wǔ?","options":["三","五","九"],"answer":1,"explain":"wǔ — это 五, число пять."},{"type":"input","q":"Напишите пиньинь числа 九.","answer":["jiǔ","jiu"],"explain":"九 читается jiǔ, третий тон."}],"homework":"Произнесите вслух ряд от 零 до 十 два раза, затем напишите иероглифы 一、三、五、七、九 по памяти."},{"id":2,"title":"Числа 11–99: логика 十 и 二十","duration":22,"goal":"Строить и понимать двузначные числа от 11 до 99.","theory":[{"heading":"После десяти","body":"Число 11 буквально значит «десять один»: <b>十一 shíyī</b>. Так же строятся 12–19: 十 + цифра. Между 十 и последней цифрой ничего добавлять не нужно."},{"heading":"Десятки","body":"Двадцать — <b>二十 èrshí</b>, то есть «два десятка». В 21 сначала называют число десятков, затем 十, затем единицу: 二十一 èrshíyī. Не говорите *二十一个*, когда просто называете число."}],"vocab":[{"hanzi":"十一","pinyin":"shíyī","ru":"одиннадцать","note":""},{"hanzi":"十二","pinyin":"shí’èr","ru":"двенадцать","note":""},{"hanzi":"十五","pinyin":"shíwǔ","ru":"пятнадцать","note":""},{"hanzi":"二十","pinyin":"èrshí","ru":"двадцать","note":""},{"hanzi":"二十一","pinyin":"èrshíyī","ru":"двадцать один","note":""},{"hanzi":"三十","pinyin":"sānshí","ru":"тридцать","note":""},{"hanzi":"四十","pinyin":"sìshí","ru":"сорок","note":""},{"hanzi":"五十","pinyin":"wǔshí","ru":"пятьдесят","note":""},{"hanzi":"九十九","pinyin":"jiǔshíjiǔ","ru":"девяносто девять","note":""}],"grammar":[{"rule":"Двузначное число: [десятки] + 十 + [единицы]","explain":"Для 11–19 число десятков 一 не произносится: 十一, а не *一十一*. Начиная с 20 произносите цифру перед 十. Не путайте порядок: 24 — 二十四, не *四十二*.","examples":[{"hanzi":"十八","pinyin":"Shíbā.","ru":"Восемнадцать."},{"hanzi":"四十二","pinyin":"Sìshí’èr.","ru":"Сорок два."},{"hanzi":"九十六","pinyin":"Jiǔshíliù.","ru":"Девяносто шесть."}]}],"dialogue":{"title":"Номер аудитории","lines":[{"speaker":"A","hanzi":"你在哪个教室？","pinyin":"Nǐ zài nǎge jiàoshì?","ru":"В какой ты аудитории?"},{"speaker":"B","hanzi":"我在二十一号教室。","pinyin":"Wǒ zài èrshíyī hào jiàoshì.","ru":"Я в аудитории номер двадцать один."},{"speaker":"A","hanzi":"是二十一吗？","pinyin":"Shì èrshíyī ma?","ru":"Двадцать один?"},{"speaker":"B","hanzi":"对，二十一。","pinyin":"Duì, èrshíyī.","ru":"Да, двадцать один."}]},"exercises":[{"type":"choice","q":"Как записать 34?","options":["三十四","四十三","三十六"],"answer":0,"explain":"Три десятка и четыре: 三十四."},{"type":"input","q":"Напишите пиньинь числа 二十.","answer":["èrshí","ershi"],"explain":"二十 читается èrshí."},{"type":"match","q":"Соотнесите число и чтение.","pairs":[{"left":"12","right":"十二"},{"left":"21","right":"二十一"},{"left":"50","right":"五十"}],"explain":"В числе сначала идут десятки, затем единицы."},{"type":"choice","q":"Что означает 九十九？","options":["девяносто девять","девятнадцать","девятьсот девяносто"],"answer":0,"explain":"九十九: девять десятков и девять."},{"type":"input","q":"Напишите иероглифами: 18.","answer":["十八"],"explain":"18 строится как 十八: «десять восемь»."},{"type":"choice","q":"Как записать 70?","options":["七十","十七","七"],"answer":0,"explain":"Семь десятков — 七十."},{"type":"input","q":"Напишите пиньинь числа 三十四.","answer":["sānshísì","sanshisi"],"explain":"三十四 читается sānshísì."}],"homework":"Запишите и прочитайте вслух 11, 16, 20, 27, 45 и 99."},{"id":3,"title":"Числа 100–1000: 百, 千 и 零","duration":24,"goal":"Называть круглые сотни и тысячи, а также числа с нулём внутри.","theory":[{"heading":"Сотня и тысяча","body":"Сто — <b>一百 yì bǎi</b>, двести — 二百 èr bǎi, тысяча — 一千 yì qiān. В обычной речи перед 百 и 千 можно услышать 两, но для точного чтения чисел на этом уроке используйте 二."},{"heading":"Зачем нужен 零","body":"Если в записи числа пропущен разряд внутри числа, произносите 零 один раз. Например, 105 — 一百零五. В конце числа 零 не читают: 120 — 一百二十, не *一百二十零*."}],"vocab":[{"hanzi":"百","pinyin":"bǎi","ru":"сто","note":""},{"hanzi":"一百","pinyin":"yì bǎi","ru":"сто","note":""},{"hanzi":"二百","pinyin":"èr bǎi","ru":"двести","note":""},{"hanzi":"一百零五","pinyin":"yì bǎi líng wǔ","ru":"сто пять","note":""},{"hanzi":"一百二十","pinyin":"yì bǎi èrshí","ru":"сто двадцать","note":""},{"hanzi":"三百","pinyin":"sān bǎi","ru":"триста","note":""},{"hanzi":"千","pinyin":"qiān","ru":"тысяча","note":""},{"hanzi":"一千","pinyin":"yì qiān","ru":"тысяча","note":""}],"grammar":[{"rule":"Число: [тысячи] + [сотни] + [десятки] + [единицы]","explain":"零 обозначает пропуск разряда только внутри числа. Не ставьте 零 между соседними заполненными разрядами: 123 — 一百二十三, без 零. Перед 百 и 千 тон 一 меняется в речи на yì.","examples":[{"hanzi":"二百零八","pinyin":"Èr bǎi líng bā.","ru":"Двести восемь."},{"hanzi":"一千零三","pinyin":"Yì qiān líng sān.","ru":"Тысяча три."},{"hanzi":"五百六十","pinyin":"Wǔ bǎi liùshí.","ru":"Пятьсот шестьдесят."}]}],"dialogue":{"title":"Большое число","lines":[{"speaker":"A","hanzi":"这个学校有多少学生？","pinyin":"Zhège xuéxiào yǒu duōshao xuéshēng?","ru":"Сколько учеников в этой школе?"},{"speaker":"B","hanzi":"有一千个学生。","pinyin":"Yǒu yì qiān ge xuéshēng.","ru":"Есть тысяча учеников."},{"speaker":"A","hanzi":"一千？很多！","pinyin":"Yì qiān? Hěn duō!","ru":"Тысяча? Очень много!"},{"speaker":"B","hanzi":"对，有很多人。","pinyin":"Duì, yǒu hěn duō rén.","ru":"Да, людей много."}]},"exercises":[{"type":"choice","q":"Как правильно прочитать 105?","options":["一百五","一百零五","一百零五十"],"answer":1,"explain":"В десятках пропуск, поэтому нужен 零: 一百零五."},{"type":"input","q":"Напишите пиньинь слова 千.","answer":["qiān","qian"],"explain":"千 читается qiān, первый тон."},{"type":"match","q":"Соотнесите запись и число.","pairs":[{"left":"二百","right":"200"},{"left":"一千","right":"1000"},{"left":"三百","right":"300"}],"explain":"百 — сотня, 千 — тысяча."},{"type":"choice","q":"Где 零 НЕ нужно?","options":["108","120","1003"],"answer":1,"explain":"120 — 一百二十: ноль стоит в конце и не произносится."},{"type":"input","q":"Запишите иероглифами: 208.","answer":["二百零八"],"explain":"В 208 нет десятков, поэтому вставляем 零."},{"type":"choice","q":"Как записать 1003?","options":["一千三","一千零三","一百零三"],"answer":1,"explain":"В сотнях и десятках пропуск, но 零 говорят один раз."},{"type":"input","q":"Напишите пиньинь числа 一百零五.","answer":["yì bǎi líng wǔ","yi bai ling wu","yibailingwu"],"explain":"一百零五 читается yì bǎi líng wǔ."}],"homework":"Напишите по-китайски 100, 305, 420, 1000 и 1006. Прочитайте каждую запись вслух."},{"id":4,"title":"Счётное слово 个 и вопрос 几","duration":22,"goal":"Считать людей и предметы с 个 и спрашивать «сколько?» с 几.","theory":[{"heading":"Почему нужен 个","body":"Между числом и существительным в китайском обычно стоит счётное слово. <b>个 ge</b> — самое универсальное и частое: 一个人 «один человек», 三个学生 «три студента». В речи его тон часто нейтральный."},{"heading":"Вопрос 几","body":"<b>几 jǐ</b> спрашивает небольшое, обычно известное количество: 几个人？ «Сколько человек?». Схема вопроса такая же, как ответа: 几 + счётное слово + существительное. Не ставьте 是 перед количеством."}],"vocab":[{"hanzi":"个","pinyin":"ge","ru":"универсальное счётное слово","note":""},{"hanzi":"几","pinyin":"jǐ","ru":"сколько (небольшое число)","note":""},{"hanzi":"人","pinyin":"rén","ru":"человек","note":""},{"hanzi":"学生","pinyin":"xuéshēng","ru":"студент","note":""},{"hanzi":"朋友","pinyin":"péngyou","ru":"друг","note":""},{"hanzi":"苹果","pinyin":"píngguǒ","ru":"яблоко","note":""},{"hanzi":"这","pinyin":"zhè","ru":"этот","note":""},{"hanzi":"那","pinyin":"nà","ru":"тот","note":""}],"grammar":[{"rule":"Число + 个 + существительное","explain":"个 ставится после цифры, а не после существительного. Для одного предмета говорят 一个; перед 个 一 произносится yí. Не опускайте 个 в сочетании *三学生* — правильно 三个学生.","examples":[{"hanzi":"一个人","pinyin":"Yí ge rén.","ru":"Один человек."},{"hanzi":"两个苹果","pinyin":"Liǎng ge píngguǒ.","ru":"Два яблока."},{"hanzi":"你有几个朋友？","pinyin":"Nǐ yǒu jǐ ge péngyou?","ru":"Сколько у тебя друзей?"}]},{"rule":"几 + 个 + существительное？","explain":"几 занимает то же место, что и число. Отвечая, замените 几 конкретным числом: 有三个朋友. Ошибка *几朋友* возникает из-за пропуска 个.","examples":[{"hanzi":"这个班有几个人？","pinyin":"Zhège bān yǒu jǐ ge rén?","ru":"Сколько человек в этом классе?"},{"hanzi":"有十个人。","pinyin":"Yǒu shí ge rén.","ru":"Есть десять человек."}]}],"dialogue":{"title":"В классе","lines":[{"speaker":"A","hanzi":"这个班有几个人？","pinyin":"Zhège bān yǒu jǐ ge rén?","ru":"Сколько человек в этом классе?"},{"speaker":"B","hanzi":"有十个人。","pinyin":"Yǒu shí ge rén.","ru":"Есть десять человек."},{"speaker":"A","hanzi":"有几个老师？","pinyin":"Yǒu jǐ ge lǎoshī?","ru":"Сколько учителей?"},{"speaker":"B","hanzi":"有一个老师。","pinyin":"Yǒu yí ge lǎoshī.","ru":"Есть один учитель."}]},"exercises":[{"type":"choice","q":"Выберите «три друга».","options":["三个朋友","三朋友","朋友三个"],"answer":0,"explain":"Сначала число, затем 个, затем существительное."},{"type":"input","q":"Напишите пиньинь слова 几.","answer":["jǐ","ji"],"explain":"几 читается jǐ, третий тон."},{"type":"match","q":"Соотнесите сочетания.","pairs":[{"left":"一个人","right":"один человек"},{"left":"两个苹果","right":"два яблока"},{"left":"几个学生","right":"сколько студентов"}],"explain":"个 соединяет число или 几 с существительным."},{"type":"choice","q":"Как спросить «Сколько людей?»","options":["几个人？","几个？人","人几？"],"answer":0,"explain":"几 стоит перед 个 и словом 人."},{"type":"input","q":"Напишите иероглифами: три студента.","answer":["三个学生"],"explain":"Для студентов здесь используем 个: 三个学生."},{"type":"choice","q":"Как спросить «Сколько яблок?»","options":["几苹果？","几个苹果？","苹果几个？"],"answer":1,"explain":"几 стоит перед счётным словом 个."},{"type":"input","q":"Напишите пиньинь слова 个.","answer":["ge"],"explain":"个 произносится нейтральным тоном: ge."}],"homework":"Составьте три фразы по схеме «число + 个 + существительное» и один вопрос с 几."},{"id":5,"title":"Счётные слова 本, 口, 岁 и другие","duration":25,"goal":"Выбирать несколько частотных счётных слов по смыслу.","theory":[{"heading":"У существительных есть «классы»","body":"个 подходит не ко всему. Для книг используйте <b>本 běn</b>, для членов семьи — <b>口 kǒu</b>, а возраст измеряется словом <b>岁 suì</b>. Счётное слово стоит на одном и том же месте: число + счётное слово + существительное."},{"heading":"Нужно запоминать вместе","body":"Учите готовые сочетания: 一本书, 三口人, 二十岁. Нельзя выбирать счётное слово по переводу русского слова «штука»: оно зависит от типа китайского существительного. Для животных часто встречается 只 zhī."}],"vocab":[{"hanzi":"本","pinyin":"běn","ru":"счётное слово для книг","note":""},{"hanzi":"书","pinyin":"shū","ru":"книга","note":""},{"hanzi":"口","pinyin":"kǒu","ru":"счётное слово для членов семьи","note":""},{"hanzi":"家","pinyin":"jiā","ru":"семья; дом","note":""},{"hanzi":"岁","pinyin":"suì","ru":"лет (о возрасте)","note":""},{"hanzi":"只","pinyin":"zhī","ru":"счётное слово для животных и одной штуки из пары","note":""},{"hanzi":"猫","pinyin":"māo","ru":"кошка","note":""},{"hanzi":"杯","pinyin":"bēi","ru":"счётное слово для стаканов, чашек","note":""}],"grammar":[{"rule":"Число + подходящее счётное слово + существительное","explain":"Выбирайте слово по существительному: 本 для 书, 口 для семьи, 只 для 猫. 个 не ошибка в самой простой разговорной ситуации с людьми, но с книгами и возрастом нужны специальные слова. Не говорите *二个岁*.","examples":[{"hanzi":"一本书","pinyin":"Yì běn shū.","ru":"Одна книга."},{"hanzi":"三口人","pinyin":"Sān kǒu rén.","ru":"Семья из трёх человек."},{"hanzi":"两只猫","pinyin":"Liǎng zhī māo.","ru":"Две кошки."}]}],"dialogue":{"title":"О семье","lines":[{"speaker":"A","hanzi":"你家有几口人？","pinyin":"Nǐ jiā yǒu jǐ kǒu rén?","ru":"Сколько человек в твоей семье?"},{"speaker":"B","hanzi":"我家有三口人。","pinyin":"Wǒ jiā yǒu sān kǒu rén.","ru":"В моей семье три человека."},{"speaker":"A","hanzi":"你有猫吗？","pinyin":"Nǐ yǒu māo ma?","ru":"У тебя есть кошка?"},{"speaker":"B","hanzi":"有一只猫。","pinyin":"Yǒu yì zhī māo.","ru":"Есть одна кошка."}]},"exercises":[{"type":"choice","q":"Как сказать «две книги»?","options":["两本书","两个书","二口书"],"answer":0,"explain":"Для книг используется 本; с обычным количеством естественно 两本书."},{"type":"input","q":"Напишите пиньинь слова 岁.","answer":["suì","sui"],"explain":"岁 читается suì, четвёртый тон."},{"type":"match","q":"Соотнесите.","pairs":[{"left":"本","right":"книга"},{"left":"口","right":"член семьи"},{"left":"只","right":"кошка"}],"explain":"Счётное слово выбирается вместе с существительным."},{"type":"choice","q":"Что правильно?","options":["三口人","三个人家","三岁人"],"answer":0,"explain":"Когда считаем членов семьи, говорят 三口人."},{"type":"input","q":"Запишите иероглифами: одна кошка.","answer":["一只猫"],"explain":"Для кошки нужно счётное слово 只."},{"type":"choice","q":"Как сказать «двадцать лет»?","options":["二十个岁","二十岁","二十口岁"],"answer":1,"explain":"Для возраста используют 岁 без 个."},{"type":"input","q":"Напишите пиньинь слова 本.","answer":["běn","ben"],"explain":"本 читается běn, третий тон."}],"homework":"Сделайте мини-словарик: по одному сочетанию с 本、口、只、杯 и прочитайте их вслух."},{"id":6,"title":"Возраст: 你几岁？我二十岁。","duration":20,"goal":"Спрашивать возраст и отвечать целой фразой.","theory":[{"heading":"Вопрос об возрасте","body":"К близкому по возрасту человеку можно обратиться: <b>你几岁？Nǐ jǐ suì?</b> Это буквально «тебе сколько лет?». Для взрослого в вежливой ситуации лучше спросить 您多大？, но в HSK1-диалогах вы встретите обе формулы."},{"heading":"Ответ без 是","body":"Возраст сообщают по схеме подлежащее + число + 岁: 我二十岁. Слово 是 перед числом не нужно. В китайском возраст всегда указывается после человека, а не как русское «мне двадцать»."}],"vocab":[{"hanzi":"多大","pinyin":"duō dà","ru":"сколько лет; какого размера","note":"о возрасте, вежливо"},{"hanzi":"您","pinyin":"nín","ru":"Вы (вежливо)","note":""},{"hanzi":"今年","pinyin":"jīnnián","ru":"в этом году","note":""},{"hanzi":"大","pinyin":"dà","ru":"большой; старший","note":""},{"hanzi":"小","pinyin":"xiǎo","ru":"маленький; младший","note":""},{"hanzi":"二十岁","pinyin":"èrshí suì","ru":"двадцать лет","note":""},{"hanzi":"十八岁","pinyin":"shíbā suì","ru":"восемнадцать лет","note":""},{"hanzi":"孩子","pinyin":"háizi","ru":"ребёнок","note":""}],"grammar":[{"rule":"你几岁？ / 我 + число + 岁。","explain":"几 заменяет число в вопросе, а 岁 остаётся после него. В ответе не ставьте 个: *二十个岁* неверно. Не используйте 是: правильно 我二十岁.","examples":[{"hanzi":"你几岁？","pinyin":"Nǐ jǐ suì?","ru":"Сколько тебе лет?"},{"hanzi":"我十八岁。","pinyin":"Wǒ shíbā suì.","ru":"Мне восемнадцать лет."},{"hanzi":"她今年二十岁。","pinyin":"Tā jīnnián èrshí suì.","ru":"В этом году ей двадцать лет."}]},{"rule":"您多大？ — вежливый вопрос взрослому","explain":"您 — уважительная форма «вы». 多大 буквально означает «насколько большой», но в вопросе к взрослому значит «сколько вам лет». Не говорите 您几岁 незнакомому взрослому: это может прозвучать слишком по-детски.","examples":[{"hanzi":"您多大？","pinyin":"Nín duō dà?","ru":"Сколько Вам лет?"},{"hanzi":"我二十五岁。","pinyin":"Wǒ èrshíwǔ suì.","ru":"Мне двадцать пять лет."}]}],"dialogue":{"title":"Новые знакомые","lines":[{"speaker":"A","hanzi":"你今年几岁？","pinyin":"Nǐ jīnnián jǐ suì?","ru":"Сколько тебе лет в этом году?"},{"speaker":"B","hanzi":"我十八岁。你呢？","pinyin":"Wǒ shíbā suì. Nǐ ne?","ru":"Мне восемнадцать. А тебе?"},{"speaker":"A","hanzi":"我二十岁。","pinyin":"Wǒ èrshí suì.","ru":"Мне двадцать лет."},{"speaker":"B","hanzi":"我们差不多大。","pinyin":"Wǒmen chàbuduō dà.","ru":"Мы примерно одного возраста."}]},"exercises":[{"type":"choice","q":"Как ответить «Мне 20 лет»?","options":["我是二十岁。","我二十岁。","我有二十岁。"],"answer":1,"explain":"Возраст называют без 是 и 有: 我二十岁。"},{"type":"input","q":"Напишите пиньинь вопроса 你几岁？","answer":["nǐ jǐ suì","ni ji sui","nijisui"],"explain":"Вопрос читается nǐ jǐ suì."},{"type":"match","q":"Соотнесите фразу и перевод.","pairs":[{"left":"你几岁？","right":"Сколько тебе лет?"},{"left":"我十八岁。","right":"Мне 18 лет."},{"left":"您多大？","right":"Сколько Вам лет?"}],"explain":"Выбирайте 您多大？ для вежливого обращения."},{"type":"choice","q":"Что ставится после числа в сообщении о возрасте?","options":["个","岁","口"],"answer":1,"explain":"岁 — счётное слово для возраста."},{"type":"input","q":"Запишите иероглифами: Мне 18 лет.","answer":["我十八岁"],"explain":"Схема: 我 + 十八 + 岁."},{"type":"choice","q":"Как вежливо спросить взрослого о возрасте?","options":["您多大？","您几岁？","你多少岁？"],"answer":0,"explain":"К взрослому естественно обратиться: 您多大？"},{"type":"input","q":"Напишите пиньинь фразы 二十岁.","answer":["èrshí suì","ershi sui","ershisui"],"explain":"二十岁 читается èrshí suì."}],"homework":"Составьте вслух два вопроса об возрасте: другу и незнакомому взрослому; затем запишите два ответа с разными числами."},{"id":7,"title":"Дни недели: 星期一 … 星期天","duration":22,"goal":"Называть дни недели и спрашивать, какой сегодня день.","theory":[{"heading":"Простая нумерация","body":"Неделя — <b>星期 xīngqī</b>. С понедельника по субботу дни строятся по номеру: 星期一, 星期二 и так далее. Воскресенье чаще говорят 星期天 или 星期日; оба варианта правильные."},{"heading":"Как спросить","body":"Вопрос «какой сегодня день недели?» — 今天星期几？ В нём 几 заменяет номер дня. Для ответа скажите 今天星期三, без 是 между 今天 и 星期三."}],"vocab":[{"hanzi":"星期","pinyin":"xīngqī","ru":"неделя; день недели","note":""},{"hanzi":"星期一","pinyin":"xīngqīyī","ru":"понедельник","note":""},{"hanzi":"星期二","pinyin":"xīngqī’èr","ru":"вторник","note":""},{"hanzi":"星期三","pinyin":"xīngqīsān","ru":"среда","note":""},{"hanzi":"星期四","pinyin":"xīngqīsì","ru":"четверг","note":""},{"hanzi":"星期五","pinyin":"xīngqīwǔ","ru":"пятница","note":""},{"hanzi":"星期六","pinyin":"xīngqīliù","ru":"суббота","note":""},{"hanzi":"星期天","pinyin":"xīngqītiān","ru":"воскресенье","note":""}],"grammar":[{"rule":"星期 + номер дня","explain":"После 星期 произносят цифру от 一 до 六. Воскресенье не называют *星期七*: используйте 星期天 или 星期日. В пиньине можно писать слитно xīngqīyī, как в словаре.","examples":[{"hanzi":"星期一","pinyin":"Xīngqīyī.","ru":"Понедельник."},{"hanzi":"星期五","pinyin":"Xīngqīwǔ.","ru":"Пятница."},{"hanzi":"星期天","pinyin":"Xīngqītiān.","ru":"Воскресенье."}]},{"rule":"今天星期几？","explain":"Вопросительное 几 стоит там, где в ответе будет номер дня. Не переставляйте 今天 в конец: естественная фраза начинается со слова времени. Ответ: 今天星期二.","examples":[{"hanzi":"今天星期几？","pinyin":"Jīntiān xīngqī jǐ?","ru":"Какой сегодня день недели?"},{"hanzi":"今天星期三。","pinyin":"Jīntiān xīngqīsān.","ru":"Сегодня среда."}]}],"dialogue":{"title":"План на неделю","lines":[{"speaker":"A","hanzi":"今天星期几？","pinyin":"Jīntiān xīngqī jǐ?","ru":"Какой сегодня день недели?"},{"speaker":"B","hanzi":"今天星期五。","pinyin":"Jīntiān xīngqīwǔ.","ru":"Сегодня пятница."},{"speaker":"A","hanzi":"明天星期六吗？","pinyin":"Míngtiān xīngqīliù ma?","ru":"Завтра суббота?"},{"speaker":"B","hanzi":"对，明天星期六。","pinyin":"Duì, míngtiān xīngqīliù.","ru":"Да, завтра суббота."}]},"exercises":[{"type":"choice","q":"Какой день 星期二？","options":["вторник","четверг","суббота"],"answer":0,"explain":"二 — «два», поэтому 星期二 — второй день недели, вторник."},{"type":"input","q":"Напишите пиньинь слова 星期天.","answer":["xīngqītiān","xingqitian"],"explain":"星期天 читается xīngqītiān."},{"type":"match","q":"Соотнесите дни.","pairs":[{"left":"星期一","right":"понедельник"},{"left":"星期三","right":"среда"},{"left":"星期六","right":"суббота"}],"explain":"После 星期 идёт номер дня."},{"type":"choice","q":"Выберите естественный ответ на «今天星期几？»","options":["星期七。","今天星期四。","今天是几。"],"answer":1,"explain":"В ответе называем конкретный день: 今天星期四。"},{"type":"input","q":"Запишите иероглифами: пятница.","answer":["星期五"],"explain":"Пятница — 星期五."},{"type":"choice","q":"Как сказать «воскресенье»?","options":["星期六","星期天","星期七"],"answer":1,"explain":"Воскресенье — 星期天 или 星期日, но не 星期七."},{"type":"input","q":"Напишите пиньинь слова 星期四.","answer":["xīngqīsì","xingqisi"],"explain":"星期四 читается xīngqīsì."}],"homework":"Назовите вслух все дни недели по порядку. Затем напишите, какой день был вчера и будет завтра, выбрав любой день за «сегодня»."},{"id":8,"title":"Месяцы и числа месяца: 月, 号","duration":23,"goal":"Называть месяц и день месяца в простой дате.","theory":[{"heading":"Месяц — это номер","body":"Месяцы образуются очень прозрачно: цифра + <b>月 yuè</b>. Январь — 一月, август — 八月, декабрь — 十二月. Не нужно учить отдельные названия месяцев."},{"heading":"Число месяца","body":"Для дня месяца в разговоре используйте цифру + <b>号 hào</b>: 八月十八号 — «18 августа». В документах и календарях часто увидите 日 rì, но сначала уверенно освойте 号."}],"vocab":[{"hanzi":"月","pinyin":"yuè","ru":"месяц","note":""},{"hanzi":"号","pinyin":"hào","ru":"номер; число месяца","note":""},{"hanzi":"一月","pinyin":"yī yuè","ru":"январь","note":""},{"hanzi":"三月","pinyin":"sān yuè","ru":"март","note":""},{"hanzi":"八月","pinyin":"bā yuè","ru":"август","note":""},{"hanzi":"十二月","pinyin":"shí’èr yuè","ru":"декабрь","note":""},{"hanzi":"生日","pinyin":"shēngrì","ru":"день рождения","note":""},{"hanzi":"今天","pinyin":"jīntiān","ru":"сегодня","note":""}],"grammar":[{"rule":"Номер месяца + 月","explain":"Месяц называют от меньшей единицы к большей: сначала номер, затем 月. Не добавляйте 个: *八个月* означает «восемь месяцев (длительность)», а не «август». Для названия августа — 八月.","examples":[{"hanzi":"一月","pinyin":"Yī yuè.","ru":"Январь."},{"hanzi":"十月","pinyin":"Shí yuè.","ru":"Октябрь."},{"hanzi":"十二月","pinyin":"Shí’èr yuè.","ru":"Декабрь."}]},{"rule":"Месяц + 月 + число + 号","explain":"Дата внутри года идёт от месяца к дню. 号 ставится только после числа дня: 八月十八号. Ошибка *十八号月* нарушает порядок.","examples":[{"hanzi":"五月一号","pinyin":"Wǔ yuè yī hào.","ru":"Первое мая."},{"hanzi":"八月十八号","pinyin":"Bā yuè shíbā hào.","ru":"Восемнадцатое августа."}]}],"dialogue":{"title":"День рождения","lines":[{"speaker":"A","hanzi":"你的生日是几月几号？","pinyin":"Nǐ de shēngrì shì jǐ yuè jǐ hào?","ru":"Когда твой день рождения?"},{"speaker":"B","hanzi":"我的生日是八月十八号。","pinyin":"Wǒ de shēngrì shì bā yuè shíbā hào.","ru":"Мой день рождения — 18 августа."},{"speaker":"A","hanzi":"今天是八月十八号吗？","pinyin":"Jīntiān shì bā yuè shíbā hào ma?","ru":"Сегодня 18 августа?"},{"speaker":"B","hanzi":"不是，今天是八月十七号。","pinyin":"Bú shì, jīntiān shì bā yuè shíqī hào.","ru":"Нет, сегодня 17 августа."}]},"exercises":[{"type":"choice","q":"Как сказать «август»?","options":["八号","八月","月八"],"answer":1,"explain":"Номер месяца ставится перед 月: 八月."},{"type":"input","q":"Напишите пиньинь слова 号.","answer":["hào","hao"],"explain":"号 читается hào, четвёртый тон."},{"type":"match","q":"Соотнесите даты.","pairs":[{"left":"一月一号","right":"1 января"},{"left":"三月八号","right":"8 марта"},{"left":"十二月二十号","right":"20 декабря"}],"explain":"Сначала месяц с 月, потом число с 号."},{"type":"choice","q":"Что добавляют после числа дня в разговорной дате?","options":["月","号","年"],"answer":1,"explain":"号 обозначает число месяца."},{"type":"input","q":"Запишите иероглифами: 5 мая.","answer":["五月五号"],"explain":"Май — 五月, пятое число — 五号."},{"type":"choice","q":"Как записать 18 августа?","options":["十八月八号","八月十八号","八号十八月"],"answer":1,"explain":"Сначала месяц с 月, затем число с 号."},{"type":"input","q":"Напишите пиньинь слова 八月.","answer":["bā yuè","ba yue","bayue"],"explain":"八月 читается bā yuè."}],"homework":"Запишите свою вымышленную дату рождения в формате «месяц + 月 + число + 号» и прочитайте её вслух."},{"id":9,"title":"Годы и полная дата: 2026年8月18日","duration":25,"goal":"Читать и записывать год и полную дату по-китайски.","theory":[{"heading":"Год читаем по цифрам","body":"В годе каждую цифру называют отдельно: 2026 год — <b>二零二六年 èr líng èr liù nián</b>, а не «две тысячи двадцать шесть». После четырёх цифр ставьте 年 nián."},{"heading":"Порядок частей даты","body":"Китайская дата идёт от большого к малому: год, месяц, день. Нейтральная запись: 2026年8月18日. В разговоре в конце даты возможен 号, но с полным форматом полезно узнавать 日."}],"vocab":[{"hanzi":"年","pinyin":"nián","ru":"год","note":""},{"hanzi":"日","pinyin":"rì","ru":"день; дата в календаре","note":""},{"hanzi":"二零二六年","pinyin":"èr líng èr liù nián","ru":"2026 год","note":""},{"hanzi":"二零二四年","pinyin":"èr líng èr sì nián","ru":"2024 год","note":""},{"hanzi":"今年","pinyin":"jīnnián","ru":"этот год","note":""},{"hanzi":"明年","pinyin":"míngnián","ru":"следующий год","note":""},{"hanzi":"去年","pinyin":"qùnián","ru":"прошлый год","note":""},{"hanzi":"日期","pinyin":"rìqī","ru":"дата","note":""}],"grammar":[{"rule":"Год: цифра + цифра + цифра + цифра + 年","explain":"В годе не объединяйте цифры в десятки и сотни. 2026 — 二零二六, потому что это чтение записи по одной цифре. Ошибка *二千二十六年* относится к количеству, а не к дате.","examples":[{"hanzi":"2026年","pinyin":"Èr líng èr liù nián.","ru":"2026 год."},{"hanzi":"2018年","pinyin":"Èr líng yī bā nián.","ru":"2018 год."}]},{"rule":"Полная дата: 年 + 月 + 日","explain":"Сначала всегда год, потом месяц, затем число дня. 日 — письменный и нейтральный вариант для даты; 号 чаще звучит в разговоре. Не ставьте запятые между частями даты.","examples":[{"hanzi":"2026年8月18日","pinyin":"Èr líng èr liù nián bā yuè shíbā rì.","ru":"18 августа 2026 года."},{"hanzi":"2024年3月8日","pinyin":"Èr líng èr sì nián sān yuè bā rì.","ru":"8 марта 2024 года."}]}],"dialogue":{"title":"Смотрим календарь","lines":[{"speaker":"A","hanzi":"今天的日期是什么？","pinyin":"Jīntiān de rìqī shì shénme?","ru":"Какая сегодня дата?"},{"speaker":"B","hanzi":"今天是二零二六年八月十八日。","pinyin":"Jīntiān shì èr líng èr liù nián bā yuè shíbā rì.","ru":"Сегодня 18 августа 2026 года."},{"speaker":"A","hanzi":"明年是哪一年？","pinyin":"Míngnián shì nǎ yì nián?","ru":"Какой год будет в следующем году?"},{"speaker":"B","hanzi":"明年是二零二七年。","pinyin":"Míngnián shì èr líng èr qī nián.","ru":"Следующий год — 2027."}]},"exercises":[{"type":"choice","q":"Как читается 2026年?","options":["二千二十六年","二零二六年","二百零二十六年"],"answer":1,"explain":"Годы читают цифра за цифрой: 二零二六年."},{"type":"input","q":"Напишите пиньинь слова 年.","answer":["nián","nian"],"explain":"年 читается nián."},{"type":"match","q":"Соотнесите элемент и значение.","pairs":[{"left":"年","right":"год"},{"left":"月","right":"месяц"},{"left":"日","right":"день даты"}],"explain":"Дата строится от года к месяцу и дню."},{"type":"choice","q":"Какой порядок верен?","options":["日—月—年","月—日—年","年—月—日"],"answer":2,"explain":"В китайской записи идут год, месяц, день."},{"type":"input","q":"Запишите иероглифами: 2024 год.","answer":["二零二四年"],"explain":"Каждая цифра года произносится отдельно."},{"type":"choice","q":"Как читается 2018年?","options":["二千十八年","二零一八年","二百零十八年"],"answer":1,"explain":"В годе каждую цифру произносят отдельно."},{"type":"input","q":"Напишите пиньинь слова 日.","answer":["rì","ri"],"explain":"日 читается rì, четвёртый тон."}],"homework":"Запишите три даты: сегодняшнюю, дату своего вымышленного рождения и дату в следующем году. В каждой дате используйте 年、月、日."},{"id":10,"title":"Сегодня, вчера, завтра: 今天, 昨天, 明天","duration":20,"goal":"Говорить о близких днях и связывать их с простыми событиями.","theory":[{"heading":"Три опорных дня","body":"Сегодня — <b>今天 jīntiān</b>, вчера — 昨天 zuótiān, завтра — 明天 míngtiān. Это готовые слова: не пытайтесь строить их из цифр. Обычно они стоят в начале предложения и сразу задают время."},{"heading":"Когда без даты достаточно","body":"Если из разговора понятно, о каком дне идёт речь, не нужно повторять полную дату. 今天我学习中文 — естественно. Для планов на завтра удобно употреблять 想 «хотеть»."}],"vocab":[{"hanzi":"昨天","pinyin":"zuótiān","ru":"вчера","note":""},{"hanzi":"明天","pinyin":"míngtiān","ru":"завтра","note":""},{"hanzi":"前天","pinyin":"qiántiān","ru":"позавчера","note":""},{"hanzi":"后天","pinyin":"hòutiān","ru":"послезавтра","note":""},{"hanzi":"学习","pinyin":"xuéxí","ru":"учиться; изучать","note":""},{"hanzi":"工作","pinyin":"gōngzuò","ru":"работать; работа","note":""},{"hanzi":"休息","pinyin":"xiūxi","ru":"отдыхать","note":""},{"hanzi":"想","pinyin":"xiǎng","ru":"хотеть; думать","note":""}],"grammar":[{"rule":"Слово времени + подлежащее + действие","explain":"Сегодня, вчера и завтра ставьте перед тем, кто действует. Не добавляйте 在 только из-за русского «сегодня»: 今天我学习中文, не *我在今天学习中文*. После временного слова можно сразу поставить подлежащее.","examples":[{"hanzi":"今天我学习中文。","pinyin":"Jīntiān wǒ xuéxí Zhōngwén.","ru":"Сегодня я учу китайский."},{"hanzi":"明天她工作。","pinyin":"Míngtiān tā gōngzuò.","ru":"Завтра она работает."},{"hanzi":"昨天我们休息。","pinyin":"Zuótiān wǒmen xiūxi.","ru":"Вчера мы отдыхали."}]}],"dialogue":{"title":"Планы на выходные","lines":[{"speaker":"A","hanzi":"你今天学习吗？","pinyin":"Nǐ jīntiān xuéxí ma?","ru":"Ты сегодня учишься?"},{"speaker":"B","hanzi":"学习。明天我想休息。","pinyin":"Xuéxí. Míngtiān wǒ xiǎng xiūxi.","ru":"Учусь. Завтра хочу отдохнуть."},{"speaker":"A","hanzi":"昨天你工作吗？","pinyin":"Zuótiān nǐ gōngzuò ma?","ru":"Ты вчера работал?"},{"speaker":"B","hanzi":"不工作，昨天我在家。","pinyin":"Bù gōngzuò, zuótiān wǒ zài jiā.","ru":"Нет, вчера я был дома."}]},"exercises":[{"type":"choice","q":"Что означает 后天？","options":["позавчера","послезавтра","завтра"],"answer":1,"explain":"后天 — день после завтра, то есть послезавтра."},{"type":"input","q":"Напишите пиньинь слова 昨天.","answer":["zuótiān","zuotian"],"explain":"昨天 читается zuótiān."},{"type":"match","q":"Соотнесите.","pairs":[{"left":"今天","right":"сегодня"},{"left":"前天","right":"позавчера"},{"left":"明天","right":"завтра"}],"explain":"Эти слова сразу указывают день относительно сегодня."},{"type":"choice","q":"Выберите естественный порядок слов.","options":["我明天学习中文。","明天我学习中文。","学习中文明天我。"],"answer":1,"explain":"Слово времени естественно вынести в начало: 明天我学习中文。"},{"type":"input","q":"Напишите иероглифами: послезавтра.","answer":["后天"],"explain":"后天 — день после завтра."},{"type":"choice","q":"Какая фраза означает «Вчера я отдыхал»?","options":["昨天我休息。","明天我休息。","今天我休息。"],"answer":0,"explain":"昨天 означает «вчера». "},{"type":"input","q":"Напишите пиньинь слова 明天.","answer":["míngtiān","mingtian"],"explain":"明天 читается míngtiān."}],"homework":"Запишите по одной правдивой или вымышленной фразе с 今天、昨天、明天 и прочитайте их с правильными тонами."},{"id":11,"title":"Часы: 点 и 分","duration":24,"goal":"Сообщать точное время в часах и минутах.","theory":[{"heading":"Сколько часов","body":"Час на циферблате — <b>点 diǎn</b>. Один час — 一点, восемь часов — 八点. В вопросе 几点？ точное количество часов заменяет 几."},{"heading":"Минуты после часа","body":"Минуты добавляют после 点: 八点十分 — 8:10. Слово 分 fēn здесь означает минуту. Не ставьте 个 между числом и 点 или 分."}],"vocab":[{"hanzi":"点","pinyin":"diǎn","ru":"час; точка","note":"о времени"},{"hanzi":"分","pinyin":"fēn","ru":"минута","note":""},{"hanzi":"一点","pinyin":"yì diǎn","ru":"один час","note":""},{"hanzi":"八点","pinyin":"bā diǎn","ru":"восемь часов","note":""},{"hanzi":"十点","pinyin":"shí diǎn","ru":"десять часов","note":""},{"hanzi":"十分","pinyin":"shí fēn","ru":"десять минут","note":""},{"hanzi":"现在","pinyin":"xiànzài","ru":"сейчас","note":""},{"hanzi":"时间","pinyin":"shíjiān","ru":"время","note":""}],"grammar":[{"rule":"Час: число + 点","explain":"点 следует сразу за числом часов. Вопрос 几点？ не требует 是: *现在是几时?* возможно, но для HSK1 отрабатывайте 现在几点？. Не путайте 点 «час» с 点 «заказать»: значение даёт контекст.","examples":[{"hanzi":"现在八点。","pinyin":"Xiànzài bā diǎn.","ru":"Сейчас восемь часов."},{"hanzi":"我们十点学习。","pinyin":"Wǒmen shí diǎn xuéxí.","ru":"Мы учимся в десять часов."}]},{"rule":"Время с минутами: число + 点 + число + 分","explain":"Сначала часы, потом минуты. В 8:05 можно сказать 八点五分. Ошибка *十分八点* переносит минуты на неправильное место.","examples":[{"hanzi":"八点十分","pinyin":"Bā diǎn shí fēn.","ru":"Восемь часов десять минут."},{"hanzi":"三点二十分","pinyin":"Sān diǎn èrshí fēn.","ru":"Три часа двадцать минут."}]}],"dialogue":{"title":"Перед уроком","lines":[{"speaker":"A","hanzi":"现在几点？","pinyin":"Xiànzài jǐ diǎn?","ru":"Сколько сейчас времени?"},{"speaker":"B","hanzi":"现在八点十分。","pinyin":"Xiànzài bā diǎn shí fēn.","ru":"Сейчас восемь часов десять минут."},{"speaker":"A","hanzi":"我们几点学习？","pinyin":"Wǒmen jǐ diǎn xuéxí?","ru":"Во сколько мы учимся?"},{"speaker":"B","hanzi":"九点学习。","pinyin":"Jiǔ diǎn xuéxí.","ru":"Учимся в девять."}]},"exercises":[{"type":"choice","q":"Как сказать 3:20?","options":["三点二十分","二十分三点","三时二十"],"answer":0,"explain":"Сначала называются часы: 三点, затем минуты: 二十分."},{"type":"input","q":"Напишите пиньинь слова 点.","answer":["diǎn","dian"],"explain":"点 читается diǎn, третий тон."},{"type":"match","q":"Соотнесите запись и значение.","pairs":[{"left":"一点","right":"1:00"},{"left":"八点十分","right":"8:10"},{"left":"十点","right":"10:00"}],"explain":"点 завершает часы, 分 завершает минуты."},{"type":"choice","q":"Что спросить, чтобы узнать текущее время?","options":["你几岁？","现在几点？","今天几月？"],"answer":1,"explain":"现在几点？ — «Сколько сейчас времени?»"},{"type":"input","q":"Запишите иероглифами: 9 часов.","answer":["九点"],"explain":"Число девять + 点: 九点."},{"type":"choice","q":"Как сказать 8:05?","options":["八点五分","五分八点","八点半"],"answer":0,"explain":"Сначала часы, затем пять минут: 八点五分."},{"type":"input","q":"Напишите пиньинь слова 分.","answer":["fēn","fen"],"explain":"分 читается fēn, первый тон."}],"homework":"Посмотрите на часы три раза в течение дня и запишите время по-китайски с 点; если есть минуты, добавьте 分."},{"id":12,"title":"半, 差, 刻: половина и четверть часа","duration":25,"goal":"Понимать и называть половину, четверть и время «без четверти».","theory":[{"heading":"Половина и четверть","body":"<b>半 bàn</b> после часа означает «половина»: 八点半 — 8:30. <b>刻 kè</b> — четверть часа: 一刻 15 минут, 三刻 45 минут. Для 8:15 говорят 八点一刻."},{"heading":"Слово 差","body":"<b>差 chà</b> значит «без» и считает минуты до следующего часа. 差一刻九点 — без четверти девять, то есть 8:45. После 差 сначала говорят сколько осталось, потом следующий час."}],"vocab":[{"hanzi":"半","pinyin":"bàn","ru":"половина","note":""},{"hanzi":"刻","pinyin":"kè","ru":"четверть часа","note":""},{"hanzi":"一刻","pinyin":"yí kè","ru":"четверть часа; 15 минут","note":""},{"hanzi":"三刻","pinyin":"sān kè","ru":"три четверти часа; 45 минут","note":""},{"hanzi":"差","pinyin":"chà","ru":"не хватает; без","note":"о времени"},{"hanzi":"八点半","pinyin":"bā diǎn bàn","ru":"половина девятого; 8:30","note":""},{"hanzi":"九点一刻","pinyin":"jiǔ diǎn yí kè","ru":"9:15","note":""},{"hanzi":"差一刻九点","pinyin":"chà yí kè jiǔ diǎn","ru":"8:45","note":""}],"grammar":[{"rule":"Час + 点 + 半 / 刻","explain":"半 и 刻 заменяют точное число минут. Не говорите *八点三十分半*: выберите либо 八点半, либо 八点三十分. 一 перед 刻 произносится yí, потому что следующий слог четвёртого тона.","examples":[{"hanzi":"七点半","pinyin":"Qī diǎn bàn.","ru":"Семь тридцать."},{"hanzi":"九点一刻","pinyin":"Jiǔ diǎn yí kè.","ru":"Девять пятнадцать."},{"hanzi":"三点三刻","pinyin":"Sān diǎn sān kè.","ru":"Три сорок пять."}]},{"rule":"差 + количество до часа + следующий час","explain":"Эта схема отсчитывает назад от следующего часа. Поэтому 8:45 — 差一刻九点, а не *差一刻八点*. Если такой порядок пока непривычен, используйте понятное 八点四十五分.","examples":[{"hanzi":"差五分十点","pinyin":"Chà wǔ fēn shí diǎn.","ru":"Без пяти десять."},{"hanzi":"差一刻九点","pinyin":"Chà yí kè jiǔ diǎn.","ru":"Без четверти девять."}]}],"dialogue":{"title":"Договорились встретиться","lines":[{"speaker":"A","hanzi":"我们几点见？","pinyin":"Wǒmen jǐ diǎn jiàn?","ru":"Во сколько встретимся?"},{"speaker":"B","hanzi":"八点半，好吗？","pinyin":"Bā diǎn bàn, hǎo ma?","ru":"В половине девятого, хорошо?"},{"speaker":"A","hanzi":"八点半太早。九点一刻吧。","pinyin":"Bā diǎn bàn tài zǎo. Jiǔ diǎn yí kè ba.","ru":"В 8:30 слишком рано. Давай в 9:15."},{"speaker":"B","hanzi":"好，九点一刻见。","pinyin":"Hǎo, jiǔ diǎn yí kè jiàn.","ru":"Хорошо, до встречи в 9:15."}]},"exercises":[{"type":"choice","q":"Что означает 八点半？","options":["8:15","8:30","8:45"],"answer":1,"explain":"半 — половина часа, поэтому это 8:30."},{"type":"input","q":"Напишите пиньинь слова 半.","answer":["bàn","ban"],"explain":"半 читается bàn."},{"type":"match","q":"Соотнесите выражения.","pairs":[{"left":"七点半","right":"7:30"},{"left":"九点一刻","right":"9:15"},{"left":"差一刻九点","right":"8:45"}],"explain":"半 — 30 минут, 一刻 — 15 минут, 差 отсчитывает до следующего часа."},{"type":"choice","q":"Как сказать «без четверти десять»?","options":["十点三刻","差一刻十点","差一刻九点"],"answer":1,"explain":"Следующий полный час — десять, поэтому 差一刻十点."},{"type":"input","q":"Запишите иероглифами: 6:30.","answer":["六点半"],"explain":"После часа поставьте 半."},{"type":"choice","q":"Как сказать 9:45?","options":["九点一刻","九点半","九点三刻"],"answer":2,"explain":"Три четверти часа после девяти — 九点三刻."},{"type":"input","q":"Напишите пиньинь слова 刻.","answer":["kè","ke"],"explain":"刻 читается kè, четвёртый тон."}],"homework":"Назовите тремя способами время 8:30, 9:15 и 8:45: сначала по-китайски, затем проверьте себя по записи."},{"id":13,"title":"Время суток: 早上, 上午, 中午, 下午, 晚上","duration":22,"goal":"Добавлять к часу время суток, чтобы избежать неоднозначности.","theory":[{"heading":"Часть дня перед временем","body":"Части дня ставят перед часом: <b>早上八点</b> — 8 утра, 下午三点 — 3 дня. Это важно, потому что 三点 без контекста может быть и 3:00, и 15:00. В китайском не используют отдельные формы «a.m.» и «p.m.»."},{"heading":"Границы условны","body":"早上 — раннее утро, 上午 — до полудня, 中午 — около полудня, 下午 — после полудня, 晚上 — вечер. Не ищите минутно точных границ: выбирайте слово по естественному контексту."}],"vocab":[{"hanzi":"早上","pinyin":"zǎoshang","ru":"утром (ранним)","note":""},{"hanzi":"上午","pinyin":"shàngwǔ","ru":"до полудня","note":""},{"hanzi":"中午","pinyin":"zhōngwǔ","ru":"в полдень; днём","note":""},{"hanzi":"下午","pinyin":"xiàwǔ","ru":"после полудня","note":""},{"hanzi":"晚上","pinyin":"wǎnshang","ru":"вечером; ночью","note":""},{"hanzi":"早","pinyin":"zǎo","ru":"рано; утро","note":""},{"hanzi":"晚","pinyin":"wǎn","ru":"поздно; вечер","note":""},{"hanzi":"睡觉","pinyin":"shuìjiào","ru":"спать; ложиться спать","note":""}],"grammar":[{"rule":"Часть суток + время","explain":"Слово 早上、下午 или 晚上 стоит перед числом с 点. Не помещайте его после времени: естественно 下午三点, а не *三点下午*. Можно начать всю фразу с такого обстоятельства.","examples":[{"hanzi":"早上七点起床。","pinyin":"Zǎoshang qī diǎn qǐchuáng.","ru":"В семь утра я встаю."},{"hanzi":"下午三点工作。","pinyin":"Xiàwǔ sān diǎn gōngzuò.","ru":"В три часа дня работаю."},{"hanzi":"晚上十点睡觉。","pinyin":"Wǎnshang shí diǎn shuìjiào.","ru":"В десять вечера ложусь спать."}]}],"dialogue":{"title":"Распорядок дня","lines":[{"speaker":"A","hanzi":"你早上几点起床？","pinyin":"Nǐ zǎoshang jǐ diǎn qǐchuáng?","ru":"Во сколько ты встаёшь утром?"},{"speaker":"B","hanzi":"早上七点。","pinyin":"Zǎoshang qī diǎn.","ru":"В семь утра."},{"speaker":"A","hanzi":"你晚上几点睡觉？","pinyin":"Nǐ wǎnshang jǐ diǎn shuìjiào?","ru":"Во сколько ты ложишься спать вечером?"},{"speaker":"B","hanzi":"晚上十点半。","pinyin":"Wǎnshang shí diǎn bàn.","ru":"В половине одиннадцатого вечера."}]},"exercises":[{"type":"choice","q":"Как сказать «3 часа дня»?","options":["下午三点","三点下午","上午三点"],"answer":0,"explain":"Часть дня ставится перед временем: 下午三点."},{"type":"input","q":"Напишите пиньинь слова 中午.","answer":["zhōngwǔ","zhongwu"],"explain":"中午 читается zhōngwǔ."},{"type":"match","q":"Соотнесите.","pairs":[{"left":"早上","right":"раннее утро"},{"left":"下午","right":"после полудня"},{"left":"晚上","right":"вечер"}],"explain":"Части суток уточняют время с 点."},{"type":"choice","q":"Когда естественно сказать 晚上十点？","options":["в 10 утра","в 10 вечера","в полдень"],"answer":1,"explain":"晚上 означает вечер, поэтому это 22:00."},{"type":"input","q":"Запишите иероглифами: утром.","answer":["早上"],"explain":"早上 — раннее утро."},{"type":"choice","q":"Какой вариант означает 7 утра?","options":["晚上七点","早上七点","下午七点"],"answer":1,"explain":"早上 уточняет, что семь часов утром."},{"type":"input","q":"Напишите пиньинь слова 下午.","answer":["xiàwǔ","xiawu"],"explain":"下午 читается xiàwǔ."}],"homework":"Опишите свой вымышленный день тремя фразами: с 早上, 下午 и 晚上. В каждой укажите час."},{"id":14,"title":"Вопрос о времени: 现在几点？几点开始？","duration":24,"goal":"Спрашивать текущее время и время начала события.","theory":[{"heading":"Два разных вопроса","body":"现在几点？ спрашивает время в эту минуту. 几点开始？ спрашивает, во сколько начнётся конкретное действие или событие. Добавьте существительное перед 开始: 课几点开始？ «Во сколько начинается урок?»."},{"heading":"Ответ на вопрос о начале","body":"В ответе назовите время перед действием: 八点开始. Можно уточнить, что речь о занятии: 课八点开始. Не нужно добавлять 是 между временем и 开始."}],"vocab":[{"hanzi":"开始","pinyin":"kāishǐ","ru":"начинаться; начинать","note":""},{"hanzi":"上课","pinyin":"shàngkè","ru":"начинать урок; быть на уроке","note":""},{"hanzi":"下课","pinyin":"xiàkè","ru":"заканчивать урок","note":""},{"hanzi":"课","pinyin":"kè","ru":"урок","note":""},{"hanzi":"电影","pinyin":"diànyǐng","ru":"фильм","note":""},{"hanzi":"看","pinyin":"kàn","ru":"смотреть; читать","note":""},{"hanzi":"什么时候","pinyin":"shénme shíhou","ru":"когда","note":""},{"hanzi":"见","pinyin":"jiàn","ru":"видеться; встречаться","note":""}],"grammar":[{"rule":"现在几点？","explain":"现在 делает вопрос вопросом о текущем моменте. Ответ обычно начинается с 现在, но его можно опустить, если ситуация понятна. Не используйте 几分, если хотите узнать часы целиком.","examples":[{"hanzi":"现在几点？","pinyin":"Xiànzài jǐ diǎn?","ru":"Сколько сейчас времени?"},{"hanzi":"现在七点半。","pinyin":"Xiànzài qī diǎn bàn.","ru":"Сейчас 7:30."}]},{"rule":"Событие + 几点开始？","explain":"几点 стоит непосредственно перед 开始. В ответе место 几 заменяет конкретное время: 电影晚上八点开始. Ошибка *开始几点？* звучит неестественно.","examples":[{"hanzi":"课几点开始？","pinyin":"Kè jǐ diǎn kāishǐ?","ru":"Во сколько начинается урок?"},{"hanzi":"课上午九点开始。","pinyin":"Kè shàngwǔ jiǔ diǎn kāishǐ.","ru":"Урок начинается в девять утра."}]}],"dialogue":{"title":"Перед фильмом","lines":[{"speaker":"A","hanzi":"电影几点开始？","pinyin":"Diànyǐng jǐ diǎn kāishǐ?","ru":"Во сколько начинается фильм?"},{"speaker":"B","hanzi":"晚上八点开始。","pinyin":"Wǎnshang bā diǎn kāishǐ.","ru":"Начинается в восемь вечера."},{"speaker":"A","hanzi":"现在几点？","pinyin":"Xiànzài jǐ diǎn?","ru":"Сколько сейчас?"},{"speaker":"B","hanzi":"现在七点四十分。","pinyin":"Xiànzài qī diǎn sìshí fēn.","ru":"Сейчас 7:40."}]},"exercises":[{"type":"choice","q":"Как спросить «Во сколько начинается урок?»","options":["几点课开始？","课几点开始？","开始课几点？"],"answer":1,"explain":"Название события ставится перед 几点开始."},{"type":"input","q":"Напишите пиньинь слова 开始.","answer":["kāishǐ","kaishi"],"explain":"开始 читается kāishǐ."},{"type":"match","q":"Соотнесите вопросы.","pairs":[{"left":"现在几点？","right":"который сейчас час?"},{"left":"课几点开始？","right":"во сколько начинается урок?"},{"left":"什么时候见？","right":"когда встретимся?"}],"explain":"Каждый вопрос уточняет время по-своему."},{"type":"choice","q":"Выберите верный ответ на «电影几点开始？»","options":["现在八点。","电影八点开始。","八点电影。"],"answer":1,"explain":"Ответ повторяет действие: 电影八点开始。"},{"type":"input","q":"Запишите иероглифами: Фильм начинается в 8 вечера.","answer":["电影晚上八点开始"],"explain":"Время ставится перед 开始."},{"type":"choice","q":"Что ответить на «现在几点？»","options":["现在八点。","课八点开始。","明天八点。"],"answer":0,"explain":"Вопрос 现在几点？ просит назвать текущее время."},{"type":"input","q":"Напишите пиньинь слова 什么时候.","answer":["shénme shíhou","shenme shihou","shenmeshihou"],"explain":"什么时候 читается shénme shíhou."}],"homework":"Напишите два мини-диалога: один с 现在几点？, другой с 课几点开始？. Дайте в каждом точный ответ."},{"id":15,"title":"Обстоятельство времени в предложении","duration":25,"goal":"Ставить дату, день или час в естественное место китайского предложения.","theory":[{"heading":"Главное место времени","body":"Часто порядок такой: <b>время + подлежащее + действие</b>. Например: 明天我去学校. Если время относится к месту или действию, его не нужно переносить в конец по русской привычке."},{"heading":"Несколько уточнений","body":"Более крупное время ставится раньше мелкого: 今天下午三点我学习. Сначала день, затем часть суток, затем час. После подлежащего время тоже возможно в некоторых фразах, но начинайте с простой и надёжной модели."}],"vocab":[{"hanzi":"去","pinyin":"qù","ru":"идти; ехать","note":""},{"hanzi":"来","pinyin":"lái","ru":"приходить; приезжать","note":""},{"hanzi":"学校","pinyin":"xuéxiào","ru":"школа","note":""},{"hanzi":"家","pinyin":"jiā","ru":"дом; семья","note":""},{"hanzi":"吃","pinyin":"chī","ru":"есть","note":""},{"hanzi":"饭","pinyin":"fàn","ru":"еда; рис","note":""},{"hanzi":"上午九点","pinyin":"shàngwǔ jiǔ diǎn","ru":"9 часов утра","note":""},{"hanzi":"下午三点","pinyin":"xiàwǔ sān diǎn","ru":"3 часа дня","note":""}],"grammar":[{"rule":"Время + подлежащее + глагол + дополнение","explain":"Поместите указание времени перед тем, кто действует. Не стройте по русскому шаблону *我去学校明天*: естественно 明天我去学校. Если время очень короткое, оно всё равно может быть первым.","examples":[{"hanzi":"明天我去学校。","pinyin":"Míngtiān wǒ qù xuéxiào.","ru":"Завтра я иду в школу."},{"hanzi":"下午三点她来。","pinyin":"Xiàwǔ sān diǎn tā lái.","ru":"Она придёт в три часа дня."}]},{"rule":"День + часть суток + час + подлежащее + действие","explain":"Уточнения идут от широкого к точному. В 今天上午九点我们上课 нет предлога «в»: время выражает свою роль положением. Не ставьте 今天 после часа.","examples":[{"hanzi":"今天上午九点我们上课。","pinyin":"Jīntiān shàngwǔ jiǔ diǎn wǒmen shàngkè.","ru":"Сегодня в девять утра у нас урок."},{"hanzi":"明天晚上八点我看电影。","pinyin":"Míngtiān wǎnshang bā diǎn wǒ kàn diànyǐng.","ru":"Завтра в восемь вечера я смотрю фильм."}]}],"dialogue":{"title":"Дневной план","lines":[{"speaker":"A","hanzi":"你明天做什么？","pinyin":"Nǐ míngtiān zuò shénme?","ru":"Что ты делаешь завтра?"},{"speaker":"B","hanzi":"明天上午九点我去学校。","pinyin":"Míngtiān shàngwǔ jiǔ diǎn wǒ qù xuéxiào.","ru":"Завтра в девять утра я иду в школу."},{"speaker":"A","hanzi":"下午呢？","pinyin":"Xiàwǔ ne?","ru":"А днём?"},{"speaker":"B","hanzi":"下午三点我回家吃饭。","pinyin":"Xiàwǔ sān diǎn wǒ huí jiā chī fàn.","ru":"В три дня я возвращаюсь домой поесть."}]},"exercises":[{"type":"choice","q":"Выберите естественный порядок.","options":["我明天去学校。","明天我去学校。","去学校我明天。"],"answer":1,"explain":"Для базовой модели время ставится в начале: 明天我去学校。"},{"type":"input","q":"Напишите пиньинь слова 学校.","answer":["xuéxiào","xuexiao"],"explain":"学校 читается xuéxiào."},{"type":"match","q":"Соотнесите части в правильном порядке.","pairs":[{"left":"今天","right":"день"},{"left":"下午","right":"часть суток"},{"left":"三点","right":"час"}],"explain":"Время уточняется от общего к конкретному."},{"type":"choice","q":"Что будет раньше в предложении?","options":["八点，今天","今天，八点","я，今天"],"answer":1,"explain":"Сначала более широкий период 今天, потом точное 八点."},{"type":"input","q":"Запишите иероглифами: Завтра я иду домой.","answer":["明天我回家"],"explain":"Время 明天 стоит перед 我."},{"type":"choice","q":"Выберите фразу «Сегодня в 8 вечера я смотрю фильм».","options":["我今天晚上八点看电影。","今天晚上八点我看电影。","看电影今天晚上八点我。"],"answer":1,"explain":"Время от общего к точному ставится перед подлежащим."},{"type":"input","q":"Напишите пиньинь фразы 明天晚上八点.","answer":["míngtiān wǎnshang bā diǎn","mingtian wanshang ba dian","mingtianwanshangbadian"],"explain":"Фраза читается míngtiān wǎnshang bā diǎn."}],"homework":"Перестройте по модели «время + кто + действие» три свои старые фразы из уроков 10–14."},{"id":16,"title":"Частица 了: завершённое действие в прошлом","duration":26,"goal":"Сообщать, что действие уже произошло или завершилось.","theory":[{"heading":"Что показывает 了","body":"<b>了 le</b> после глагола показывает, что конкретное действие завершено. 我吃了饭 — «я поел». Она не равна русскому прошедшему времени: важен результат или факт завершения."},{"heading":"Время и 了 вместе","body":"Слово вчера уже задаёт прошлое, но 了 подчёркивает завершённость: 昨天我看了电影. В отрицании с 没 используйте 没 + глагол, без 了: 我没看电影. Не говорите *没看了*."}],"vocab":[{"hanzi":"了","pinyin":"le","ru":"частица завершённости","note":"не имеет отдельного перевода"},{"hanzi":"吃了","pinyin":"chī le","ru":"поел; съел","note":""},{"hanzi":"看了","pinyin":"kàn le","ru":"посмотрел; прочитал","note":""},{"hanzi":"买","pinyin":"mǎi","ru":"покупать","note":""},{"hanzi":"买了","pinyin":"mǎi le","ru":"купил","note":""},{"hanzi":"没","pinyin":"méi","ru":"не; не было","note":"для прошлого"},{"hanzi":"回","pinyin":"huí","ru":"возвращаться","note":""},{"hanzi":"回来了","pinyin":"huí lái le","ru":"вернулся","note":""}],"grammar":[{"rule":"Глагол + 了 (+ дополнение)","explain":"了 стоит сразу после действия, которое завершилось. Если есть дополнение, оно идёт дальше: 看了电影. Ошибка *了看电影* возникает, когда частицу переносят перед глаголом.","examples":[{"hanzi":"我吃了饭。","pinyin":"Wǒ chī le fàn.","ru":"Я поел."},{"hanzi":"她看了电影。","pinyin":"Tā kàn le diànyǐng.","ru":"Она посмотрела фильм."},{"hanzi":"昨天我买了书。","pinyin":"Zuótiān wǒ mǎi le shū.","ru":"Вчера я купил книгу."}]},{"rule":"Отрицание прошлого: 没 + глагол","explain":"С 没 частица 了 после глагола не нужна. 没 смотрит на факт действия: 我没去学校 — «я не ходил в школу». Не заменяйте 没 на 不, когда говорите о завершённом прошлом действии.","examples":[{"hanzi":"我没吃饭。","pinyin":"Wǒ méi chī fàn.","ru":"Я не ел."},{"hanzi":"昨天他没来。","pinyin":"Zuótiān tā méi lái.","ru":"Вчера он не пришёл."}]}],"dialogue":{"title":"После выходных","lines":[{"speaker":"A","hanzi":"昨天你看电影了吗？","pinyin":"Zuótiān nǐ kàn diànyǐng le ma?","ru":"Ты вчера посмотрел фильм?"},{"speaker":"B","hanzi":"看了。我看了一个中国电影。","pinyin":"Kàn le. Wǒ kàn le yí ge Zhōngguó diànyǐng.","ru":"Да. Я посмотрел один китайский фильм."},{"speaker":"A","hanzi":"你吃饭了吗？","pinyin":"Nǐ chī fàn le ma?","ru":"Ты поел?"},{"speaker":"B","hanzi":"还没吃。","pinyin":"Hái méi chī.","ru":"Ещё не ел."}]},"exercises":[{"type":"choice","q":"Выберите «Я купил книгу».","options":["我买书。","我买了书。","我了买书。"],"answer":1,"explain":"了 ставится после 买 и показывает завершённую покупку."},{"type":"input","q":"Напишите пиньинь слова 没.","answer":["méi","mei"],"explain":"没 читается méi."},{"type":"match","q":"Соотнесите фразы.","pairs":[{"left":"吃了饭","right":"поел"},{"left":"没吃饭","right":"не ел"},{"left":"看了电影","right":"посмотрел фильм"}],"explain":"了 показывает завершённость, 没 отрицает факт в прошлом."},{"type":"choice","q":"Как правильно сказать «Я вчера не пришёл»?","options":["昨天我不来了。","昨天我没来。","昨天我没来了。"],"answer":1,"explain":"Для прошлого отрицания используйте 没 + глагол без 了."},{"type":"input","q":"Запишите иероглифами: Я посмотрел фильм.","answer":["我看了电影"],"explain":"了 идёт после 看."},{"type":"choice","q":"Где стоит 了 в «Я купил книгу»?","options":["我了买书。","我买了书。","我买书了。"],"answer":1,"explain":"В этой модели 了 стоит после глагола 买."},{"type":"input","q":"Напишите пиньинь слова 买了.","answer":["mǎi le","mai le","maile"],"explain":"买了 читается mǎi le."}],"homework":"Напишите четыре фразы: две о том, что вы «сделали вчера», с 了, и две отрицательные с 没."},{"id":17,"title":"现在 и 以后, 每天 и регулярность","duration":24,"goal":"Различать действие сейчас, после момента и повторяющуюся привычку.","theory":[{"heading":"Сейчас и потом","body":"<b>现在 xiànzài</b> задаёт текущий момент: 现在我学习. <b>以后 yǐhòu</b> ставят после времени или события: 八点以后 «после восьми», 以后我想去中国 «потом я хочу поехать в Китай»."},{"heading":"Каждый день","body":"每天 měitiān означает «каждый день» и указывает на привычку. Как и другое время, его удобно ставить в начале: 我每天学习中文 или 每天我学习中文. Не путайте 每天 с 今天: первое повторяется, второе — только сегодня."}],"vocab":[{"hanzi":"以后","pinyin":"yǐhòu","ru":"после; потом","note":""},{"hanzi":"每天","pinyin":"měitiān","ru":"каждый день","note":""},{"hanzi":"常常","pinyin":"chángcháng","ru":"часто","note":""},{"hanzi":"也","pinyin":"yě","ru":"тоже","note":""},{"hanzi":"都","pinyin":"dōu","ru":"все; оба","note":""},{"hanzi":"早饭","pinyin":"zǎofàn","ru":"завтрак","note":""},{"hanzi":"喝","pinyin":"hē","ru":"пить","note":""},{"hanzi":"水","pinyin":"shuǐ","ru":"вода","note":""}],"grammar":[{"rule":"现在 / 每天 + подлежащее + действие","explain":"现在 описывает ситуацию в этот момент, а 每天 — обычное повторение. Не присоединяйте 了 к привычке без причины: 每天我喝水, не *每天我喝了水*. Время можно поставить и после подлежащего: 我每天喝水.","examples":[{"hanzi":"现在我喝水。","pinyin":"Xiànzài wǒ hē shuǐ.","ru":"Сейчас я пью воду."},{"hanzi":"我每天吃早饭。","pinyin":"Wǒ měitiān chī zǎofàn.","ru":"Я каждый день завтракаю."},{"hanzi":"她常常学习。","pinyin":"Tā chángcháng xuéxí.","ru":"Она часто учится."}]},{"rule":"Время / действие + 以后","explain":"以后 следует за точкой отсчёта. 八点以后 значит «после восьми», а не «восемь часов спустя». Ошибка *以后八点* меняет естественный порядок.","examples":[{"hanzi":"八点以后我回家。","pinyin":"Bā diǎn yǐhòu wǒ huí jiā.","ru":"После восьми я возвращаюсь домой."},{"hanzi":"以后我想去中国。","pinyin":"Yǐhòu wǒ xiǎng qù Zhōngguó.","ru":"Потом я хочу поехать в Китай."}]}],"dialogue":{"title":"О привычках","lines":[{"speaker":"A","hanzi":"你每天几点吃早饭？","pinyin":"Nǐ měitiān jǐ diǎn chī zǎofàn?","ru":"Во сколько ты каждый день завтракаешь?"},{"speaker":"B","hanzi":"我每天早上七点吃早饭。","pinyin":"Wǒ měitiān zǎoshang qī diǎn chī zǎofàn.","ru":"Я каждый день завтракаю в семь утра."},{"speaker":"A","hanzi":"你现在喝什么？","pinyin":"Nǐ xiànzài hē shénme?","ru":"Что ты сейчас пьёшь?"},{"speaker":"B","hanzi":"我现在喝水。","pinyin":"Wǒ xiànzài hē shuǐ.","ru":"Сейчас я пью воду."}]},"exercises":[{"type":"choice","q":"Что означает 每天？","options":["сегодня","каждый день","после завтра"],"answer":1,"explain":"每天 говорит о регулярной привычке: «каждый день». "},{"type":"input","q":"Напишите пиньинь слова 以后.","answer":["yǐhòu","yihou"],"explain":"以后 читается yǐhòu."},{"type":"match","q":"Соотнесите слова.","pairs":[{"left":"现在","right":"сейчас"},{"left":"每天","right":"каждый день"},{"left":"以后","right":"потом; после"}],"explain":"Эти слова указывают разный тип времени."},{"type":"choice","q":"Как сказать «После восьми я иду домой»?","options":["以后八点我回家。","八点以后我回家。","八点我以后回家。"],"answer":1,"explain":"Точка отсчёта стоит перед 以后: 八点以后."},{"type":"input","q":"Запишите иероглифами: Я каждый день пью воду.","answer":["我每天喝水","每天我喝水"],"explain":"每天 можно поставить после подлежащего или в начало."},{"type":"choice","q":"Какая фраза говорит о привычке?","options":["我现在喝水。","我每天喝水。","我以后喝水。"],"answer":1,"explain":"每天 показывает регулярное действие."},{"type":"input","q":"Напишите пиньинь слова 每天.","answer":["měitiān","meitian"],"explain":"每天 читается měitiān."}],"homework":"Составьте четыре фразы о привычках с 每天 или 常常 и одну фразу о планах с 以后."},{"id":18,"title":"Цена и деньги: 多少钱？块, 元","duration":25,"goal":"Спрашивать цену и называть сумму в юанях.","theory":[{"heading":"Вопрос о цене","body":"Чтобы узнать цену, спросите <b>多少钱？duōshao qián?</b> Буквально это «сколько денег?». Это готовая вопросительная формула: не добавляйте 几 перед 钱."},{"heading":"Два слова для юаня","body":"<b>元 yuán</b> — официальное слово «юань», его увидите на ценнике. <b>块 kuài</b> — разговорное «юань»: 十块 и 十元 — десять юаней. После точной суммы слово валюты обычно ставится в конце."}],"vocab":[{"hanzi":"多少钱","pinyin":"duōshao qián","ru":"сколько стоит","note":""},{"hanzi":"钱","pinyin":"qián","ru":"деньги","note":""},{"hanzi":"块","pinyin":"kuài","ru":"юань (разговорно)","note":""},{"hanzi":"元","pinyin":"yuán","ru":"юань (официально)","note":""},{"hanzi":"毛","pinyin":"máo","ru":"десятая часть юаня","note":""},{"hanzi":"贵","pinyin":"guì","ru":"дорогой","note":""},{"hanzi":"便宜","pinyin":"piányi","ru":"дешёвый","note":""},{"hanzi":"买","pinyin":"mǎi","ru":"покупать","note":""}],"grammar":[{"rule":"Предмет + 多少钱？","explain":"Название вещи можно поставить перед вопросом о цене. В ответе цена заканчивается 块 или 元: 这本书十块. Не говорите *多少钱块？*: 多少钱 уже содержит вопрос о сумме.","examples":[{"hanzi":"这个多少钱？","pinyin":"Zhège duōshao qián?","ru":"Сколько это стоит?"},{"hanzi":"这本书多少钱？","pinyin":"Zhè běn shū duōshao qián?","ru":"Сколько стоит эта книга?"},{"hanzi":"十块。","pinyin":"Shí kuài.","ru":"Десять юаней."}]},{"rule":"Число + 块 / 元 (+ число + 毛)","explain":"块 и 元 в данном контексте взаимозаменяемы по смыслу, но не ставьте оба одновременно: *十块元* неверно. Для 10,5 юаня можно сказать 十块五毛. Не путайте 毛 «десять фэней» с 猫 «кошка».","examples":[{"hanzi":"二十元","pinyin":"Èrshí yuán.","ru":"Двадцать юаней."},{"hanzi":"五块钱","pinyin":"Wǔ kuài qián.","ru":"Пять юаней."},{"hanzi":"十块五毛","pinyin":"Shí kuài wǔ máo.","ru":"Десять юаней пять мао."}]}],"dialogue":{"title":"В книжном магазине","lines":[{"speaker":"A","hanzi":"这本书多少钱？","pinyin":"Zhè běn shū duōshao qián?","ru":"Сколько стоит эта книга?"},{"speaker":"B","hanzi":"二十块。","pinyin":"Èrshí kuài.","ru":"Двадцать юаней."},{"speaker":"A","hanzi":"太贵了。","pinyin":"Tài guì le.","ru":"Слишком дорого."},{"speaker":"B","hanzi":"那本书十块，很便宜。","pinyin":"Nà běn shū shí kuài, hěn piányi.","ru":"Та книга — десять юаней, очень дёшево."}]},"exercises":[{"type":"choice","q":"Как спросить цену книги?","options":["这本书几钱？","这本书多少钱？","这本书多少块？"],"answer":1,"explain":"多少钱 — стандартный вопрос «сколько стоит?». "},{"type":"input","q":"Напишите пиньинь слова 元.","answer":["yuán","yuan"],"explain":"元 читается yuán."},{"type":"match","q":"Соотнесите.","pairs":[{"left":"十块","right":"10 юаней"},{"left":"二十元","right":"20 юаней"},{"left":"五毛","right":"0,5 юаня"}],"explain":"块 — разговорный юань, 元 — официальный, 毛 — десятая часть."},{"type":"choice","q":"Что НЕ говорят для десяти юаней?","options":["十块","十元","十块元"],"answer":2,"explain":"Выберите либо 块, либо 元, но не оба сразу."},{"type":"input","q":"Запишите иероглифами: 8 юаней (разговорно).","answer":["八块","八块钱"],"explain":"Разговорно скажите 八块 или 八块钱."},{"type":"choice","q":"Как назвать 20 юаней официально?","options":["二十块元","二十元","二十毛"],"answer":1,"explain":"元 — официальное слово для юаня."},{"type":"input","q":"Напишите пиньинь вопроса 多少钱？","answer":["duōshao qián","duoshao qian","duoshaoqian"],"explain":"多少钱 читается duōshao qián."}],"homework":"Придумайте ценник для трёх вещей и составьте к каждому вопрос «多少钱？» и ответ с 块 или 元."},{"id":19,"title":"Номер телефона и цифры в речи: 幺","duration":24,"goal":"Читать и записывать номер телефона по одной цифре.","theory":[{"heading":"Цифры по одной","body":"Номер телефона не читают как число с десятками и сотнями. Каждую цифру произносят отдельно: 138 читается 一三八. Разбивать длинный номер на группы удобно для памяти, но порядок цифр не меняется."},{"heading":"Особое чтение единицы","body":"В телефонных номерах и других последовательностях цифру 1 часто произносят <b>幺 yāo</b>, чтобы её было легче расслышать. Обычное 一 тоже понимают. Не заменяйте 幺 в датах или количестве: там остаётся 一."}],"vocab":[{"hanzi":"电话","pinyin":"diànhuà","ru":"телефон; телефонный звонок","note":""},{"hanzi":"电话号码","pinyin":"diànhuà hàomǎ","ru":"номер телефона","note":""},{"hanzi":"号码","pinyin":"hàomǎ","ru":"номер","note":""},{"hanzi":"幺","pinyin":"yāo","ru":"единица в номере телефона","note":""},{"hanzi":"零","pinyin":"líng","ru":"ноль","note":"в последовательности цифр"},{"hanzi":"手机","pinyin":"shǒujī","ru":"мобильный телефон","note":""},{"hanzi":"给","pinyin":"gěi","ru":"давать; для; кому-то","note":""},{"hanzi":"打电话","pinyin":"dǎ diànhuà","ru":"звонить по телефону","note":""}],"grammar":[{"rule":"Номер: цифра + цифра + цифра…","explain":"В телефонном номере каждую цифру читают отдельно: 205 — 二零五, не 二百零五. Ноль всегда 零. Не вставляйте 点 и 分: они относятся только ко времени.","examples":[{"hanzi":"138","pinyin":"Yāo sān bā.","ru":"Один-три-восемь (в номере)."},{"hanzi":"205","pinyin":"Èr líng wǔ.","ru":"Два-ноль-пять."},{"hanzi":"010","pinyin":"Líng yāo líng.","ru":"Ноль-один-ноль."}]},{"rule":"幺 вместо 一 только в номере","explain":"幺 используют как чёткое «один» при диктовке номера, особенно по телефону. В любой учебной дате говорите 一月, а не *幺月*. При записи иероглиф 幺 заменяет именно цифру 1, а не слово «один предмет».","examples":[{"hanzi":"我的电话号码是幺三八。","pinyin":"Wǒ de diànhuà hàomǎ shì yāo sān bā.","ru":"Мой номер телефона — 138."},{"hanzi":"请给我打电话。","pinyin":"Qǐng gěi wǒ dǎ diànhuà.","ru":"Пожалуйста, позвони мне."}]}],"dialogue":{"title":"Обмен номерами","lines":[{"speaker":"A","hanzi":"你的电话号码是多少？","pinyin":"Nǐ de diànhuà hàomǎ shì duōshao?","ru":"Какой твой номер телефона?"},{"speaker":"B","hanzi":"是幺三八，二零五，六七九。","pinyin":"Shì yāo sān bā, èr líng wǔ, liù qī jiǔ.","ru":"138, 205, 679."},{"speaker":"A","hanzi":"幺三八，二零五，六七九，对吗？","pinyin":"Yāo sān bā, èr líng wǔ, liù qī jiǔ, duì ma?","ru":"138, 205, 679, верно?"},{"speaker":"B","hanzi":"对。请给我打电话。","pinyin":"Duì. Qǐng gěi wǒ dǎ diànhuà.","ru":"Верно. Пожалуйста, позвони мне."}]},"exercises":[{"type":"choice","q":"Как прочитать 105 в номере?","options":["一百零五","幺零五","十零五"],"answer":1,"explain":"В номере цифры читаются отдельно; 1 можно сказать 幺."},{"type":"input","q":"Напишите пиньинь слова 幺.","answer":["yāo","yao"],"explain":"幺 читается yāo."},{"type":"match","q":"Соотнесите запись номера и чтение.","pairs":[{"left":"138","right":"幺三八"},{"left":"205","right":"二零五"},{"left":"670","right":"六七零"}],"explain":"В последовательности каждую цифру называют отдельно."},{"type":"choice","q":"Где НЕ надо использовать 幺?","options":["в номере 138","в дате 一月","при диктовке 010"],"answer":1,"explain":"В дате первая цифра месяца читается 一, а 幺 — особое чтение номера."},{"type":"input","q":"Запишите иероглифами цифры номера 210.","answer":["二幺零","二一零"],"explain":"В номере можно произнести 1 как 幺 или 一."},{"type":"choice","q":"Как прочитать 120 в телефонном номере?","options":["一百二十","幺二零","十二零"],"answer":1,"explain":"В номере цифры читают по одной; 1 можно сказать 幺."},{"type":"input","q":"Напишите пиньинь слова 电话号码.","answer":["diànhuà hàomǎ","dianhua haoma","dianhuahaoma"],"explain":"电话号码 читается diànhuà hàomǎ."}],"homework":"Придумайте безопасный девятизначный номер, разбейте его на три группы и запишите, как вы продиктуете каждую цифру по-китайски."},{"id":20,"title":"Итоговое повторение: числа, время и даты","duration":30,"goal":"Уверенно использовать числа, даты, время, регулярность, цену и номера в связанных ситуациях.","theory":[{"heading":"Что уже умеем","body":"Вы можете строить числа, выбирать счётные слова, говорить дату и время, назначать начало события и называть цену. В сложной фразе сначала дайте ориентир во времени, затем человека и действие: 明天晚上八点我们看电影."},{"heading":"Проверка себя","body":"Перед ответом спросите: я называю количество, дату, время или номер? Для количества нужны число и счётное слово; год и номер читаются цифрами по одной; для времени используйте 点. Это помогает не смешивать похожие модели."},{"heading":"Связанная речь","body":"Полезно соединять изученные элементы в реальном диалоге: дата встречи, время начала, цена билета и телефон. Не стремитесь сказать всё одним длинным предложением: несколько коротких точных фраз звучат естественно."}],"vocab":[{"hanzi":"生日","pinyin":"shēngrì","ru":"день рождения","note":"повторение даты"},{"hanzi":"票","pinyin":"piào","ru":"билет","note":""},{"hanzi":"商店","pinyin":"shāngdiàn","ru":"магазин","note":""},{"hanzi":"医院","pinyin":"yīyuàn","ru":"больница","note":""},{"hanzi":"医生","pinyin":"yīshēng","ru":"врач","note":""},{"hanzi":"名字","pinyin":"míngzi","ru":"имя","note":""},{"hanzi":"再见","pinyin":"zàijiàn","ru":"до свидания","note":""},{"hanzi":"帮助","pinyin":"bāngzhù","ru":"помогать; помощь","note":""}],"grammar":[{"rule":"Итоговая модель планирования: дата/время + кто + действие","explain":"Собирайте время от большого к малому: 年、月、日, затем часть суток и 点. После этой группы поставьте человека и действие. Не ставьте номер телефона в ту же модель: номер диктуют отдельно, цифра за цифрой.","examples":[{"hanzi":"八月十八号晚上八点我们看电影。","pinyin":"Bā yuè shíbā hào wǎnshang bā diǎn wǒmen kàn diànyǐng.","ru":"18 августа в восемь вечера мы смотрим фильм."},{"hanzi":"明天上午九点课开始。","pinyin":"Míngtiān shàngwǔ jiǔ diǎn kè kāishǐ.","ru":"Завтра в девять утра начинается урок."}]},{"rule":"Итоговая проверка типов чисел","explain":"Обычное количество: 三本书; год: 二零二六年; время: 八点半; телефон: 幺三八. Ошибка часто возникает, когда число читают одинаково везде. Сначала определите задачу числа, затем выберите модель.","examples":[{"hanzi":"三本书","pinyin":"Sān běn shū.","ru":"Три книги."},{"hanzi":"二零二六年","pinyin":"Èr líng èr liù nián.","ru":"2026 год."},{"hanzi":"幺三八","pinyin":"Yāo sān bā.","ru":"138 в номере телефона."}]}],"dialogue":{"title":"Встреча в кино","lines":[{"speaker":"A","hanzi":"你的生日是八月十八号吗？","pinyin":"Nǐ de shēngrì shì bā yuè shíbā hào ma?","ru":"Твой день рождения 18 августа?"},{"speaker":"B","hanzi":"对。我们晚上几点看电影？","pinyin":"Duì. Wǒmen wǎnshang jǐ diǎn kàn diànyǐng?","ru":"Да. Во сколько вечером мы смотрим фильм?"},{"speaker":"A","hanzi":"晚上八点。票二十块。","pinyin":"Wǎnshang bā diǎn. Piào èrshí kuài.","ru":"В восемь вечера. Билет стоит двадцать юаней."},{"speaker":"B","hanzi":"好。我七点半给你打电话。","pinyin":"Hǎo. Wǒ qī diǎn bàn gěi nǐ dǎ diànhuà.","ru":"Хорошо. Я позвоню тебе в 7:30."},{"speaker":"A","hanzi":"好，再见！","pinyin":"Hǎo, zàijiàn!","ru":"Хорошо, до встречи!"}]},"exercises":[{"type":"choice","q":"Выберите верную запись «две книги».","options":["两个书","两本书","二本书"],"answer":1,"explain":"Для книг требуется 本; с количеством две естественно 两本书."},{"type":"input","q":"Напишите пиньинь вопроса 现在几点？","answer":["xiànzài jǐ diǎn","xianzai ji dian","xianzaijidian"],"explain":"Фраза читается xiànzài jǐ diǎn."},{"type":"match","q":"Соотнесите тип и пример.","pairs":[{"left":"год","right":"二零二六年"},{"left":"время","right":"八点半"},{"left":"номер","right":"幺三八"}],"explain":"Год и номер читаются по цифрам, а время — с 点 и 半."},{"type":"choice","q":"Как сказать «Урок начинается завтра в 9 утра»?","options":["课明天九点上午开始。","明天上午九点课开始。","明天课开始上午九点。"],"answer":1,"explain":"Сначала день и часть суток, потом час, затем событие и 开始."},{"type":"input","q":"Запишите иероглифами: 18 августа.","answer":["八月十八号","八月十八日"],"explain":"В разговоре используйте 号; с датой календаря также возможен 日."},{"type":"match","q":"Соотнесите вопрос и естественный ответ.","pairs":[{"left":"多少钱？","right":"二十块。"},{"left":"你几岁？","right":"我二十岁。"},{"left":"电话号码是多少？","right":"幺三八二零五。"}],"explain":"Каждый вопрос требует своей модели числа."},{"type":"choice","q":"Что правильно для прошлого отрицания?","options":["昨天我没看电影。","昨天我没看了电影。","昨天我不看了电影。"],"answer":0,"explain":"Прошлое отрицание: 没 + глагол, без 了."}],"homework":"Сделайте финальную самопроверку: напишите мини-диалог из 6 реплик с датой, временем начала, ценой и номером телефона. Используйте не менее трёх разных конструкций модуля."}]}],"roadmap":[{"module":4,"hsk":"HSK1","title":"Семья и описание людей","summary":"Родственники, внешность и характер, притяжательные конструкции."},{"module":5,"hsk":"HSK2","title":"Еда и ресторан","summary":"Заказ блюд, вкусы, счёт в кафе и вежливые просьбы."},{"module":6,"hsk":"HSK2","title":"Покупки и деньги","summary":"Цены, торг, размеры и цвета, оплата покупок."},{"module":7,"hsk":"HSK2","title":"Транспорт и направления","summary":"Метро, такси, дорога до места и предлоги направления."},{"module":8,"hsk":"HSK2","title":"Работа и учёба","summary":"Профессии, расписание, учёба и рабочие диалоги."},{"module":9,"hsk":"HSK3","title":"Путешествия","summary":"Отель, билеты, планы поездки и рассказ о путешествии."},{"module":10,"hsk":"HSK3","title":"Здоровье и самочувствие","summary":"У врача, симптомы, советы и просьбы о помощи."},{"module":11,"hsk":"HSK3","title":"Хобби и свободное время","summary":"Интересы, спорт, кино и приглашения куда-то пойти."},{"module":12,"hsk":"HSK3","title":"Подготовка к HSK 3","summary":"Структура экзамена, стратегии и тренировочные варианты."}]};
